INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C1','math',4,2,'u2',2,'수직 — 두 직선이 만나서 이루는 각이 직각일 때 두 직선은 서로 수직이며, 놓인 방향이 아니라 만나서 이루는 각으로 정한다',ARRAY['4수02-06']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C2','math',4,2,'u2',2,'수선과 수선 긋기 — 두 직선이 수직일 때 한 직선을 다른 직선에 대한 수선이라 하고, 삼각자의 직각 부분이나 각도기의 90°로 수선을 긋는다',ARRAY['4수02-06']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C3','math',4,2,'u2',3,'평행과 평행선 — 한 직선에 수직인 두 직선처럼 아무리 늘여도 만나지 않는 두 직선은 서로 평행하고, 평행한 두 직선을 평행선이라 하며, 공통의 수선으로 확인한다',ARRAY['4수02-06']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C4','math',4,2,'u2',4,'평행선 사이의 거리 — 평행선의 한 직선에서 다른 직선에 그은 수직인 선분의 길이로, 가장 짧고 어디에서 재어도 같다',ARRAY['4수02-06']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C5','math',4,2,'u2',5,'사다리꼴 — 평행한 변이 한 쌍이라도 있는 사각형으로, 평행한 변이 두 쌍인 사각형도 사다리꼴이다',ARRAY['4수02-07']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C6','math',4,2,'u2',6,'평행사변형 — 마주 보는 두 쌍의 변이 서로 평행한 사각형으로, 기울어져 있지 않아도(직사각형·정사각형도) 평행사변형이다',ARRAY['4수02-07']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C7','math',4,2,'u2',6,'평행사변형의 성질 — 마주 보는 두 변의 길이가 같고, 마주 보는 두 각의 크기가 같으며, 이웃한 두 각의 크기의 합이 180°이다',ARRAY['4수02-07']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C8','math',4,2,'u2',7,'마름모와 그 성질 — 네 변의 길이가 모두 같은 사각형으로, 마주 보는 두 쌍의 변이 평행하고 마주 보는 각이 같으며, 마주 보는 꼭짓점끼리 이은 두 선분은 수직으로 만나 서로를 반으로 나눈다',ARRAY['4수02-07']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C9','math',4,2,'u2',8,'여러 가지 사각형의 관계 — 직사각형·정사각형의 성질을 알고, 기준(평행한 변·변의 길이·각의 크기)에 따라 한 사각형이 여러 이름으로 불릴 수 있음을 알기',ARRAY['4수02-07']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C10','math',4,2,'u2',9,'조건에 맞는 사각형 그리기 — 크기가 같은 두 원의 중심과 만나는 점을 이어 마름모를 그리고(네 변이 모두 반지름), 평행선·같은 길이를 이용해 여러 가지 사각형을 그리기',ARRAY['4수02-07']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X01','math',4,'u2',ARRAY['M4-2-u2-C1','M4-2-u2-C2','M4-2-u2-C3']::text[],'옆으로·위아래로 반듯하게 놓인 선만 수직·수선이라고 생각한다 — 기울어진 직선끼리 직각으로 만나면 수직이 아니라고 한다','놓인 방향 말고 만나서 이루는 각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X02','math',4,'u2',ARRAY['M4-2-u2-C1','M4-2-u2-C2','M4-2-u2-C3']::text[],'관계를 나타내는 말(수직·평행)과 직선을 가리키는 말(수선·평행선)을 섞어 쓴다','수직·평행은 관계, 수선·평행선은 직선') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X03','math',4,'u2',ARRAY['M4-2-u2-C1','M4-2-u2-C2']::text[],'직각에 가까운 각으로 만나도 수직이라고 눈대중한다 — 삼각자를 대어 확인하지 않는다','삼각자를 대어 직각인지 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X04','math',4,'u2',ARRAY['M4-2-u2-C2','M4-2-u2-C3']::text[],'한 직선에 대한 수선·평행선은 하나뿐이라고 생각하거나, 한 점을 지나는 수선·평행선이 여러 개라고 생각한다','한 직선에는 셀 수 없이 많이, 한 점을 지나면 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X05','math',4,'u2',ARRAY['M4-2-u2-C3']::text[],'그림 안에서 만나지 않으면 평행이라고 생각한다 — 늘이면 만나는 두 직선도 평행이라고 한다','끝없이 늘여 보기·공통의 수선') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X06','math',4,'u2',ARRAY['M4-2-u2-C3','M4-2-u2-C5','M4-2-u2-C6']::text[],'기울어져 있거나 길이가 다르거나 멀리 떨어진 두 직선(변)은 평행하지 않다고 생각한다','방향·길이가 아니라 만나는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X07','math',4,'u2',ARRAY['M4-2-u2-C4']::text[],'평행선 사이의 거리를 비스듬한 선분이나 가장 긴 선분의 길이로 잰다','수직인 선분의 길이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X08','math',4,'u2',ARRAY['M4-2-u2-C4']::text[],'평행선 사이의 거리가 재는 자리마다 다르다고 생각한다','어디에서 재어도 같다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X09','math',4,'u2',ARRAY['M4-2-u2-C5','M4-2-u2-C9']::text[],'사다리꼴은 평행한 변이 「한 쌍만」 있어야 한다고 생각한다 — 평행사변형·직사각형은 사다리꼴이 아니라고 한다','한 쌍이라도 있으면 사다리꼴') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X10','math',4,'u2',ARRAY['M4-2-u2-C5','M4-2-u2-C6','M4-2-u2-C9']::text[],'사각형의 이름을 모양(위가 좁은 사다리 모양·비스듬히 기운 모양)으로 정한다 — 평행한 변을 확인하지 않는다','평행한 변이 몇 쌍인지 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X11','math',4,'u2',ARRAY['M4-2-u2-C6','M4-2-u2-C9']::text[],'평행사변형은 비스듬히 기울어져 있어야 한다고 생각한다 — 직사각형·정사각형은 평행사변형이 아니라고 한다','마주 보는 두 쌍의 변이 평행하면 평행사변형') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X12','math',4,'u2',ARRAY['M4-2-u2-C7','M4-2-u2-C8','M4-2-u2-C9']::text[],'마주 보는 각과 이웃한 각을 섞는다 — 이웃한 두 각이 같다고 하거나 이웃한 두 각의 합을 90°·360°로 계산한다','마주 보는 각은 같고, 이웃한 두 각의 합은 180°') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X14','math',4,'u2',ARRAY['M4-2-u2-C7','M4-2-u2-C8']::text[],'평행사변형은 네 변의 길이가 모두 같다고 생각하거나, 마름모를 다이아몬드처럼 세워 놓인 모양으로만 안다','변의 길이를 재어 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X15','math',4,'u2',ARRAY['M4-2-u2-C8']::text[],'마름모의 마주 보는 꼭짓점끼리 이은 두 선분이 길이가 같다고 하거나, 수직으로 만나지 않는다·반으로 나누지 않는다고 생각한다','두 선분은 수직으로 만나 서로를 반으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X16','math',4,'u2',ARRAY['M4-2-u2-C8','M4-2-u2-C9']::text[],'사각형 사이의 관계를 거꾸로 안다 — 마름모는 모두 정사각형, 사다리꼴은 모두 평행사변형, 직사각형은 모두 정사각형이라고 한다','정사각형 → 마름모(거꾸로는 아님)') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X17','math',4,'u2',ARRAY['M4-2-u2-C5','M4-2-u2-C6','M4-2-u2-C8','M4-2-u2-C9']::text[],'한 사각형에는 이름이 하나뿐이라고 생각한다 — 정사각형은 마름모·직사각형이 아니라고 한다','기준마다 이름이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X18','math',4,'u2',ARRAY['M4-2-u2-C1','M4-2-u2-C2','M4-2-u2-C3','M4-2-u2-C4','M4-2-u2-C5','M4-2-u2-C6','M4-2-u2-C7','M4-2-u2-C8','M4-2-u2-C9','M4-2-u2-C10']::text[],'묻는 말을 거꾸로 읽는다 — 아닌 것↔맞는 것, 잘못 말한↔바르게 말한','물음의 「아닌·잘못」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X19','math',4,'u2',ARRAY['M4-2-u2-C10']::text[],'두 원으로 그린 사각형의 변이 반지름임을 놓친다 — 크기가 다른 두 원으로도 마름모가 된다고 하거나 지름을 변의 길이로 잡는다','네 변이 모두 반지름인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_basic#1','math',4,2,'u2','L02','g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C1',1,'mc','auto','두 직선이 만나서 이루는 각이 직각일 때, 두 직선은 서로 어떤 관계라고 하나요?',ARRAY['M4-2-u2-X05','M4-2-u2-X02']::text[],true,'{"seq":1,"concept":"M4-2-u2-C1","difficulty":1,"kind":"mc","stem":"두 직선이 만나서 이루는 각이 직각일 때, 두 직선은 서로 어떤 관계라고 하나요?","options":[{"t":"수직","correct":true},{"t":"평행","mis":"M4-2-u2-X05"},{"t":"수선","mis":"M4-2-u2-X02"},{"t":"평행선","mis":"M4-2-u2-X02"}],"explanation":["두 직선이 만나서 이루는 각이 직각이면 두 직선은 서로 수직이에요.","이때 한 직선을 다른 직선에 대한 수선이라고 해요.","수직은 두 직선의 관계, 수선은 한 직선을 가리키는 말이에요."],"variant_rule":{"alt":[{"stem":"두 직선이 서로 수직일 때, 한 직선을 다른 직선에 대한 무엇이라고 하나요?","options":[{"t":"수선","correct":true},{"t":"수직","mis":"M4-2-u2-X02"},{"t":"평행선","mis":"M4-2-u2-X05"},{"t":"반직선","mis":"M4-2-u2-X02"}],"explanation":["두 직선이 만나서 이루는 각이 직각이면 두 직선은 서로 수직이에요.","이때 한 직선을 다른 직선에 대한 수선이라고 해요.","수직은 두 직선의 관계, 수선은 한 직선을 가리키는 말이에요."],"asset":null},{"stem":"주차장의 주차선 가와 주차선 나가 만나서 이루는 각이 직각이에요. 주차선 나는 주차선 가에 대한 무엇인가요?","options":[{"t":"수선","correct":true},{"t":"수직","mis":"M4-2-u2-X02"},{"t":"평행선","mis":"M4-2-u2-X05"},{"t":"직각","mis":"M4-2-u2-X02"}],"explanation":["두 직선이 만나서 이루는 각이 직각이면 두 직선은 서로 수직이에요.","이때 한 직선을 다른 직선에 대한 수선이라고 해요.","수직은 두 직선의 관계, 수선은 한 직선을 가리키는 말이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_basic#2','math',4,2,'u2','L02','g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C1',1,'sa','auto','두 직선이 서로 수직으로 만날 때 이루는 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u2-C1","difficulty":1,"kind":"sa","stem":"두 직선이 서로 수직으로 만날 때 이루는 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["수직은 만나서 이루는 각이 직각인 관계예요.","직각은 90°예요.","그래서 수직인 두 직선이 이루는 각은 90°예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,75.0],[150.0,75.0]],[[30.0,0.0],[30.0,105.0]]],"lab":[[[136.5,63.75],"가"],[[18.75,13.5],"나"]],"right":[[[150.0,75.0],[30.0,75.0],[30.0,105.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직선 나는 직선 가에 대한 수선이에요. 두 직선이 만나서 이루는 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["수직은 만나서 이루는 각이 직각인 관계예요.","직각은 90°예요.","그래서 수직인 두 직선이 이루는 각은 90°예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,30.0],[135.0,75.0]],[[30.0,105.0],[60.0,15.0]]],"lab":[[[9.249662155992509,44.94176194429559],"가"],[[44.94176194429559,95.75033784400749],"나"]],"right":[[[135.0,75.0],[49.5,46.5],[60.0,15.0]]]}],"tag":false}},{"stem":"주차선 두 줄이 서로 수직으로 만나요. 두 주차선이 만나서 이루는 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["수직은 만나서 이루는 각이 직각인 관계예요.","직각은 90°예요.","그래서 수직인 두 직선이 이루는 각은 90°예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,105.0],[105.0,0.0]],[[15.0,0.0],[120.0,105.0]]],"lab":[[[103.40900974233026,17.500892834367054],"가"],[[16.59099025766973,17.500892834367054],"나"]],"right":[[[105.0,0.0],[60.0,45.0],[120.0,105.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_basic#3','math',4,2,'u2','L02','g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C1',1,'mc','auto','두 직선이 서로 수직인지 알아보려면 삼각자의 어느 부분을 대어 보나요?',ARRAY['M4-2-u2-X03']::text[],true,'{"seq":3,"concept":"M4-2-u2-C1","difficulty":1,"kind":"mc","stem":"두 직선이 서로 수직인지 알아보려면 삼각자의 어느 부분을 대어 보나요?","options":[{"t":"직각 부분","correct":true},{"t":"가장 긴 변","mis":"M4-2-u2-X03"},{"t":"가장 뾰족한 각 부분","mis":"M4-2-u2-X03"},{"t":"대어 보지 않고 눈으로 본다","mis":"M4-2-u2-X03"}],"explanation":["수직은 만나서 이루는 각이 직각인지로 정해요.","삼각자의 직각 부분을 대거나 각도기로 90°인지 재어 확인해요.","눈대중이나 놓인 방향으로는 정할 수 없어요."],"variant_rule":{"alt":[{"stem":"각도기로 두 직선이 서로 수직인지 알아보려면 만나서 이루는 각이 몇 도인지 보면 되나요?","options":[{"t":"90°","correct":true},{"t":"180°","mis":"M4-2-u2-X03"},{"t":"60°","mis":"M4-2-u2-X03"},{"t":"45°","mis":"M4-2-u2-X03"}],"explanation":["수직은 만나서 이루는 각이 직각인지로 정해요.","삼각자의 직각 부분을 대거나 각도기로 90°인지 재어 확인해요.","눈대중이나 놓인 방향으로는 정할 수 없어요."],"asset":null},{"stem":"주차선이 서로 수직인지 가장 바르게 확인하는 방법은 어느 것인가요?","options":[{"t":"만나는 곳에 삼각자의 직각 부분을 대어 본다","correct":true},{"t":"두 선이 반듯해 보이는지 눈으로 본다","mis":"M4-2-u2-X03"},{"t":"두 선의 길이를 자로 잰다","mis":"M4-2-u2-X02"},{"t":"한 선이 가로로 놓였는지 본다","mis":"M4-2-u2-X01"}],"explanation":["수직은 만나서 이루는 각이 직각인지로 정해요.","삼각자의 직각 부분을 대거나 각도기로 90°인지 재어 확인해요.","눈대중이나 놓인 방향으로는 정할 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
