INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_basic#6','math',4,2,'u2','L02','g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C1',2,'ox','auto','직선 나는 직선 가에 대한 수선이에요.',ARRAY['M4-2-u2-X01']::text[],true,'{"seq":6,"concept":"M4-2-u2-C1","difficulty":2,"kind":"ox","stem":"직선 나는 직선 가에 대한 수선이에요.","answer":"O","reason_options":[{"t":"기울어져 있어도 만나서 이루는 각이 직각이라서","correct":true},{"t":"옆으로·위아래로 반듯하게 놓이지 않아서","mis":"M4-2-u2-X01"}],"mis":"M4-2-u2-X01","explanation":["수직은 놓인 방향이 아니라 만나서 이루는 각으로 정해요.","두 직선이 만나는 곳의 각이 직각이에요.","그래서 두 직선은 서로 수직이고, 한 직선은 다른 직선에 대한 수선이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,30.0],[135.0,75.0]],[[30.0,105.0],[60.0,15.0]]],"lab":[[[9.249662155992509,44.94176194429559],"가"],[[44.94176194429559,95.75033784400749],"나"]],"right":[[[135.0,75.0],[49.5,46.5],[60.0,15.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직선 가와 직선 나는 서로 수직이에요.","answer":"O","reason_options":[{"t":"기울어져 있어도 만나서 이루는 각이 직각이라서","correct":true},{"t":"옆으로·위아래로 반듯하게 놓이지 않아서","mis":"M4-2-u2-X01"}],"explanation":["수직은 놓인 방향이 아니라 만나서 이루는 각으로 정해요.","두 직선이 만나는 곳의 각이 직각이에요.","그래서 두 직선은 서로 수직이고, 한 직선은 다른 직선에 대한 수선이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,105.0],[105.0,0.0]],[[15.0,0.0],[120.0,105.0]]],"lab":[[[103.40900974233026,17.500892834367054],"가"],[[16.59099025766973,17.500892834367054],"나"]],"right":[[[105.0,0.0],[60.0,45.0],[120.0,105.0]]]}],"tag":false}},{"stem":"두 직선이 기울어져 있으니 서로 수직이 아니에요.","answer":"X","reason_options":[{"t":"기울어져 있어도 만나서 이루는 각이 직각이라서","correct":true},{"t":"옆으로·위아래로 반듯하게 놓이지 않아서","mis":"M4-2-u2-X01"}],"explanation":["수직은 놓인 방향이 아니라 만나서 이루는 각으로 정해요.","두 직선이 만나는 곳의 각이 직각이에요.","그래서 두 직선은 서로 수직이고, 한 직선은 다른 직선에 대한 수선이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,15.0],[150.0,90.0]],[[15.0,105.0],[60.0,15.0]]],"lab":[[[7.043614129124338,31.099689437998485],"가"],[[31.099689437998485,97.95638587087565],"나"]],"right":[[[150.0,90.0],[48.0,39.0],[60.0,15.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_basic#7','math',4,2,'u2','L02','g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C2',2,'mc','auto','수직과 수선에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['M4-2-u2-X02','M4-2-u2-X01','M4-2-u2-X04']::text[],true,'{"seq":7,"concept":"M4-2-u2-C2","difficulty":2,"kind":"mc","stem":"수직과 수선에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"수직은 두 직선의 관계를, 수선은 한 직선을 가리키는 말이에요","correct":true},{"t":"수선은 두 직선의 관계를 나타내는 말이에요","mis":"M4-2-u2-X02"},{"t":"옆으로 반듯하게 그은 선만 수선이 될 수 있어요","mis":"M4-2-u2-X01"},{"t":"한 직선에 대한 수선은 하나뿐이에요","mis":"M4-2-u2-X04"}],"explanation":["두 직선이 만나서 이루는 각이 직각이면 서로 수직, 이때 한 직선은 다른 직선에 대한 수선이에요.","수선은 놓인 방향과 상관없고, 한 직선에 셀 수 없이 많이 그을 수 있어요.","선분끼리 직각으로 만나도 서로 수직이에요."],"variant_rule":{"alt":[{"stem":"수직과 수선에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"한 직선에 대한 수선은 셀 수 없이 많이 그을 수 있어요","correct":true},{"t":"한 직선에 대한 수선은 하나만 그을 수 있어요","mis":"M4-2-u2-X04"},{"t":"직각에 가깝게 만나도 수선이에요","mis":"M4-2-u2-X03"},{"t":"수직인 두 직선은 서로 만나지 않아요","mis":"M4-2-u2-X05"}],"explanation":["두 직선이 만나서 이루는 각이 직각이면 서로 수직, 이때 한 직선은 다른 직선에 대한 수선이에요.","수선은 놓인 방향과 상관없고, 한 직선에 셀 수 없이 많이 그을 수 있어요.","선분끼리 직각으로 만나도 서로 수직이에요."],"asset":null},{"stem":"수직과 수선에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"선분과 선분이 만나서 이루는 각이 직각일 때도 서로 수직이라고 해요","correct":true},{"t":"수직은 직선끼리만 쓰는 말이에요","mis":"M4-2-u2-X02"},{"t":"기울어진 두 선분은 수직일 수 없어요","mis":"M4-2-u2-X01"},{"t":"수직인 두 선분은 길이가 같아야 해요","mis":"M4-2-u2-X06"}],"explanation":["두 직선이 만나서 이루는 각이 직각이면 서로 수직, 이때 한 직선은 다른 직선에 대한 수선이에요.","수선은 놓인 방향과 상관없고, 한 직선에 셀 수 없이 많이 그을 수 있어요.","선분끼리 직각으로 만나도 서로 수직이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_basic#8','math',4,2,'u2','L02','g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C2',2,'mc','auto','점 ㄱ을 지나고 직선 가에 대한 수선을 바르게 긋는 방법은 어느 것인가요?',ARRAY['M4-2-u2-X03','M4-2-u2-X05','M4-2-u2-X01']::text[],true,'{"seq":8,"concept":"M4-2-u2-C2","difficulty":2,"kind":"mc","stem":"점 ㄱ을 지나고 직선 가에 대한 수선을 바르게 긋는 방법은 어느 것인가요?","options":[{"t":"삼각자의 직각을 낀 한 변을 직선 가에 맞추고, 직각을 낀 다른 변을 따라 선을 긋는다","correct":true},{"t":"삼각자의 60° 부분을 직선 가에 맞추고 선을 긋는다","mis":"M4-2-u2-X03"},{"t":"직선 가와 만나지 않게 나란히 선을 긋는다","mis":"M4-2-u2-X05"},{"t":"종이의 위아래 방향으로 선을 긋는다","mis":"M4-2-u2-X01"}],"explanation":["수선은 직선 가와 만나서 이루는 각이 직각이 되게 그어요.","삼각자의 직각 부분을 쓰거나 각도기로 90°를 재어 그어요.","60°·45°로 그으면 수선이 아니에요."],"variant_rule":{"alt":[{"stem":"점 ㄱ을 지나고 직선 가에 대한 수선을 바르게 긋는 방법은 어느 것인가요?","options":[{"t":"각도기의 중심을 점 ㄱ에 맞추고 90°가 되는 눈금에 점을 찍어 점 ㄱ과 잇는다","correct":true},{"t":"각도기의 중심을 점 ㄱ에 맞추고 45°가 되는 눈금에 점을 찍어 잇는다","mis":"M4-2-u2-X03"},{"t":"각도기 없이 점 ㄱ에서 비스듬히 선을 긋는다","mis":"M4-2-u2-X03"},{"t":"각도기의 밑금을 직선 가와 겹치지 않게 놓고 긋는다","mis":"M4-2-u2-X03"}],"explanation":["수선은 직선 가와 만나서 이루는 각이 직각이 되게 그어요.","삼각자의 직각 부분을 쓰거나 각도기로 90°를 재어 그어요.","60°·45°로 그으면 수선이 아니에요."],"asset":null},{"stem":"점 ㄱ을 지나고 직선 가에 대한 수선을 바르게 긋는 방법은 어느 것인가요?","options":[{"t":"삼각자의 직각 부분이 직선 가 위의 점 ㄱ에 오도록 대고 선을 긋는다","correct":true},{"t":"삼각자의 가장 긴 변을 직선 가에 대고 그 변을 따라 긋는다","mis":"M4-2-u2-X03"},{"t":"직선 가와 겹치게 선을 긋는다","mis":"M4-2-u2-X02"},{"t":"점 ㄱ에서 아무 방향으로나 선을 긋는다","mis":"M4-2-u2-X03"}],"explanation":["수선은 직선 가와 만나서 이루는 각이 직각이 되게 그어요.","삼각자의 직각 부분을 쓰거나 각도기로 90°를 재어 그어요.","60°·45°로 그으면 수선이 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_basic#9','math',4,2,'u2','L02','g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C1',2,'mc','auto','사각형 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 수직인 변을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X04','M4-2-u2-X06','M4-2-u2-X03']::text[],true,'{"seq":9,"concept":"M4-2-u2-C1","difficulty":2,"kind":"mc","stem":"사각형 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 수직인 변을 모두 고른 것은 어느 것인가요?","options":[{"t":"변 ㄴㄷ, 변 ㄹㄱ","correct":true},{"t":"변 ㄴㄷ","mis":"M4-2-u2-X04"},{"t":"변 ㄷㄹ","mis":"M4-2-u2-X06"},{"t":"변 ㄴㄷ, 변 ㄷㄹ, 변 ㄹㄱ","mis":"M4-2-u2-X03"}],"explanation":["변 ㄱㄴ과 만나서 이루는 각이 직각인 변을 찾아요.","변 ㄴㄷ, 변 ㄹㄱ — 모눈으로 보면 직각으로 만나요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,15.0],"ㄴ":[120.0,15.0],"ㄷ":[120.0,75.0],"ㄹ":[15.0,75.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"사각형 ㄱㄴㄷㄹ에서 변 ㄴㄷ과 수직인 변을 모두 고른 것은 어느 것인가요?","options":[{"t":"변 ㄱㄴ, 변 ㄷㄹ","correct":true},{"t":"변 ㄱㄴ","mis":"M4-2-u2-X04"},{"t":"변 ㄹㄱ","mis":"M4-2-u2-X06"},{"t":"변 ㄱㄴ, 변 ㄷㄹ, 변 ㄹㄱ","mis":"M4-2-u2-X03"}],"explanation":["변 ㄴㄷ과 만나서 이루는 각이 직각인 변을 찾아요.","변 ㄱㄴ, 변 ㄷㄹ — 모눈으로 보면 직각으로 만나요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[120.0,75.0],"ㄷ":[120.0,15.0],"ㄹ":[60.0,15.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}},{"stem":"사각형 ㅁㅂㅅㅇ에서 변 ㅅㅇ과 수직인 변을 모두 고른 것은 어느 것인가요?","options":[{"t":"변 ㅂㅅ, 변 ㅇㅁ","correct":true},{"t":"변 ㅂㅅ","mis":"M4-2-u2-X04"},{"t":"변 ㅁㅂ","mis":"M4-2-u2-X06"},{"t":"변 ㅁㅂ, 변 ㅂㅅ, 변 ㅇㅁ","mis":"M4-2-u2-X03"}],"explanation":["변 ㅅㅇ과 만나서 이루는 각이 직각인 변을 찾아요.","변 ㅂㅅ, 변 ㅇㅁ — 모눈으로 보면 직각으로 만나요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[45.0,7.5],"ㅂ":[90.0,37.5],"ㅅ":[60.0,82.5],"ㅇ":[15.0,52.5]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_basic#10','math',4,2,'u2','L02','g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C1',3,'sa','auto','점 ㅇ에서 수직인 두 직선 사이에 반직선을 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u2-C1","difficulty":3,"kind":"sa","stem":"점 ㅇ에서 수직인 두 직선 사이에 반직선을 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["두 직선이 수직이라 만나서 이루는 각은 90°예요.","90°가 35°와 ㉠으로 나뉘었어요.","㉠ = 90° − 35° = 55°예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"line":[[[30.0,90.0],[120.0,90.0]]],"ray":[[[30.0,90.0],[30.0,7.5]],[[30.0,90.0],[138.0,18.000000000000004]]],"right":[[[75.0,90.0],[30.0,90.0],[30.0,45.0]]],"lab":[[[77.3760637639512,75.65571255746626],"35°"],[[53.35699303151151,46.357121124679196],"㉠"]],"pts":{"ㅇ":[30.0,90.0]},"show":["ㅇ"]}],"tag":false},"variant_rule":{"alt":[{"stem":"주차선 두 줄이 수직으로 만나는 점 ㅇ에서 비스듬한 안내선을 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["두 직선이 수직이라 만나서 이루는 각은 90°예요.","90°가 65°와 ㉠으로 나뉘었어요.","㉠ = 90° − 65° = 25°예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"line":[[[30.0,90.0],[120.0,90.0]]],"ray":[[[30.0,90.0],[30.0,7.5]],[[30.0,90.0],[102.0,54.0]]],"right":[[[75.0,90.0],[30.0,90.0],[30.0,45.0]]],"lab":[[[78.17533378216905,78.62514989212599],"㉠"],[[56.02187155703885,47.891661150444655],"65°"]],"pts":{"ㅇ":[30.0,90.0]},"show":["ㅇ"]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점 ㅇ에서 수직인 두 직선 사이에 반직선을 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["두 직선이 수직이라 만나서 이루는 각은 90°예요.","90°가 65°와 ㉠으로 나뉘었어요.","㉠ = 90° − 65° = 25°예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"line":[[[30.0,90.0],[120.0,90.0]]],"ray":[[[30.0,90.0],[30.0,7.5]],[[30.0,90.0],[66.0,18.000000000000004]]],"right":[[[75.0,90.0],[30.0,90.0],[30.0,45.0]]],"lab":[[[72.10833884955535,63.97812844296115],"65°"],[[41.37485010787402,41.82466621783095],"㉠"]],"pts":{"ㅇ":[30.0,90.0]},"show":["ㅇ"]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_challenge#1','math',4,2,'u2','L02','g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C2',2,'mc','auto','직선 가에 대한 수선을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X03','M4-2-u2-X18']::text[],true,'{"seq":1,"concept":"M4-2-u2-C2","difficulty":2,"kind":"mc","stem":"직선 가에 대한 수선을 모두 고른 것은 어느 것인가요?","options":[{"t":"직선 나","correct":true},{"t":"직선 나, 직선 다","mis":"M4-2-u2-X03"},{"t":"직선 다, 직선 라","mis":"M4-2-u2-X18"},{"t":"직선 다","mis":"M4-2-u2-X03"}],"explanation":["직선 가와 만나서 이루는 각이 직각인 직선을 찾아요.","직선 나 — 모두 직선 가와 직각으로 만나요.","직각에 가깝기만 한 직선이나 직선 가와 평행한 직선은 수선이 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,105.0],[105.0,0.0]],[[15.0,0.0],[120.0,105.0]],[[150.0,30.0],[60.0,105.0]],[[0.0,45.0],[150.0,45.0]]],"lab":[[[103.40900974233026,17.500892834367054],"가"],[[16.59099025766973,17.500892834367054],"나"],[[63.16891277833918,87.71502120905905],"다"],[[13.5,56.25],"라"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 직선 가에 대한 수선을 모두 고른 것은 어느 것인가요?","options":[{"t":"직선 나, 직선 다","correct":true},{"t":"직선 나","mis":"M4-2-u2-X04"},{"t":"직선 나, 직선 다, 직선 라","mis":"M4-2-u2-X03"},{"t":"직선 라","mis":"M4-2-u2-X18"}],"explanation":["직선 가와 만나서 이루는 각이 직각인 직선을 찾아요.","직선 나, 직선 다 — 모두 직선 가와 직각으로 만나요.","직각에 가깝기만 한 직선이나 직선 가와 평행한 직선은 수선이 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,90.0],[150.0,15.0]],[[30.0,15.0],[67.5,90.0]],[[75.0,0.0],[120.0,90.0]],[[105.0,0.0],[105.0,105.0]]],"lab":[[[17.105920027873392,94.02492235949961],"가"],[[18.47507764050038,17.105920027873392],"나"],[[70.97507764050039,17.105920027873392],"다"],[[93.75,91.5],"라"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 직선 가에 대한 수선을 모두 고른 것은 어느 것인가요?","options":[{"t":"직선 나, 직선 라","correct":true},{"t":"직선 나","mis":"M4-2-u2-X04"},{"t":"직선 나, 직선 다, 직선 라","mis":"M4-2-u2-X03"},{"t":"직선 다","mis":"M4-2-u2-X18"}],"explanation":["직선 가와 만나서 이루는 각이 직각인 직선을 찾아요.","직선 나, 직선 라 — 모두 직선 가와 직각으로 만나요.","직각에 가깝기만 한 직선이나 직선 가와 평행한 직선은 수선이 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,75.0],[150.0,75.0]],[[30.0,0.0],[30.0,105.0]],[[60.0,105.0],[105.0,0.0]],[[120.0,0.0],[120.0,105.0]]],"lab":[[[13.5,86.25],"가"],[[18.75,13.5],"나"],[[75.65829211852191,97.02313420377185],"다"],[[131.25,13.5],"라"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_challenge#2','math',4,2,'u2','L02','g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C2',2,'ox','auto','직선 가에 대한 수선은 하나만 그을 수 있어요.',ARRAY['M4-2-u2-X04']::text[],true,'{"seq":2,"concept":"M4-2-u2-C2","difficulty":2,"kind":"ox","stem":"직선 가에 대한 수선은 하나만 그을 수 있어요.","answer":"X","reason_options":[{"t":"직선 가 위의 어느 점에서나 수선을 그을 수 있어서","correct":true},{"t":"한 직선에는 수선이 하나뿐이라서","mis":"M4-2-u2-X04"}],"mis":"M4-2-u2-X04","explanation":["수선은 직선 가와 직각으로 만나는 직선이에요.","직선 가 위의 점은 셀 수 없이 많고, 점마다 수선을 하나씩 그을 수 있어요.","그래서 직선 가에 대한 수선은 셀 수 없이 많지만, 한 점을 지나는 수선은 하나예요."],"variant_rule":{"alt":[{"stem":"점 ㄱ을 지나고 직선 가에 수직인 직선은 하나뿐이에요.","answer":"O","reason_options":[{"t":"한 점을 지나며 직선 가와 직각으로 만나는 직선은 하나뿐이라서","correct":true},{"t":"한 점을 지나는 수선도 셀 수 없이 많아서","mis":"M4-2-u2-X04"}],"explanation":["수선은 직선 가와 직각으로 만나는 직선이에요.","직선 가 위의 점은 셀 수 없이 많고, 점마다 수선을 하나씩 그을 수 있어요.","그래서 직선 가에 대한 수선은 셀 수 없이 많지만, 한 점을 지나는 수선은 하나예요."],"asset":null},{"stem":"직선 가에 대한 수선은 셀 수 없이 많이 그을 수 있어요.","answer":"O","reason_options":[{"t":"직선 가 위의 점마다 수선을 그을 수 있어서","correct":true},{"t":"수선은 직선 가와 만나는 한 곳에만 그을 수 있어서","mis":"M4-2-u2-X04"}],"explanation":["수선은 직선 가와 직각으로 만나는 직선이에요.","직선 가 위의 점은 셀 수 없이 많고, 점마다 수선을 하나씩 그을 수 있어요.","그래서 직선 가에 대한 수선은 셀 수 없이 많지만, 한 점을 지나는 수선은 하나예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_challenge#3','math',4,2,'u2','L02','g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C2',3,'sa','auto','그림에서 직선 가에 대한 수선은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u2-C2","difficulty":3,"kind":"sa","stem":"그림에서 직선 가에 대한 수선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["직선 가와 만나서 이루는 각이 직각인 직선을 찾아요.","직선 나, 직선 라가 직선 가와 직각으로 만나요.","직선 가에 대한 수선은 2개예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,15.0],[150.0,90.0]],[[15.0,105.0],[60.0,15.0]],[[90.0,105.0],[120.0,0.0]],[[105.0,105.0],[150.0,15.0]]],"lab":[[[7.043614129124338,31.099689437998485],"가"],[[31.099689437998485,97.95638587087565],"나"],[[82.89159081565535,88.9288140180034],"다"],[[121.09968943799848,97.95638587087565],"라"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 그림에서 직선 가에 대한 수선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["직선 가와 만나서 이루는 각이 직각인 직선을 찾아요.","직선 나가 직선 가와 직각으로 만나요.","직선 가에 대한 수선은 1개예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,105.0],[105.0,0.0]],[[15.0,0.0],[120.0,105.0]],[[150.0,30.0],[60.0,105.0]],[[0.0,45.0],[150.0,45.0]]],"lab":[[[103.40900974233026,17.500892834367054],"가"],[[16.59099025766973,17.500892834367054],"나"],[[63.16891277833918,87.71502120905905],"다"],[[13.5,56.25],"라"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 그림에서 직선 가에 대한 수선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["직선 가와 만나서 이루는 각이 직각인 직선을 찾아요.","직선 나, 직선 다가 직선 가와 직각으로 만나요.","직선 가에 대한 수선은 2개예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,90.0],[150.0,15.0]],[[30.0,15.0],[67.5,90.0]],[[75.0,0.0],[120.0,90.0]],[[105.0,0.0],[105.0,105.0]]],"lab":[[[17.105920027873392,94.02492235949961],"가"],[[18.47507764050038,17.105920027873392],"나"],[[70.97507764050039,17.1059200