INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_challenge#4','math',4,2,'u2','L02','g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C1',3,'sa','auto','계단 난간을 따라 선분을 이어 그렸어요. 이웃한 두 선분이 서로 수직으로 만나는 곳은 모두 몇 군데인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u2-C1","difficulty":3,"kind":"sa","stem":"계단 난간을 따라 선분을 이어 그렸어요. 이웃한 두 선분이 서로 수직으로 만나는 곳은 모두 몇 군데인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["선분이 꺾이는 곳 5군데를 하나씩 살펴봐요.","모눈을 따라 직각으로 꺾인 곳만 세요.","서로 수직으로 만나는 곳은 5군데예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"grid":15,"seg":[[[15.0,90.0],[15.0,60.0]],[[15.0,60.0],[45.0,60.0]],[[45.0,60.0],[45.0,30.0]],[[45.0,30.0],[75.0,30.0]],[[75.0,30.0],[75.0,7.5]],[[75.0,7.5],[120.0,7.5]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"곧은 선분을 이어 그린 길이에요. 이웃한 두 선분이 서로 수직으로 만나는 곳은 모두 몇 군데인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["선분이 꺾이는 곳 3군데를 하나씩 살펴봐요.","모눈을 따라 직각으로 꺾인 곳만 세요.","서로 수직으로 만나는 곳은 3군데예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"grid":15,"seg":[[[15.0,15.0],[60.0,15.0]],[[60.0,15.0],[60.0,45.0]],[[60.0,45.0],[105.0,45.0]],[[105.0,45.0],[105.0,90.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 계단 난간을 따라 선분을 이어 그렸어요. 이웃한 두 선분이 서로 수직으로 만나는 곳은 모두 몇 군데인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["선분이 꺾이는 곳 3군데를 하나씩 살펴봐요.","모눈을 따라 직각으로 꺾인 곳만 세요 — 비스듬히 꺾여 직각이 아닌 곳은 빼요.","서로 수직으로 만나는 곳은 2군데예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"grid":15,"seg":[[[15.0,90.0],[30.0,45.0]],[[30.0,45.0],[75.0,45.0]],[[75.0,45.0],[75.0,15.0]],[[75.0,15.0],[120.0,15.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_challenge#5','math',4,2,'u2','L02','g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C1',3,'error','auto','그림을 보고 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u2-X01','M4-2-u2-X18']::text[],true,'{"seq":5,"concept":"M4-2-u2-C1","difficulty":3,"kind":"error","stem":"그림을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「직선 라는 기울어져 있어서 직선 가에 대한 수선이 아니야.」","correct":true,"mis_target":"M4-2-u2-X01"},{"t":"시우 — 「직선 나와 직선 가는 서로 수직이야.」","mis":"M4-2-u2-X18"},{"t":"은우 — 「직선 다는 직선 가에 대한 수선이 아니야.」","mis":"M4-2-u2-X18"},{"t":"하랑 — 「수선인지는 만나서 이루는 각으로 알아봐.」","mis":"M4-2-u2-X18"}],"explanation":["수선인지는 직선 가와 만나서 이루는 각이 직각인지로 정해요.","직선 라는 기울어져 있어도 직선 가와 직각으로 만나요.","그래서 직선 라도 직선 가에 대한 수선이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,30.0],[135.0,75.0]],[[30.0,105.0],[60.0,15.0]],[[75.0,105.0],[135.0,15.0]],[[90.0,105.0],[120.0,15.0]]],"lab":[[[9.249662155992509,44.94176194429559],"가"],[[44.94176194429559,95.75033784400749],"나"],[[78.95223889810475,78.79041572835791],"다"],[[110.05823805570442,9.249662155992509],"라"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 그림을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「직선 라는 기울어져 있어서 직선 가에 대한 수선이 아니야.」","correct":true,"mis_target":"M4-2-u2-X01"},{"t":"은우 — 「직선 나와 직선 가는 서로 수직이야.」","mis":"M4-2-u2-X18"},{"t":"하랑 — 「직선 다는 직선 가에 대한 수선이 아니야.」","mis":"M4-2-u2-X18"},{"t":"지아 — 「수선인지는 만나서 이루는 각으로 알아봐.」","mis":"M4-2-u2-X18"}],"explanation":["수선인지는 직선 가와 만나서 이루는 각이 직각인지로 정해요.","직선 라는 기울어져 있어도 직선 가와 직각으로 만나요.","그래서 직선 라도 직선 가에 대한 수선이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,15.0],[150.0,90.0]],[[15.0,105.0],[60.0,15.0]],[[90.0,105.0],[120.0,0.0]],[[105.0,105.0],[150.0,15.0]]],"lab":[[[7.043614129124338,31.099689437998485],"가"],[[31.099689437998485,97.95638587087565],"나"],[[82.89159081565535,88.9288140180034],"다"],[[121.09968943799848,97.95638587087565],"라"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 그림을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「직선 다는 기울어져 있어서 직선 가에 대한 수선이 아니야.」","correct":true,"mis_target":"M4-2-u2-X01"},{"t":"하랑 — 「직선 나와 직선 가는 서로 수직이야.」","mis":"M4-2-u2-X18"},{"t":"지아 — 「직선 라는 직선 가에 대한 수선이 아니야.」","mis":"M4-2-u2-X18"},{"t":"준서 — 「수선인지는 만나서 이루는 각으로 알아봐.」","mis":"M4-2-u2-X18"}],"explanation":["수선인지는 직선 가와 만나서 이루는 각이 직각인지로 정해요.","직선 다는 기울어져 있어도 직선 가와 직각으로 만나요.","그래서 직선 다도 직선 가에 대한 수선이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,90.0],[150.0,15.0]],[[30.0,15.0],[67.5,90.0]],[[75.0,0.0],[120.0,90.0]],[[105.0,0.0],[105.0,105.0]]],"lab":[[[17.105920027873392,94.02492235949961],"가"],[[18.47507764050038,17.105920027873392],"나"],[[70.97507764050039,17.105920027873392],"다"],[[93.75,91.5],"라"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_challenge#6','math',4,2,'u2','L02','g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C2',3,'sa','auto','삼각자의 한 각은 직각이에요. 직각이 아닌 두 각 가운데 한 각이 60°일 때, 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u2-C2","difficulty":3,"kind":"sa","stem":"삼각자의 한 각은 직각이에요. 직각이 아닌 두 각 가운데 한 각이 60°일 때, 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","직각이 90°이니 나머지 두 각의 합은 180° − 90° = 90°예요.","90° − 60° = 30°예요."],"variant_rule":{"alt":[{"stem":"삼각자의 한 각은 직각이에요. 직각이 아닌 두 각 가운데 한 각이 30°일 때, 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","직각이 90°이니 나머지 두 각의 합은 180° − 90° = 90°예요.","90° − 30° = 60°예요."],"asset":null},{"stem":"삼각자의 한 각은 직각이에요. 직각이 아닌 두 각 가운데 한 각이 45°일 때, 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","직각이 90°이니 나머지 두 각의 합은 180° − 90° = 90°예요.","90° − 45° = 45°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_challenge#7','math',4,2,'u2','L02','g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C1',3,'sa','auto','주차선 두 줄이 수직으로 만나는 점 ㅇ에서 비스듬한 안내선을 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u2-C1","difficulty":3,"kind":"sa","stem":"주차선 두 줄이 수직으로 만나는 점 ㅇ에서 비스듬한 안내선을 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["두 직선이 수직이라 만나서 이루는 각은 90°예요.","90°가 35°와 ㉠으로 나뉘었어요.","㉠ = 90° − 35° = 55°예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"line":[[[30.0,90.0],[120.0,90.0]]],"ray":[[[30.0,90.0],[30.0,7.5]],[[30.0,90.0],[102.0,-17.99999999999999]]],"right":[[[75.0,90.0],[30.0,90.0],[30.0,45.0]]],"lab":[[[73.6428788753208,66.6430069684885],"㉠"],[[44.34428744253374,42.62393623604881],"35°"]],"pts":{"ㅇ":[30.0,90.0]},"show":["ㅇ"]}],"tag":false},"variant_rule":{"alt":[{"stem":"점 ㅇ에서 수직인 두 직선 사이에 반직선을 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["두 직선이 수직이라 만나서 이루는 각은 90°예요.","90°가 70°와 ㉠으로 나뉘었어요.","㉠ = 90° − 70° = 20°예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"line":[[[30.0,90.0],[120.0,90.0]]],"ray":[[[30.0,90.0],[30.0,7.5]],[[30.0,90.0],[138.0,54.0]]],"right":[[[75.0,90.0],[30.0,90.0],[30.0,45.0]]],"lab":[[[78.86117153516517,82.07308911295429],"㉠"],[[58.94489328714291,49.844761828674095],"70°"]],"pts":{"ㅇ":[30.0,90.0]},"show":["ㅇ"]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 주차선 두 줄이 수직으로 만나는 점 ㅇ에서 비스듬한 안내선을 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["두 직선이 수직이라 만나서 이루는 각은 90°예요.","90°가 70°와 ㉠으로 나뉘었어요.","㉠ = 90° − 70° = 20°예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"line":[[[30.0,90.0],[120.0,90.0]]],"ray":[[[30.0,90.0],[30.0,7.5]],[[30.0,90.0],[66.0,-17.99999999999999]]],"right":[[[75.0,90.0],[30.0,90.0],[30.0,45.0]]],"lab":[[[70.1552381713259,61.055106712857096],"70°