INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_challenge#8','math',4,2,'u2','L02','g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C1',4,'sa','auto','점 ㅇ에서 직선과 그 직선에 대한 수선을 긋고, 그 사이에 반직선 2개를 더 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u2-C1","difficulty":4,"kind":"sa","stem":"점 ㅇ에서 직선과 그 직선에 대한 수선을 긋고, 그 사이에 반직선 2개를 더 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["수선과 직선이 만나서 이루는 각은 90°예요.","90°가 세 각으로 나뉘었어요 — 나머지 두 각은 20°, 45°예요.","㉠ = 90° − 20° − 45° = 25°예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"line":[[[30.0,90.0],[120.0,90.0]]],"ray":[[[30.0,90.0],[30.0,7.5]],[[30.0,90.0],[120.0,60.0]],[[30.0,90.0],[60.0,60.0]]],"right":[[[75.0,90.0],[30.0,90.0],[30.0,45.0]]],"lab":[[[87.74502090519522,80.63183258803689],"20°"],[[79.7644004585654,59.24687906895409],"㉠"],[[50.66490534771485,40.11050524439052],"45°"]],"pts":{"ㅇ":[30.0,90.0]},"show":["ㅇ"]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점 ㅇ에서 직선과 그 직선에 대한 수선을 긋고, 그 사이에 반직선 2개를 더 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["수선과 직선이 만나서 이루는 각은 90°예요.","90°가 세 각으로 나뉘었어요 — 나머지 두 각은 35°, 25°예요.","㉠ = 90° − 35° − 25° = 30°예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"line":[[[30.0,90.0],[120.0,90.0]]],"ray":[[[30.0,90.0],[30.0,7.5]],[[30.0,90.0],[120.0,30.0]],[[30.0,90.0],[60.0,30.0]]],"right":[[[75.0,90.0],[30.0,90.0],[30.0,45.0]]],"lab":[[[85.98989353921505,73.04766029518738],"35°"],[[68.717369755755,46.14552156055043],"㉠"],[[42.40892739040802,37.445090419451944],"25°"]],"pts":{"ㅇ":[30.0,90.0]},"show":["ㅇ"]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점 ㅇ에서 직선과 그 직선에 대한 수선을 긋고, 그 사이에 반직선 2개를 더 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["수선과 직선이 만나서 이루는 각은 90°예요.","90°가 세 각으로 나뉘었어요 — 나머지 두 각은 25°, 45°예요.","㉠ = 90° − 25° − 45° = 20°예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"line":[[[30.0,90.0],[120.0,90.0]]],"ray":[[[30.0,90.0],[30.0,7.5]],[[30.0,90.0],[90.0,60.0]],[[30.0,90.0],[60.0,60.0]]],"right":[[[75.0,90.0],[30.0,90.0],[30.0,45.0]]],"lab":[[[86.93448537892705,76.55699532705799],"25°"],[[77.45619056611244,55.79239884246747],"㉠"],[[50.66490534771485,40.11050524439052],"45°"]],"pts":{"ㅇ":[30.0,90.0]},"show":["ㅇ"]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_challenge#9','math',4,2,'u2','L02','g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C1',4,'sa','auto','직선 위의 점 ㅇ에서 그 직선에 대한 수선과 반직선을 그었어요. 파란 호로 표시한 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u2-C1","difficulty":4,"kind":"sa","stem":"직선 위의 점 ㅇ에서 그 직선에 대한 수선과 반직선을 그었어요. 파란 호로 표시한 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["145"],"explanation":["㉠은 수선의 왼쪽 직각 90°와 수선과 반직선 사이의 55°를 합친 각이에요.","수선과 직선이 이루는 각은 90°예요.","㉠ = 90° + 55° = 145°예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[15.0,90.0],[135.0,90.0]]],"ray":[[[75.0,90.0],[75.0,7.5]],[[75.0,90.0],[183.0,18.000000000000004]]],"right":[[[120.0,90.0],[75.0,90.0],[75.0,45.0]]],"lab":[[[98.35699303151151,46.357121124679196],"55°"],[[42.0,66.0],"㉠"]],"pts":{"ㅇ":[75.0,90.0]},"show":["ㅇ"],"arc":[[[15.0,90.0],[75.0,90.0],[183.0,18.000000000000004]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 직선 위의 점 ㅇ에서 그 직선에 대한 수선과 반직선을 그었어요. 파란 호로 표시한 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["155"],"explanation":["㉠은 수선의 왼쪽 직각 90°와 수선과 반직선 사이의 65°를 합친 각이에요.","수선과 직선이 이루는 각은 90°예요.","㉠ = 90° + 65° = 155°예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[15.0,90.0],[135.0,90.0]]],"ray":[[[75.0,90.0],[75.0,7.5]],[[75.0,90.0],[147.0,54.0]]],"right":[[[120.0,90.0],[75.0,90.0],[75.0,45.0]]],"lab":[[[101.02187155703885,47.891661150444655],"65°"],[[42.0,66.0],"㉠"]],"pts":{"ㅇ":[75.0,90.0]},"show":["ㅇ"],"arc":[[[15.0,90.0],[75.0,90.0],[147.0,54.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 직선 위의 점 ㅇ에서 그 직선에 대한 수선과 반직선을 그었어요. 파란 호로 표시한 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["115"],"explanation":["㉠은 수선의 왼쪽 직각 90°와 수선과 반직선 사이의 25°를 합친 각이에요.","수선과 직선이 이루는 각은 90°예요.","㉠ = 90° + 25° = 115°예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[15.0,90.0],[135.0,90.0]]],"ray":[[[75.0,90.0],[75.0,7.5]],[[75.0,90.0],[111.0,18.000000000000004]]],"right":[[[120.0,90.0],[75.0,90.0],[75.0,45.0]]],"lab":[[[86.37485010787401,41.82466621783095],"25°"],[[42.0,66.0],"㉠"]],"pts":{"ㅇ":[75.0,90.0]},"show":["ㅇ"],"arc":[[[15.0,90.0],[75.0,90.0],[111.0,18.000000000000004]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L02_challenge#10','math',4,2,'u2','L02','g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C1',4,'essay','teacher','기울어져 놓인 직선 가와 직선 나가 서로 수직인지 알아보는 방법을 쓰고, 기울어져 있어도 수직이라고 할 수 있는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u2-C1","difficulty":4,"kind":"essay","stem":"기울어져 놓인 직선 가와 직선 나가 서로 수직인지 알아보는 방법을 쓰고, 기울어져 있어도 수직이라고 할 수 있는 까닭을 써 보세요.","answer_guide":{"answer":"예: 두 직선이 만나는 곳에 삼각자의 직각 부분을 대어 보거나 각도기로 만나서 이루는 각을 재어 본다. 각이 직각(90°)이면 서로 수직이다. 수직은 놓인 방향이 아니라 만나서 이루는 각이 직각인지로 정하기 때문에 기울어져 있어도 수직일 수 있다.","scoring_points":["삼각자의 직각 부분이나 각도기로 확인하는 방법을 썼는가","만나서 이루는 각이 직각이면 수직이라고 썼는가","놓인 방향은 상관없다는 까닭을 썼는가"]},"explanation":["만나는 곳에 삼각자의 직각 부분을 대거나 각도기로 재어요.","만나서 이루는 각이 90°면 서로 수직이에요.","수직은 놓인 방향이 아니라 각으로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L03_basic#1','math',4,2,'u2','L03','g4_2_math_u2_L03_basic','lesson_basic','M4-2-u2-C3',1,'mc','auto','한 직선에 수직인 두 직선처럼, 아무리 늘여도 서로 만나지 않는 두 직선의 관계를 무엇이라고 하나요?',ARRAY['M4-2-u2-X05','M4-2-u2-X02']::text[],true,'{"seq":1,"concept":"M4-2-u2-C3","difficulty":1,"kind":"mc","stem":"한 직선에 수직인 두 직선처럼, 아무리 늘여도 서로 만나지 않는 두 직선의 관계를 무엇이라고 하나요?","options":[{"t":"평행","correct":true},{"t":"수직","mis":"M4-2-u2-X05"},{"t":"평행선","mis":"M4-2-u2-X02"},{"t":"수선","mis":"M4-2-u2-X02"}],"explanation":["한 직선에 수직인 두 직선은 아무리 늘여도 만나지 않아요.","이렇게 만나지 않는 두 직선은 서로 평행하다고 해요.","평행은 두 직선의 관계, 평행선은 평행한 두 직선을 가리키는 말이에요."],"variant_rule":{"alt":[{"stem":"서로 평행한 두 직선을 무엇이라고 하나요?","options":[{"t":"평행선","correct":true},{"t":"평행","mis":"M4-2-u2-X02"},{"t":"수선","mis":"M4-2-u2-X02"},{"t":"수직선","mis":"M4-2-u2-X02"}],"explanation":["한 직선에 수직인 두 직선은 아무리 늘여도 만나지 않아요.","이렇게 만나지 않는 두 직선은 서로 평행하다고 해요.","평행은 두 직선의 관계, 평행선은 평행한 두 직선을 가리키는 말이에요."],"asset":null},{"stem":"자전거 도로의 두 경계선은 아무리 늘여도 만나지 않아요. 두 경계선은 서로 어떤 관계인가요?","options":[{"t":"평행","correct":true},{"t":"수직","mis":"M4-2-u2-X05"},{"t":"수선","mis":"M4-2-u2-X02"},{"t":"직각","mis":"M4-2-u2-X02"}],"explanation":["한 직선에 수직인 두 직선은 아무리 늘여도 만나지 않아요.","이렇게 만나지 않는 두 직선은 서로 평행하다고 해요.","평행은 두 직선의 관계, 평행선은 평행한 두 직선을 가리키는 말이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L03_basic#2','math',4,2,'u2','L03','g4_2_math_u2_L03_basic','lesson_basic','M4-2-u2-C3',1,'mc','auto','직선 가와 서로 평행한 직선은 어느 것인가요?',ARRAY['M4-2-u2-X05','M4-2-u2-X06']::text[],true,'{"seq":2,"concept":"M4-2-u2-C3","difficulty":1,"kind":"mc","stem":"직선 가와 서로 평행한 직선은 어느 것인가요?","options":[{"t":"직선 다","correct":true},{"t":"직선 나","mis":"M4-2-u2-X05"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"평행한 직선이 없어요","mis":"M4-2-u2-X06"}],"explanation":["끝없이 늘여도 직선 가와 만나지 않는 직선을 찾아요.","모눈을 보면 직선 가와 직선 다는 같은 방향으로 뻗어 만나지 않아요.","그래서 두 직선은 서로 평행해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,15.0],[150.0,15.0]],[[30.0,0.0],[75.0,105.0]],[[0.0,60.0],[150.0,60.0]],[[90.0,0.0],[135.0,105.0]]],"lab":[[[13.5,26.25],"가"],[[80.02247105688438,88.15994998574058],"나"],[[13.5,71.25],"다"],[[140.0224710568844,88.15994998574058],"라"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 직선 가와 서로 평행한 직선은 어느 것인가요?","options":[{"t":"직선 나","correct":true},{"t":"직선 다","mis":"M4-2-u2-X05"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"평행한 직선이 없어요","mis":"M4-2-u2-X06"}],"explanation":["끝없이 늘여도 직선 가와 만나지 않는 직선을 찾아요.","모눈을 보면 직선 가와 직선 나는 같은 방향으로 뻗어 만나지 않아요.","그래서 두 직선은 서로 평행해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,90.0],[135.0,0.0]],[[60.0,105.0],[150.0,45.0]],[[0.0,30.0],[150.0,60.0]],[[90.0,0.0],[120.0,105.0]]],"lab":[[[17.473056181094716,91.87211316226015],"가"],[[64.99230176602705,88.15098153965866],"나"],[[11.031532601522853,43.67910042588833],"다"],[[127.10840918434467,88.9288140180034],"라"]]}],"tag":false}},{"stem":"직선 나와 서로 평행한 직선은 어느 것인가요?","options":[{"t":"직선 다","correct":true},{"t":"직선 가","mis":"M4-2-u2-X01"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"평행한 직선이 없어요","mis":"M4-2-u2-X06"}],"explanation":["끝없이 늘여도 직선 나와 만나지 않는 직선을 찾아요.","모눈을 보면 직선 나와 직선 다는 같은 방향으로 뻗어 만나지 않아요.","그래서 두 직선은 서로 평행해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,30.0],[135.0,75.0]],[[30.0,105.0],[60.0,15.0]],[[90.0,105.0],[120.0,15.0]],[[0.0,90.0],[150.0,90.0]]],"lab":[[[9.249662155992509,44.94176194429559],"가"],[[50.05823805570442,9.249662155992509],"나"],[[110.05823805570442,9.249662155992509],"다"],[[13.5,78.75],"라"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L03_basic#3','math',4,2,'u2','L03','g4_2_math_u2_L03_basic','lesson_basic','M4-2-u2-C3',1,'sa','auto','평행선을 그으려면 삼각자가 몇 개 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u2-C3","difficulty":1,"kind":"sa","stem":"평행선을 그으려면 삼각자가 몇 개 있어야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["한 삼각자를 손으로 꼭 잡아 고정해요.","다른 삼각자를 그 변을 따라 밀며 선을 그어요.","그래서 삼각자 2개가 있어야 해요."],"variant_rule":{"alt":[{"stem":"정사각형에서 서로 평행한 변은 몇 쌍인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["마주 보는 두 변을 늘여 만나는지 살펴봐요.","위아래 두 변이 평행하고, 양옆 두 변도 평행해요.","서로 평행한 변은 2쌍이에요."],"asset":null},{"stem":"이 사각형에서 서로 평행한 변은 몇 쌍인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["마주 보는 두 변을 늘여 만나는지 살펴봐요.","위아래 두 변이 평행하고, 양옆 두 변도 평행해요.","서로 평행한 변은 2쌍이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[90.0,75.0],[120.0,15.0],[45.0,15.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L03_basic#4','math',4,2,'u2','L03','g4_2_math_u2_L03_basic','lesson_basic','M4-2-u2-C3',1,'ox','auto','평행한 두 직선은 아무리 늘여도 서로 만나지 않아요.',ARRAY['M4-2-u2-X05']::text[],true,'{"seq":4,"concept":"M4-2-u2-C3","difficulty":1,"kind":"ox","stem":"평행한 두 직선은 아무리 늘여도 서로 만나지 않아요.","answer":"O","reason_options":[{"t":"평행은 만나지 않는 두 직선의 관계라서","correct":true},{"t":"아주 멀리 늘이면 결국 만나서","mis":"M4-2-u2-X05"}],"mis":"M4-2-u2-X05","explanation":["한 직선에 수직인 두 직선은 같은 방향으로 뻗어요.","그래서 아무리 늘여도 만나지 않아요 — 서로 평행해요.","평행한 두 직선이 평행선이에요."],"variant_rule":{"alt":[{"stem":"평행선은 끝없이 늘이면 언젠가 서로 만나요.","answer":"X","reason_options":[{"t":"평행선은 아무리 늘여도 만나지 않아서","correct":true},{"t":"그림 밖에서는 만날 수도 있어서","mis":"M4-2-u2-X05"}],"explanation":["한 직선에 수직인 두 직선은 같은 방향으로 뻗어요.","그래서 아무리 늘여도 만나지 않아요 — 서로 평행해요.","평행한 두 직선이 평행선이에요."],"asset":null},{"stem":"한 직선에 수직인 두 직선은 서로 만나지 않아요.","answer":"O","reason_options":[{"t":"한 직선에 수직인 두 직선은 서로 평행해서","correct":true},{"t":"두 직선이 모두 수직이니 서로 만나서","mis":"M4-2-u2-X02"}],"explanation":["한 직선에 수직인 두 직선은 같은 방향으로 뻗어요.","그래서 아무리 늘여도 만나지 않아요 — 서로 평행해요.","평행한 두 직선이 평행선이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
