INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L03_basic#6','math',4,2,'u2','L03','g4_2_math_u2_L03_basic','lesson_basic','M4-2-u2-C3',2,'mc','auto','두 직선이 서로 평행한지 알아보는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u2-X05','M4-2-u2-X06']::text[],true,'{"seq":6,"concept":"M4-2-u2-C3","difficulty":2,"kind":"mc","stem":"두 직선이 서로 평행한지 알아보는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 직선에 공통으로 수직인 직선을 그어 본다","correct":true},{"t":"눈으로 나란해 보이는지 본다","mis":"M4-2-u2-X05"},{"t":"두 직선의 길이를 자로 잰다","mis":"M4-2-u2-X06"},{"t":"두 직선이 그림 안에서 만나는지만 본다","mis":"M4-2-u2-X05"}],"explanation":["평행한 두 직선은 한 직선에 함께 수직이에요.","그래서 공통의 수선을 그어 두 직선과 모두 직각으로 만나는지 봐요.","눈대중·길이·놓인 방향으로는 정할 수 없어요."],"variant_rule":{"alt":[{"stem":"두 직선이 서로 평행한지 알아보는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 직선에 수선을 긋고, 그 수선이 다른 직선과도 직각으로 만나는지 본다","correct":true},{"t":"두 직선이 모두 가로로 놓였는지 본다","mis":"M4-2-u2-X01"},{"t":"두 직선의 색이 같은지 본다","mis":"M4-2-u2-X18"},{"t":"두 직선 사이에 아무 선분이나 그어 길이를 잰다","mis":"M4-2-u2-X07"}],"explanation":["평행한 두 직선은 한 직선에 함께 수직이에요.","그래서 공통의 수선을 그어 두 직선과 모두 직각으로 만나는지 봐요.","눈대중·길이·놓인 방향으로는 정할 수 없어요."],"asset":null},{"stem":"두 직선이 서로 평행한지 알아보는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"삼각자 두 개로 한 직선에 수직인 선을 그어 다른 직선에도 수직인지 확인한다","correct":true},{"t":"삼각자 하나를 대고 두 직선이 나란한지 눈대중한다","mis":"M4-2-u2-X03"},{"t":"두 직선을 짧게 잘라 길이를 비교한다","mis":"M4-2-u2-X06"},{"t":"두 직선이 가까이 있으면 평행이라고 한다","mis":"M4-2-u2-X05"}],"explanation":["평행한 두 직선은 한 직선에 함께 수직이에요.","그래서 공통의 수선을 그어 두 직선과 모두 직각으로 만나는지 봐요.","눈대중·길이·놓인 방향으로는 정할 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
