INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L03_challenge#4','math',4,2,'u2','L03','g4_2_math_u2_L03_challenge','lesson_challenge','M4-2-u2-C3',3,'mc','auto','직선 가와 직선 나는 모두 직선 다에 수직이에요. 직선 가와 직선 나는 서로 어떤 관계인가요?',ARRAY['M4-2-u2-X05','M4-2-u2-X06']::text[],true,'{"seq":4,"concept":"M4-2-u2-C3","difficulty":3,"kind":"mc","stem":"직선 가와 직선 나는 모두 직선 다에 수직이에요. 직선 가와 직선 나는 서로 어떤 관계인가요?","options":[{"t":"평행","correct":true},{"t":"수직","mis":"M4-2-u2-X05"},{"t":"알 수 없어요","mis":"M4-2-u2-X06"},{"t":"한 점에서 만나요","mis":"M4-2-u2-X05"}],"explanation":["평행한 두 직선에는 공통의 수선이 있어요.","한 직선에 수직인 두 직선은 서로 평행해요.","그림으로 확인하면 두 직선이 만나지 않아요 — 평행이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,30.0],[135.0,75.0]],[[30.0,105.0],[60.0,15.0]],[[90.0,105.0],[120.0,15.0]]],"lab":[[[9.249662155992509,44.94176194429559],"다"],[[44.94176194429559,95.75033784400749],"가"],[[104.94176194429559,95.75033784400749],"나"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직선 가는 직선 다에 대한 수선이고, 직선 나도 직선 다에 대한 수선이에요. 직선 가와 직선 나는 어떤 관계인가요?","options":[{"t":"평행","correct":true},{"t":"수직","mis":"M4-2-u2-X02"},{"t":"직선 나는 직선 가에 대한 수선이에요","mis":"M4-2-u2-X02"},{"t":"알 수 없어요","mis":"M4-2-u2-X06"}],"explanation":["평행한 두 직선에는 공통의 수선이 있어요.","한 직선에 대한 두 수선은 서로 만나지 않아요 — 평행해요.","그림으로 확인하면 두 직선이 만나지 않아요 — 평행이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,30.0],[135.0,75.0]],[[30.0,105.0],[60.0,15.0]],[[90.0,105.0],[120.0,15.0]]],"lab":[[[9.249662155992509,44.94176194429559],"다"],[[44.94176194429559,95.75033784400749],"가"],[[104.94176194429559,95.75033784400749],"나"]]}],"tag":false}},{"stem":"직선 가와 직선 나는 서로 평행하고, 직선 다는 직선 가에 수직이에요. 직선 다와 직선 나는 어떤 관계인가요?","options":[{"t":"수직","correct":true},{"t":"평행","mis":"M4-2-u2-X05"},{"t":"알 수 없어요","mis":"M4-2-u2-X06"},{"t":"만나지 않아요","mis":"M4-2-u2-X05"}],"explanation":["평행한 