INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L03_challenge#7','math',4,2,'u2','L03','g4_2_math_u2_L03_challenge','lesson_challenge','M4-2-u2-C3',3,'mc','auto','점 ㄱ을 지나고 직선 가와 평행한 직선을 바르게 긋는 방법은 어느 것인가요?',ARRAY['M4-2-u2-X03','M4-2-u2-X05']::text[],true,'{"seq":7,"concept":"M4-2-u2-C3","difficulty":3,"kind":"mc","stem":"점 ㄱ을 지나고 직선 가와 평행한 직선을 바르게 긋는 방법은 어느 것인가요?","options":[{"t":"한 삼각자를 꼭 잡아 고정하고, 다른 삼각자를 그 변을 따라 밀어 선을 긋는다","correct":true},{"t":"두 삼각자를 모두 손에서 떼고 번갈아 대며 긋는다","mis":"M4-2-u2-X03"},{"t":"삼각자 하나를 직선에 대고 비스듬히 긋는다","mis":"M4-2-u2-X03"},{"t":"자 없이 직선과 나란해 보이게 긋는다","mis":"M4-2-u2-X05"}],"explanation":["평행선은 한 직선에 함께 수직인 두 직선이에요.","삼각자 하나를 꼭 고정하고 다른 삼각자를 밀면 기울기가 그대로 유지돼요.","손을 놓거나 눈대중으로 그으면 선이 기울어져요."],"variant_rule":{"alt":[{"stem":"점 ㄱ을 지나고 직선 가와 평행한 직선을 바르게 긋는 방법은 어느 것인가요?","options":[{"t":"직선 가에 수선을 긋고, 그 수선에 점 ㄱ을 지나는 수선을 한 번 더 긋는다","correct":true},{"t":"점 ㄱ에서 직선 가에 수선을 하나만 긋는다","mis":"M4-2-u2-X02"},{"t":"점 ㄱ에서 직선 가와 45°가 되게 긋는다","mis":"M4-2-u2-X03"},{"t":"점 ㄱ을 지나는 아무 직선이나 긋는다","mis":"M4-2-u2-X05"}],"explanation":["평행선은 한 직선에 함께 수직인 두 직선이에요.","삼각자 하나를 꼭 고정하고 다른 삼각자를 밀면 기울기가 그대로 유지돼요.","손을 놓거나 눈대중으로 그으면 선이 기울어져요."],"asset":null},{"stem":"점 ㄱ을 지나고 직선 가와 평행한 직선을 바르게 긋는 방법은 어느 것인가요?","options":[{"t":"삼각자의 한 변을 직선 가에 맞추고, 다른 삼각자로 그 삼각자를 받친 채 점 ㄱ까지 밀어 긋는다","correct":true},{"t":"삼각자 하나를 직선 가에 맞추고 점 ㄱ까지 손으로 옮겨 긋는다","mis":"M4-2-u2-X03"},{"t":"직선 가를 따라 덧그린다","mis":"M4-2-u2-X05"},{"t":"점 ㄱ에서 직선 가에 가장 가까운 선분을 긋는다","mis":"M4-2-u2-X02"}],"explanation":["평행선은 한 직선에 함께 수직인 두 직선이에요.","삼각자 하나를 꼭 고정하고 다른 삼각자를 밀면 기울기가 그대로 유지돼요.","손을 놓거나 눈대중으로 그으면 선이 기울어져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L03_challenge#8','math',4,2,'u2','L03','g4_2_math_u2_L03_challenge','lesson_challenge','M4-2-u2-C3',4,'sa','auto','그림에서 서로 수직인 직선은 모두 몇 쌍인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u2-C3","difficulty":4,"kind":"sa","stem":"그림에서 서로 수직인 직선은 모두 몇 쌍인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["직선 가부터 차례로, 짝이 되는 직선과 직각으로 만나는지 살펴봐요(같은 쌍을 두 번 세지 않아요).","수직인 쌍: 직선 가와 직선 다, 직선 가와 직선 라, 직선 나와 직선 다, 직선 나와 직선 라.","모두 4쌍이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,30.0],[150.0,30.0]],[[0.0,75.0],[150.0,75.0]],[[30.0,0.0],[30.0,105.0]],[[105.0,0.0],[105.0,105.0]],[[60.0,105.0],[135.0,0.0]]],"lab":[[[136.5,41.25],"가"],[[136.5,86.25],"나"],[[18.75,13.5],"다"],[[93.75,13.5],"라"],[[83.10421820033409,92.00932637037819],"마"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 그림에서 서로 수직인 직선은 모두 몇 쌍인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["직선 가부터 차례로, 짝이 되는 직선과 직각으로 만나는지 살펴봐요(같은 쌍을 두 번 세지 않아요).","수직인 쌍: 직선 가와 직선 다, 직선 가와 직선 라, 직선 나와 직선 다, 직선 나와 직선 라.","모두 4쌍이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,15.0],[150.0,90.0]],[[0.0,60.0],[90.0,105.0]],[[30.0,105.0],[75.0,15.0]],[[90.0,105.0],[135.0,15.0]],[[0.0,97.5],[150.0,97.5]]],"lab":[[[7.043614129124338,31.099689437998485],"가"],[[7.043614129124338,76.09968943799848],"나"],[[66.40031056200152,7.043614129124338],"다"],[[126.40031056200152,7.043614129124338],"라"],[[114.0,86.25],"마"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 그림에서 서로 수직인 직선은 모두 몇 쌍인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["직선 가부터 차례로, 짝이 되는 직선과 직각으로 만나는지 살펴봐요(같은 쌍을 두 번 세지 않아요).","수직인 쌍: 직선 가와 직선 나, 직선 가와 직선 다, 직선 라와 직선 마.","모두 3쌍이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,90.0],[150.0,15.0]],[[30.0,15.0],[67.5,90.0]],[[75.0,0.0],[120.0,90.0]],[[15.0,0.0],[15.0,105.0]],[[0.0,45.0],[150.0,45.0]]],"lab":[[[132.8940799721266,10.975077640500377],"가"],[[38.599689437998485,7.043614129124338],"나"],[[91.09968943799848,7.043614129124338],"다"],[[26.25,91.5],"라"],[[136.5,56.25],"마"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L03_challenge#9','math',4,2,'u2','L03','g4_2_math_u2_L03_challenge','lesson_challenge','M4-2-u2-C3',4,'mc','auto','철길의 두 선로 가와 나는 서로 평행해요. 침목 다는 선로 가에 수직으로 놓였어요. 침목 다와 선로 나는 서로 어떤 관계인가요?',ARRAY['M4-2-u2-X05','M4-2-u2-X06']::text[],true,'{"seq":9,"concept":"M4-2-u2-C3","difficulty":4,"kind":"mc","stem":"철길의 두 선로 가와 나는 서로 평행해요. 침목 다는 선로 가에 수직으로 놓였어요. 침목 다와 선로 나는 서로 어떤 관계인가요?","options":[{"t":"수직","correct":true},{"t":"평행","mis":"M4-2-u2-X05"},{"t":"만나지 않아요","mis":"M4-2-u2-X05"},{"t":"알 수 없어요","mis":"M4-2-u2-X06"}],"explanation":["평행한 두 직선에는 공통의 수선이 있어요.","침목 다는 선로 가에 대한 수선이에요.","평행한 선로 나와도 직각으로 만나요 — 수직이에요."],"variant_rule":{"alt":[{"stem":"침목 다와 침목 라는 모두 선로 가에 수직으로 놓였어요. 침목 다와 침목 라는 서로 어떤 관계인가요?","options":[{"t":"평행","correct":true},{"t":"수직","mis":"M4-2-u2-X02"},{"t":"한 점에서 만나요","mis":"M4-2-u2-X05"},{"t":"알 수 없어요","mis":"M4-2-u2-X06"}],"explanation":["평행한 두 직선에는 공통의 수선이 있어요.","두 침목은 모두 선로 가에 대한 수선이에요.","한 직선에 수직인 두 직선은 만나지 않아요 — 평행이에요."],"asset":null},{"stem":"직선 가와 직선 나는 서로 평행하고, 직선 나와 직선 다도 서로 평행해요. 직선 가와 직선 다는 서로 어떤 관계인가요?","options":[{"t":"평행","correct":true},{"t":"수직","mis":"M4-2-u2-X05"},{"t":"한 점에서 만나요","mis":"M4-2-u2-X05"},{"t":"알 수 없어요","mis":"M4-2-u2-X06"}],"explanation":["평행한 두 직선에는 공통의 수선이 있어요.","직선 나에 수선을 하나 그으면 직선 가·다와도 모두 직각으로 만나요.","공통의 수선이 있으니 직선 가와 직선 다도 평행이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L03_challenge#10','math',4,2,'u2','L03','g4_2_math_u2_L03_challenge','lesson_challenge','M4-2-u2-C3',4,'essay','teacher','기울어져 놓인 두 직선이 서로 평행한지 알아보는 방법을 쓰고, 기울어져 있어도 평행이라고 할 수 있는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u2-C3","difficulty":4,"kind":"essay","stem":"기울어져 놓인 두 직선이 서로 평행한지 알아보는 방법을 쓰고, 기울어져 있어도 평행이라고 할 수 있는 까닭을 써 보세요.","answer_guide":{"answer":"예: 한 직선에 수선을 긋고, 그 수선이 다른 직선과도 직각으로 만나는지 삼각자로 확인한다. 두 직선이 같은 직선에 수직이면 아무리 늘여도 만나지 않으므로 평행이다. 평행은 놓인 방향이 아니라 만나는지로 정하므로 기울어져 있어도 평행일 수 있다.","scoring_points":["공통의 수선을 그어 확인하는 방법을 썼는가","한 직선에 수직인 두 직선은 만나지 않는다고 썼는가","놓인 방향은 상관없다는 까닭을 썼는가"]},"explanation":["한 직선에 수선을 긋고 다른 직선과도 직각인지 봐요.","공통의 수선이 있으면 두 직선은 만나지 않아요 — 평행.","평행은 방향이 아니라 만나는지로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L04_basic#1','math',4,2,'u2','L04','g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',1,'mc','auto','평행선의 한 직선에서 다른 직선에 수직인 선분을 그었을 때, 이 선분의 길이를 무엇이라고 하나요?',ARRAY['M4-2-u2-X02','M4-2-u2-X07']::text[],true,'{"seq":1,"concept":"M4-2-u2-C4","difficulty":1,"kind":"mc","stem":"평행선의 한 직선에서 다른 직선에 수직인 선분을 그었을 때, 이 선분의 길이를 무엇이라고 하나요?","options":[{"t":"평행선 사이의 거리","correct":true},{"t":"수선의 길이","mis":"M4-2-u2-X02"},{"t":"평행선의 길이","mis":"M4-2-u2-X07"},{"t":"직선의 길이","mis":"M4-2-u2-X07"}],"explanation":["평행선의 한 직선에서 다른 직선에 수직인 선분을 그어요.","그 수직인 선분의 길이가 평행선 사이의 거리예요.","수직인 선분은 가장 짧고 어디에 그어도 길이가 같아요."],"variant_rule":{"alt":[{"stem":"평행선 사이의 거리를 바르게 설명한 것은 어느 것인가요?","options":[{"t":"평행선의 한 직선에서 다른 직선에 그은 수직인 선분의 길이","correct":true},{"t":"평행선의 한 직선에서 다른 직선에 그은 가장 긴 선분의 길이","mis":"M4-2-u2-X07"},{"t":"평행선의 한 직선에서 다른 직선에 비스듬히 그은 선분의 길이","mis":"M4-2-u2-X07"},{"t":"두 평행선의 길이를 더한 것","mis":"M4-2-u2-X02"}],"explanation":["평행선의 한 직선에서 다른 직선에 수직인 선분을 그어요.","그 수직인 선분의 길이가 평행선 사이의 거리예요.","수직인 선분은 가장 짧고 어디에 그어도 길이가 같아요."],"asset":null},{"stem":"횡단보도의 두 선은 서로 평행해요. 두 선 사이의 거리를 재려면 어떤 선분의 길이를 재어야 하나요?","options":[{"t":"두 선에 수직인 선분","correct":true},{"t":"두 선을 비스듬히 잇는 선분","mis":"M4-2-u2-X07"},{"t":"두 선을 잇는 가장 긴 선분","mis":"M4-2-u2-X07"},{"t":"아무 선분이나 재도 된다","mis":"M4-2-u2-X08"}],"explanation":["평행선의 한 직선에서 다른 직선에 수직인 선분을 그어요.","그 수직인 선분의 길이가 평행선 사이의 거리예요.","수직인 선분은 가장 짧고 어디에 그어도 길이가 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L04_basic#2','math',4,2,'u2','L04','g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',1,'mc','auto','두 직선은 서로 평행해요. 평행선 사이의 거리를 나타내는 선분은 어느 것인가요?',ARRAY['M4-2-u2-X07','M4-2-u2-X08']::text[],true,'{"seq":2,"concept":"M4-2-u2-C4","difficulty":1,"kind":"mc","stem":"두 직선은 서로 평행해요. 평행선 사이의 거리를 나타내는 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㄷ","correct":true},{"t":"선분 ㄱㄴ","mis":"M4-2-u2-X07"},{"t":"선분 ㄱㄹ","mis":"M4-2-u2-X07"},{"t":"세 선분 모두","mis":"M4-2-u2-X08"}],"explanation":["평행선 사이의 거리는 한 직선에서 다른 직선에 그은 수직인 선분의 길이예요.","선분 ㄱㄷ이 아래 직선과 직각으로 만나요.","비스듬한 선분은 거리를 나타내지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"pts":{"ㄱ":[67.5,22.5],"ㄴ":[22.5,82.5],"ㄷ":[67.5,82.5],"ㄹ":[135.0,82.5]},"seg":[["ㄱ","ㄴ"],["ㄱ","ㄷ"],["ㄱ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 두 직선은 서로 평행해요. 평행선 사이의 거리를 나타내는 선분은 어느 것인가요?","options":[{"t":"선분 ㅁㅂ","correct":true},{"t":"선분 ㅁㅅ","mis":"M4-2-u2-X07"},{"t":"선분 ㅁㅇ","mis":"M4-2-u2-X07"},{"t":"세 선분 모두","mis":"M4-2-u2-X08"}],"explanation":["평행선 사이의 거리는 한 직선에서 다른 직선에 그은 수직인 선분의 길이예요.","선분 ㅁㅂ이 아래 직선과 직각으로 만나요.","비스듬한 선분은 거리를 나타내지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"pts":{"ㅁ":[52.5,22.5],"ㅂ":[52.5,82.5],"ㅅ":[112.5,82.5],"ㅇ":[7.5,82.5]},"seg":[["ㅁ","ㅂ"],["ㅁ","ㅅ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 두 직선은 서로 평행해요. 평행선 사이의 거리를 나타내는 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㅁ","correct":true},{"t":"선분 ㄱㄷ","mis":"M4-2-u2-X07"},{"t":"선분 ㄱㄹ","mis":"M4-2-u2-X07"},{"t":"세 선분 모두","mis":"M4-2-u2-X08"}],"explanation":["평행선 사이의 거리는 한 직선에서 다른 직선에 그은 수직인 선분의 길이예요.","선분 ㄱㅁ이 아래 직선과 직각으로 만나요.","비스듬한 선분은 거리를 나타내지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"pts":{"ㄱ":[90.0,22.5],"ㄷ":[135.0,82.5],"ㄹ":[30.0,82.5],"ㅁ":[90.0,82.5]},"seg":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L04_basic#3','math',4,2,'u2','L04','g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',1,'sa','auto','두 직선은 서로 평행해요. 점 ㄱ에서 아래 직선에 그은 세 선분 가운데 하나는 아래 직선에 수직이에요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u2-C4","difficulty":1,"kind":"sa","stem":"두 직선은 서로 평행해요. 점 ㄱ에서 아래 직선에 그은 세 선분 가운데 하나는 아래 직선에 수직이에요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["수직인 선분이 세 선분 가운데 가장 짧아요.","세 길이 5 cm, 4 cm, 6 cm 가운데 가장 짧은 것은 4 cm예요.","평행선 사이의 거리는 4 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"pts":{"ㄱ":[67.5,22.5],"ㄴ":[22.5,82.5],"ㄷ":[67.5,82.5],"ㄹ":[135.0,82.5]},"seg":[["ㄱ","ㄴ"],["ㄱ","ㄷ"],["ㄱ","ㄹ"]],"lab":[[[17.849999999999998,67.5],"5 cm"],[[86.25,43.5],"4 cm"],[[133.35000000000002,67.5],"6 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"두 직선은 서로 평행해요. 점 ㅁ에서 아래 직선에 그은 세 선분 가운데 하나는 아래 직선에 수직이에요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["수직인 선분이 세 선분 가운데 가장 짧아요.","세 길이 4 cm, 6 cm, 5 cm 가운데 가장 짧은 것은 4 cm예요.","평행선 사이의 거리는 4 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"pts":{"ㅁ":[52.5,22.5],"ㅂ":[52.5,82.5],"ㅅ":[112.5,82.5],"ㅇ":[7.5,82.5]},"seg":[["ㅁ","ㅂ"],["ㅁ","ㅅ"],["ㅁ","ㅇ"]],"lab":[[[71.25,43.5],"4 cm"],[[112.94999999999999,67.5],"6 cm"],[[2.849999999999999,67.5],"5 cm"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 두 직선은 서로 평행해요. 점 ㄱ에서 아래 직선에 그은 세 선분 가운데 하나는 아래 직선에 수직이에요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["수직인 선분이 세 선분 가운데 가장 짧아요.","세 길이 5 cm, 6 cm, 4 cm 가운데 가장 짧은 것은 4 cm예요.","평행선 사이의 거리는 4 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"pts":{"ㄱ":[90.0,22.5],"ㄷ":[135.0,82.5],"ㄹ":[30.0,82.5],"ㅁ":[90.0,82.5]},"seg":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"]],"lab":[[[139.65,67.5],"5 cm"],[[29.550000000000004,67.5],"6 cm"],[[108.75,43.5],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L04_basic#4','math',4,2,'u2','L04','g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',1,'sa','auto','평행선 사이의 거리가 4 cm예요. 다른 자리에서 수직인 선분을 그어 재면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u2-C4","difficulty":1,"kind":"sa","stem":"평행선 사이의 거리가 4 cm예요. 다른 자리에서 수직인 선분을 그어 재면 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["평행선 사이에 수직인 선분은 어디에 그어도 길이가 같아요.","평행선 사이의 거리는 일정해요.","그래서 4 cm예요."],"variant_rule":{"alt":[{"stem":"자전거 도로의 두 경계선은 평행해요. 한 곳에서 잰 경계선 사이의 거리가 7 cm였어요. 몇 걸음 떨어진 곳에서 수직으로 재면 몇 cm일까요? 숫자로 쓰세요.","answer":["7"],"explanation":["평행선 사이에 수직인 선분은 어디에 그어도 길이가 같아요.","평행선 사이의 거리는 일정해요.","그래서 7 cm예요."],"asset":null},{"stem":"평행선의 왼쪽에서 수직인 선분을 그어 쟀더니 12 cm였어요. 오른쪽 끝에서 수직인 선분을 그어 재면 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["평행선 사이에 수직인 선분은 어디에 그어도 길이가 같아요.","평행선 사이의 거리는 일정해요.","그래서 12 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L04_basic#5','math',4,2,'u2','L04','g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',2,'sa','auto','모눈 한 칸의 길이는 1 cm예요. 두 직선은 서로 평행해요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u2-C4","difficulty":2,"kind":"sa","stem":"모눈 한 칸의 길이는 1 cm예요. 두 직선은 서로 평행해요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["비스듬히 그은 선분의 길이는 평행선 사이의 거리가 아니에요.","한 직선에서 다른 직선까지 모눈 줄을 따라 수직으로 칸을 세어요.","4칸이니 4 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,15.0],[150.0,15.0]],[[0.0,75.0],[150.0,75.0]]],"seg":[[[45.0,15.0],[97.5,75.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 모눈 한 칸의 길이는 1 cm예요. 두 직선은 서로 평행해요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["비스듬히 그은 선분의 길이는 평행선 사이의 거리가 아니에요.","한 직선에서 다른 직선까지 모눈 줄을 따라 수직으로 칸을 세어요.","6칸이니 6 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[30.0,0.0],[30.0,105.0]],[[120.0,0.0],[120.0,105.0]]],"seg":[[[30.0,22.5],[120.0,82.5]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 모눈 한 칸의 길이는 1 cm예요. 두 직선은 서로 평행해요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["비스듬히 그은 선분의 길이는 평행선 사이의 거리가 아니에요.","한 직선에서 다른 직선까지 모눈 줄을 따라 수직으로 칸을 세어요.","3칸이니 3 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,30.0],[150.0,30.0]],[[0.0,75.0],[150.0,75.0]]],"seg":[[[45.0,30.0],[97.5,75.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L04_basic#6','math',4,2,'u2','L04','g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',2,'ox','auto','평행선 사이의 거리는 재는 자리마다 달라요.',ARRAY['M4-2-u2-X08']::text[],true,'{"seq":6,"concept":"M4-2-u2-C4","difficulty":2,"kind":"ox","stem":"평행선 사이의 거리는 재는 자리마다 달라요.","answer":"X","reason_options":[{"t":"수직인 선분은 어디에 그어도 길이가 같아서","correct":true},{"t":"평행선의 왼쪽과 오른쪽은 떨어진 정도가 달라서","mis":"M4-2-u2-X08"}],"mis":"M4-2-u2-X08","explanation":["평행선 사이의 거리는 수직인 선분의 길이로 재요.","수직인 선분이 가장 짧고, 어디에 그어도 길이가 같아요.","비스듬한 선분은 긋는 자리에 따라 길이가 달라져요."],"variant_rule":{"alt":[{"stem":"평행선 사이에 그은 선분 가운데 수직인 선분의 길이가 가장 짧아요.","answer":"O","reason_options":[{"t":"비스듬한 선분은 수직인 선분보다 길어서","correct":true},{"t":"선분은 길이가 모두 같아서","mis":"M4-2-u2-X07"}],"explanation":["평행선 사이의 거리는 수직인 선분의 길이로 재요.","수직인 선분이 가장 짧고, 어디에 그어도 길이가 같아요.","비스듬한 선분은 긋는 자리에 따라 길이가 달라져요."],"asset":null},{"stem":"평행선 사이의 거리는 비스듬한 선분으로 재도 같아요.","answer":"X","reason_options":[{"t":"비스듬한 선분은 수직인 선분보다 길어서","correct":true},{"t":"평행선 사이의 선분은 길이가 모두 같아서","mis":"M4-2-u2-X07"}],"explanation":["평행선 사이의 거리는 수직인 선분의 길이로 재요.","수직인 선분이 가장 짧고, 어디에 그어도 길이가 같아요.","비스듬한 선분은 긋는 자리에 따라 길이가 달라져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
