INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L04_basic#8','math',4,2,'u2','L04','g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',2,'mc','auto','평행선 사이의 거리를 꼭 수직인 선분으로 재는 까닭은 무엇인가요?',ARRAY['M4-2-u2-X07','M4-2-u2-X06','M4-2-u2-X08']::text[],true,'{"seq":8,"concept":"M4-2-u2-C4","difficulty":2,"kind":"mc","stem":"평행선 사이의 거리를 꼭 수직인 선분으로 재는 까닭은 무엇인가요?","options":[{"t":"수직인 선분은 어디에 그어도 길이가 같아 값이 하나로 정해져서","correct":true},{"t":"수직인 선분이 가장 길어서","mis":"M4-2-u2-X07"},{"t":"비스듬한 선분은 그을 수 없어서","mis":"M4-2-u2-X06"},{"t":"재는 자리마다 거리가 달라서","mis":"M4-2-u2-X08"}],"explanation":["한 점에서 직선에 그은 선분 가운데 수직인 선분이 가장 짧아요.","수직인 선분은 어디에 그어도 길이가 같아요.","그래서 평행선 사이의 거리는 수직인 선분의 길이로 하나로 정해요."],"variant_rule":{"alt":[{"stem":"점 ㄱ에서 아래 직선에 그은 여러 선분 가운데 길이가 가장 짧은 선분은 어느 것인가요?","options":[{"t":"아래 직선과 수직으로 만나는 선분","correct":true},{"t":"가장 비스듬한 선분","mis":"M4-2-u2-X07"},{"t":"가장 오른쪽에 그은 선분","mis":"M4-2-u2-X06"},{"t":"모든 선분의 길이가 같다","mis":"M4-2-u2-X08"}],"explanation":["한 점에서 직선에 그은 선분 가운데 수직인 선분이 가장 짧아요.","수직인 선분은 어디에 그어도 길이가 같아요.","그래서 평행선 사이의 거리는 수직인 선분의 길이로 하나로 정해요."],"asset":null},{"stem":"평행선 사이에 비스듬한 선분을 그어 재면 어떻게 되나요?","options":[{"t":"긋는 자리에 따라 길이가 달라 거리를 하나로 말할 수 없다","correct":true},{"t":"수직인 선분과 길이가 같다","mis":"M4-2-u2-X07"},{"t":"수직인 선분보다 짧다","mis":"M4-2-u2-X07"},{"t":"어디에 그어도 길이가 같다","mis":"M4-2-u2-X08"}],"explanation":["한 점에서 직선에 그은 선분 가운데 수직인 선분이 가장 짧아요.","수직인 선분은 어디에 그어도 길이가 같아요.","그래서 평행선 사이의 거리는 수직인 선분의 길이로 하나로 정해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L04_basic#9','math',4,2,'u2','L04','g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',2,'sa','auto','직사각형 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 변 ㄹㄷ은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u2-C4","difficulty":2,"kind":"sa","stem":"직사각형 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 변 ㄹㄷ은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["변 ㄴㄷ은 위아래 두 변에 모두 수직이에요.","그래서 두 변 사이의 거리는 변 ㄴㄷ의 길이와 같아요.","4 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,15.0],"ㄴ":[120.0,15.0],"ㄷ":[120.0,75.0],"ㄹ":[15.0,75.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"right":[["ㄹ","ㄱ","ㄴ"],["ㄱ","ㄴ","ㄷ"],["ㄴ","ㄷ","ㄹ"],["ㄷ","ㄹ","ㄱ"]],"lab":[[[67.5,3.75],"7 cm"],[[139.65,45.0],"4 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직사각형 ㅁㅂㅅㅇ에서 변 ㅁㅂ과 변 ㅇㅅ은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["변 ㅂㅅ은 위아래 두 변에 모두 수직이에요.","그래서 두 변 사이의 거리는 변 ㅂㅅ의 길이와 같아요.","5 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[45.0,7.5],"ㅂ":[90.0,7.5],"ㅅ":[90.0,82.5],"ㅇ":[45.0,82.5]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"right":[["ㅇ","ㅁ","ㅂ"],["ㅁ","ㅂ","ㅅ"],["ㅂ","ㅅ","ㅇ"],["ㅅ","ㅇ","ㅁ"]],"lab":[[[67.5,-3.75],"3 cm"],[[109.65,45.0],"5 cm"]]}],"tag":false}},{"stem":"정사각형 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 변 ㄹㄷ은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["변 ㄴㄷ은 위아래 두 변에 모두 수직이에요.","그래서 두 변 사이의 거리는 변 ㄴㄷ의 길이와 같아요.","6 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[30.0,15.0],"ㄴ":[90.0,15.0],"ㄷ":[90.0,75.0],"ㄹ":[30.0,75.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"right":[["ㄹ","ㄱ","ㄴ"],["ㄱ","ㄴ","ㄷ"],["ㄴ","ㄷ","ㄹ"],["ㄷ","ㄹ","ㄱ"]],"lab":[[[60.0,3.75],"6 cm"],[[109.65,45.0],"6 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EX