INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L04_basic#10','math',4,2,'u2','L04','g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',3,'sa','auto','직선 가, 나, 다는 서로 평행하고, 위에서부터 차례로 놓여 있어요. 가와 나 사이의 거리는 4 cm, 나와 다 사이의 거리는 3 cm예요. 직선 가와 직선 다 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u2-C4","difficulty":3,"kind":"sa","stem":"직선 가, 나, 다는 서로 평행하고, 위에서부터 차례로 놓여 있어요. 가와 나 사이의 거리는 4 cm, 나와 다 사이의 거리는 3 cm예요. 직선 가와 직선 다 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["세 직선이 차례로 평행하게 놓여 있어요.","가와 다 사이의 거리는 가와 나 사이, 나와 다 사이를 이어 붙인 길이예요.","4 + 3 = 7 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,15.0],[150.0,15.0]],[[0.0,57.85714285714286],[150.0,57.85714285714286]],[[0.0,90.0],[150.0,90.0]]],"lab":[[[9.0,8.25],"가"],[[9.0,51.10714285714286],"나"],[[9.0,83.25],"다"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"책장 선반 가, 나, 다는 서로 평행하고 위에서부터 차례로 있어요. 가와 나 사이는 50 cm, 나와 다 사이는 60 cm예요. 선반 가와 선반 다 사이의 거리는 몇 cm인가요? (선반 두께는 생각하지 않아요.) 숫자로 쓰세요.","answer":["110"],"explanation":["세 직선이 차례로 평행하게 놓여 있어요.","가와 다 사이의 거리는 가와 나 사이, 나와 다 사이를 이어 붙인 길이예요.","50 + 60 = 110 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,15.0],[150.0,15.0]],[[0.0,49.09090909090909],[150.0,49.09090909090909]],[[0.0,90.0],[150.0,90.0]]],"lab":[[[9.0,8.25],"가"],[[9.0,42.3409090909091],"나"],[[9.0,83.25],"다"]]}],"tag":false}},{"stem":"직선 가, 나, 다는 서로 평행하고, 위에서부터 차례로 놓여 있어요. 가와 나 사이의 거리는 7 cm, 나와 다 사이의 거리는 2 cm예요. 직선 가와 직선 다 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["세 직선이 차례로 평행하게 놓여 있어요.","가와 다 사이의 거리는 가와 나 사이, 나와 다 사이를 이어 붙인 길이예요.","7 + 2 = 9 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,15.0],[150.0,15.0]],[[0.0,73.33333333333334],[150.0,73.33333333333334]],[[0.0,90.0],[150.0,90.0]]],"lab":[[[9.0,8.25],"가"],[[9.0,66.58333333333334],"나"],[[9.0