INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L04_challenge#2','math',4,2,'u2','L04','g4_2_math_u2_L04_challenge','lesson_challenge','M4-2-u2-C4',2,'ox','auto','평행선 사이에 그은 선분 가운데 수직인 선분의 길이가 가장 짧아요.',ARRAY['M4-2-u2-X07']::text[],true,'{"seq":2,"concept":"M4-2-u2-C4","difficulty":2,"kind":"ox","stem":"평행선 사이에 그은 선분 가운데 수직인 선분의 길이가 가장 짧아요.","answer":"O","reason_options":[{"t":"비스듬한 선분은 수직인 선분보다 길어서","correct":true},{"t":"선분은 길이가 모두 같아서","mis":"M4-2-u2-X07"}],"mis":"M4-2-u2-X07","explanation":["평행선 사이의 거리는 수직인 선분의 길이로 재요.","수직인 선분이 가장 짧고, 어디에 그어도 길이가 같아요.","비스듬한 선분은 긋는 자리에 따라 길이가 달라져요."],"variant_rule":{"alt":[{"stem":"평행선 사이의 거리는 비스듬한 선분으로 재도 같아요.","answer":"X","reason_options":[{"t":"비스듬한 선분은 수직인 선분보다 길어서","correct":true},{"t":"평행선 사이의 선분은 길이가 모두 같아서","mis":"M4-2-u2-X07"}],"explanation":["평행선 사이의 거리는 수직인 선분의 길이로 재요.","수직인 선분이 가장 짧고, 어디에 그어도 길이가 같아요.","비스듬한 선분은 긋는 자리에 따라 길이가 달라져요."],"asset":null},{"stem":"평행선 사이의 거리는 재는 자리마다 달라요.","answer":"X","reason_options":[{"t":"수직인 선분은 어디에 그어도 길이가 같아서","correct":true},{"t":"평행선의 왼쪽과 오른쪽은 떨어진 정도가 달라서","mis":"M4-2-u2-X08"}],"explanation":["평행선 사이의 거리는 수직인 선분의 길이로 재요.","수직인 선분이 가장 짧고, 어디에 그어도 길이가 같아요.","비스듬한 선분은 긋는 자리에 따라 길이가 달라져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
