INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L04_challenge#5','math',4,2,'u2','L04','g4_2_math_u2_L04_challenge','lesson_challenge','M4-2-u2-C4',3,'sa','auto','사다리꼴 ㅁㅂㅅㅇ에서 위아래 두 변은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u2-C4","difficulty":3,"kind":"sa","stem":"사다리꼴 ㅁㅂㅅㅇ에서 위아래 두 변은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["평행한 두 변 사이의 거리는 두 변에 수직인 선분의 길이예요.","비스듬한 변(5 cm)이나 평행한 변(9 cm)의 길이가 아니에요.","점선으로 그은 수직인 선분이 4 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[15.0,75.0],"ㅂ":[120.0,75.0],"ㅅ":[90.0,15.0],"ㅇ":[45.0,15.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"lab":[[[13.217694101250945,36.60884705062547],"5 cm"],[[67.5,86.25],"9 cm"],[[62.25000000000001,45.0],"4 cm"]],"dash":[[[45.0,15.0],[45.0,75.0]]],"right":[[[45.0,15.0],[45.0,75.0],[15.0,75.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 사다리꼴 ㅁㅂㅅㅇ에서 위아래 두 변은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["평행한 두 변 사이의 거리는 두 변에 수직인 선분의 길이예요.","비스듬한 변(6 cm)이나 평행한 변(7 cm)의 길이가 아니에요.","점선으로 그은 수직인 선분이 4 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[30.0,15.0],"ㅂ":[75.0,15.0],"ㅅ":[120.0,75.0],"ㅇ":[15.0,75.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"lab":[[[3.680014520423841,40.29500363010596],"6 cm"],[[67.5,86.25],"7 cm"],[[47.25,45.0],"4 cm"]],"dash":[[[30.0,15.0],[30.0,75.0]]],"right":[[[30.0,15.0],[30.0,75.0],[120.0,75.0]]]}],"tag":false}},{"stem":"평행사변형 ㄱㄴㄷㄹ에서 위아래 두 변은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["평행한 두 변 사이의 거리는 두 변에 수직인 선분의 길이예요.","비스듬한 변(5 cm)이나 평행한 변(6 cm)의 길이가 아니에요.","점선으로 그은 수직인 선분이 4 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[120.0,15.0],"ㄹ":[45.0,15.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[13.217694101250945,36.60884705062547],"5 cm"],[[52.5,86.25],"6 cm"],[[62.25000000000001,45.0],"4 cm"]],"dash":[[[45.0,15.0],[45.0,75.0]]],"right":[[[45.0,15.0],[45.0,75.0],[15.0,75.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L04_challenge#6','math',4,2,'u2','L04','g4_2_math_u2_L04_challenge','lesson_challenge','M4-2-u2-C4',3,'sa','auto','직사각형 ㅁㅂㅅㅇ에서 변 ㅁㅂ과 변 ㅇㅅ은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u2-C4","difficulty":3,"kind":"sa","stem":"직사각형 ㅁㅂㅅㅇ에서 변 ㅁㅂ과 변 ㅇㅅ은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["변 ㅂㅅ은 위아래 두 변에 모두 수직이에요.","그래서 두 변 사이의 거리는 변 ㅂㅅ의 길이와 같아요.","5 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[15.0,15.0],"ㅂ":[120.0,15.0],"ㅅ":[120.0,75.0],"ㅇ":[15.0,75.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"right":[["ㅇ","ㅁ","ㅂ"],["ㅁ","ㅂ","ㅅ"],["ㅂ","ㅅ","ㅇ"],["ㅅ","ㅇ","ㅁ"]],"lab":[[[67.5,3.75],"9 cm"],[[139.65,45.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정사각형 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 변 ㄹㄷ은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["변 ㄴㄷ은 위아래 두 변에 모두 수직이에요.","그래서 두 변 사이의 거리는 변 ㄴㄷ의 길이와 같아요.","6 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[30.0,15.0],"ㄴ":[90.0,15.0],"ㄷ":[90.0,75.0],"ㄹ":[30.0,75.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"right":[["ㄹ","ㄱ","ㄴ"],["ㄱ","ㄴ","ㄷ"],["ㄴ","ㄷ","ㄹ"],["ㄷ","ㄹ","ㄱ"]],"lab":[[[60.0,3.75],"6 cm"],[[109.65,45.0],"6 cm"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 직사각형 ㅁㅂㅅㅇ에서 변 ㅁㅂ과 변 ㅇㅅ은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["변 ㅂㅅ은 위아래 두 변에 모두 수직이에요.","그래서 두 변 사이의 거리는 변 ㅂㅅ의 길이와 같아요.","5 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[45.0,7.5],"ㅂ":[90.0,7.5],"ㅅ":[90.0,82.5],"ㅇ":[45.0,82.5]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"right":[["ㅇ","ㅁ","ㅂ"],["ㅁ","ㅂ","ㅅ"],["ㅂ","ㅅ","ㅇ"],["ㅅ","ㅇ","ㅁ"]],"lab":[[[67.5,-3.75],"3 cm"],[[109.65,45.0],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EX