INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L04_challenge#7','math',4,2,'u2','L04','g4_2_math_u2_L04_challenge','lesson_challenge','M4-2-u2-C4',3,'sa','auto','책장 선반 가, 나, 다는 서로 평행하고 위에서부터 차례로 있어요. 가와 나 사이는 30 cm, 나와 다 사이는 80 cm예요. 선반 가와 선반 다 사이의 거리는 몇 cm인가요? (선반 두께는 생각하지 않아요.) 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u2-C4","difficulty":3,"kind":"sa","stem":"책장 선반 가, 나, 다는 서로 평행하고 위에서부터 차례로 있어요. 가와 나 사이는 30 cm, 나와 다 사이는 80 cm예요. 선반 가와 선반 다 사이의 거리는 몇 cm인가요? (선반 두께는 생각하지 않아요.) 숫자로 쓰세요.","answer":["110"],"explanation":["세 직선이 차례로 평행하게 놓여 있어요.","가와 다 사이의 거리는 가와 나 사이, 나와 다 사이를 이어 붙인 길이예요.","30 + 80 = 110 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,15.0],[150.0,15.0]],[[0.0,35.45454545454545],[150.0,35.45454545454545]],[[0.0,90.0],[150.0,90.0]]],"lab":[[[9.0,8.25],"가"],[[9.0,28.704545454545453],"나"],[[9.0,83.25],"다"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"책장 선반 가, 나, 다는 서로 평행하고 위에서부터 차례로 있어요. 가와 나 사이는 50 cm, 나와 다 사이는 60 cm예요. 선반 가와 선반 다 사이의 거리는 몇 cm인가요? (선반 두께는 생각하지 않아요.) 숫자로 쓰세요.","answer":["110"],"explanation":["세 직선이 차례로 평행하게 놓여 있어요.","가와 다 사이의 거리는 가와 나 사이, 나와 다 사이를 이어 붙인 길이예요.","50 + 60 = 110 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,15.0],[150.0,15.0]],[[0.0,49.09090909090909],[150.0,49.09090909090909]],[[0.0,90.0],[150.0,90.0]]],"lab":[[[9.0,8.25],"가"],[[9.0,42.3409090909091],"나"],[[9.0,83.25],"다"]]}],"tag":false}},{"stem":"직선 가, 나, 다는 서로 평행하고, 위에서부터 차례로 놓여 있어요. 가와 나 사이의 거리는 7 cm, 나와 다 사이의 거리는 2 cm예요. 직선 가와 직선 다 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["세 직선이 차례로 평행하게 놓여 있어요.","가와 다 사이의 거리는 가와 나 사이, 나와 다 사이를 이어 붙인 길이예요.","7 + 2 = 9 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,15.0],[150.0,15.0]],[[0.0,73.33333333333334],[150.0,73.33333333333334]],[[0.0,90.0],[150.0,90.0]]],"lab":[[[9.0,8.25],"가"],[[9.0,66.58333333333334],"나"],[[9.0,83.25],"다"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L04_challenge#8','math',4,2,'u2','L04','g4_2_math_u2_L04_challenge','lesson_challenge','M4-2-u2-C4',4,'sa','auto','직선 가, 나, 다는 서로 평행해요. 직선 나는 직선 가와 직선 다 사이에 있어요. 가와 나 사이의 거리는 5 cm, 가와 다 사이의 거리는 12 cm예요. 나와 다 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u2-C4","difficulty":4,"kind":"sa","stem":"직선 가, 나, 다는 서로 평행해요. 직선 나는 직선 가와 직선 다 사이에 있어요. 가와 나 사이의 거리는 5 cm, 가와 다 사이의 거리는 12 cm예요. 나와 다 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["세 직선이 놓인 차례를 먼저 그려 봐요.","가와 다 사이의 거리는 가와 나 사이와 나와 다 사이를 이어 붙인 길이예요.","12 − 5 = 7 cm예요."],"variant_rule":{"alt":[{"stem":"직선 가, 나, 다는 서로 평행해요. 직선 다는 직선 가와 직선 나 사이에 있어요. 가와 나 사이의 거리는 15 cm, 가와 다 사이의 거리는 6 cm예요. 나와 다 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["세 직선이 놓인 차례를 먼저 그려 봐요.","다가 가운데에 있으니 가와 나 사이 = 가와 다 사이 + 다와 나 사이예요.","15 − 6 = 9 cm예요."],"asset":null},{"stem":"직선 가, 나, 다는 서로 평행해요. 직선 가는 직선 나와 직선 다 사이에 있어요. 가와 나 사이의 거리는 8 cm, 가와 다 사이의 거리는 11 cm예요. 나와 다 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["세 직선이 놓인 차례를 먼저 그려 봐요.","가가 가운데에 있으니 나와 다 사이 = 나와 가 사이 + 가와 다 사이예요.","8 + 11 = 19 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L04_challenge#9','math',4,2,'u2','L04','g4_2_math_u2_L04_challenge','lesson_challenge','M4-2-u2-C4',4,'sa','auto','책장에 평행한 선반 4개가 같은 간격으로 있어요. 맨 위 선반과 맨 아래 선반 사이의 거리가 36 cm일 때, 이웃한 두 선반 사이의 거리는 몇 cm인가요? (선반 두께는 생각하지 않아요.) 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u2-C4","difficulty":4,"kind":"sa","stem":"책장에 평행한 선반 4개가 같은 간격으로 있어요. 맨 위 선반과 맨 아래 선반 사이의 거리가 36 cm일 때, 이웃한 두 선반 사이의 거리는 몇 cm인가요? (선반 두께는 생각하지 않아요.) 숫자로 쓰세요.","answer":["12"],"explanation":["선반 4개 사이의 간격은 3군데예요.","간격이 모두 같으니 36 cm를 3으로 나눠요.","36 ÷ 3 = 12 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":105,"seg":[[[15.0,7.5],[105.0,7.5]],[[15.0,37.5],[105.0,37.5]],[[15.0,67.5],[105.0,67.5]],[[15.0,97.5],[105.0,97.5]],[[15.0,7.5],[15.0,97.5]],[[105.0,7.5],[105.0,97.5]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"책장에 평행한 선반 5개가 같은 간격으로 있어요. 맨 위 선반과 맨 아래 선반 사이의 거리가 80 cm일 때, 이웃한 두 선반 사이의 거리는 몇 cm인가요? (선반 두께는 생각하지 않아요.) 숫자로 쓰세요.","answer":["20"],"explanation":["선반 5개 사이의 간격은 4군데예요.","간격이 모두 같으니 80 cm를 4로 나눠요.","80 ÷ 4 = 20 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":105,"seg":[[[15.0,7.5],[105.0,7.5]],[[15.0,30.0],[105.0,30.0]],[[15.0,52.5],[105.0,52.5]],[[15.0,75.0],[105.0,75.0]],[[15.0,97.5],[105.0,97.5]],[[15.0,7.5],[15.0,97.5]],[[105.0,7.5],[105.0,97.5]]]}],"tag":false}},{"stem":"책장에 평행한 선반 3개가 같은 간격으로 있어요. 맨 위 선반과 맨 아래 선반 사이의 거리가 50 cm일 때, 이웃한 두 선반 사이의 거리는 몇 cm인가요? (선반 두께는 생각하지 않아요.) 숫자로 쓰세요.","answer":["25"],"explanation":["선반 3개 사이의 간격은 2군데예요.","간격이 모두 같으니 50 cm를 2로 나눠요.","50 ÷ 2 = 25 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":105,"seg":[[[15.0,7.5],[105.0,7.5]],[[15.0,52.5],[105.0,52.5]],[[15.0,97.5],[105.0,97.5]],[[15.0,7.5],[15.0,97.5]],[[105.0,7.5],[105.0,97.5]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L04_challenge#10','math',4,2,'u2','L04','g4_2_math_u2_L04_challenge','lesson_challenge','M4-2-u2-C4',4,'essay','teacher','평행선 사이의 거리를 잴 때 비스듬한 선분이 아니라 수직인 선분의 길이로 재는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u2-C4","difficulty":4,"kind":"essay","stem":"평행선 사이의 거리를 잴 때 비스듬한 선분이 아니라 수직인 선분의 길이로 재는 까닭을 써 보세요.","answer_guide":{"answer":"예: 비스듬한 선분은 어디에 어떻게 긋느냐에 따라 길이가 계속 달라져서 두 직선이 얼마나 떨어져 있는지 하나로 말할 수 없다. 수직인 선분은 가장 짧고 어디에 그어도 길이가 같아서 거리가 하나로 정해진다.","scoring_points":["비스듬한 선분은 길이가 달라진다고 썼는가","수직인 선분은 어디서나 길이가 같다(가장 짧다)고 썼는가","그래서 거리가 하나로 정해진다고 썼는가"]},"explanation":["비스듬한 선분은 긋는 자리마다 길이가 달라요.","수직인 선분은 가장 짧고 어디서나 길이가 같아요.","그래서 거리를 하나로 정할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L05_basic#1','math',4,2,'u2','L05','g4_2_math_u2_L05_basic','lesson_basic','M4-2-u2-C5',1,'mc','auto','사다리꼴은 어떤 사각형인가요?',ARRAY['M4-2-u2-X09','M4-2-u2-X14','M4-2-u2-X18']::text[],true,'{"seq":1,"concept":"M4-2-u2-C5","difficulty":1,"kind":"mc","stem":"사다리꼴은 어떤 사각형인가요?","options":[{"t":"평행한 변이 한 쌍이라도 있는 사각형","correct":true},{"t":"평행한 변이 한 쌍만 있는 사각형","mis":"M4-2-u2-X09"},{"t":"네 변의 길이가 모두 같은 사각형","mis":"M4-2-u2-X14"},{"t":"평행한 변이 없는 사각형","mis":"M4-2-u2-X18"}],"explanation":["사각형을 평행한 변이 있는지로 갈라 봐요.","평행한 변이 한 쌍이라도 있으면 사다리꼴이에요.","「한 쌍만」이 아니라 「한 쌍이라도」예요."],"variant_rule":{"alt":[{"stem":"평행한 변이 한 쌍이라도 있는 사각형을 무엇이라고 하나요?","options":[{"t":"사다리꼴","correct":true},{"t":"평행사변형","mis":"M4-2-u2-X09"},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"직사각형","mis":"M4-2-u2-X10"}],"explanation":["사각형을 평행한 변이 있는지로 갈라 봐요.","평행한 변이 한 쌍이라도 있으면 사다리꼴이에요.","「한 쌍만」이 아니라 「한 쌍이라도」예요."],"asset":null},{"stem":"책장에 기대 놓은 사다리에서 찾은 사각형은 위아래 두 변이 서로 평행해요. 이런 사각형을 무엇이라고 하나요?","options":[{"t":"사다리꼴","correct":true},{"t":"평행사변형","mis":"M4-2-u2-X10"},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"정사각형","mis":"M4-2-u2-X10"}],"explanation":["사각형을 평행한 변이 있는지로 갈라 봐요.","평행한 변이 한 쌍이라도 있으면 사다리꼴이에요.","「한 쌍만」이 아니라 「한 쌍이라도」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L05_basic#2','math',4,2,'u2','L05','g4_2_math_u2_L05_basic','lesson_basic','M4-2-u2-C5',1,'sa','auto','사다리꼴에는 서로 평행한 변이 적어도 몇 쌍 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u2-C5","difficulty":1,"kind":"sa","stem":"사다리꼴에는 서로 평행한 변이 적어도 몇 쌍 있어야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있는 사각형이에요.","한 쌍이 있어도, 두 쌍이 있어도 사다리꼴이에요.","그래서 적어도 1쌍이에요."],"variant_rule":{"alt":[{"stem":"사각형에 서로 평행한 변이 적어도 몇 쌍 있으면 사다리꼴이라고 할 수 있나요? 숫자로 쓰세요.","answer":["1"],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있는 사각형이에요.","한 쌍이 있어도, 두 쌍이 있어도 사다리꼴이에요.","그래서 적어도 1쌍이에요."],"asset":null},{"stem":"평행한 변이 몇 쌍 있는 사각형부터 사다리꼴이라고 부르나요? 가장 작은 수를 숫자로 쓰세요.","answer":["1"],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있는 사각형이에요.","한 쌍이 있어도, 두 쌍이 있어도 사다리꼴이에요.","그래서 적어도 1쌍이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L05_basic#3','math',4,2,'u2','L05','g4_2_math_u2_L05_basic','lesson_basic','M4-2-u2-C5',1,'mc','auto','이 사각형은 위아래(또는 마주 보는) 두 변만 서로 평행해요. 이 사각형의 이름으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u2-X10','M4-2-u2-X14']::text[],true,'{"seq":3,"concept":"M4-2-u2-C5","difficulty":1,"kind":"mc","stem":"이 사각형은 위아래(또는 마주 보는) 두 변만 서로 평행해요. 이 사각형의 이름으로 알맞은 것은 어느 것인가요?","options":[{"t":"사다리꼴","correct":true},{"t":"평행사변형","mis":"M4-2-u2-X10"},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"직사각형","mis":"M4-2-u2-X10"}],"explanation":["마주 보는 변을 늘여 만나는지 봐요.","평행한 변이 한 쌍 있어요.","그래서 사다리꼴이에요 — 두 쌍이 아니라 평행사변형은 아니에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[120.0,75.0],[90.0,15.0],[45.0,15.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 사각형은 위아래(또는 마주 보는) 두 변만 서로 평행해요. 이 사각형의 이름으로 알맞은 것은 어느 것인가요?","options":[{"t":"사다리꼴","correct":true},{"t":"평행사변형","mis":"M4-2-u2-X10"},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"직사각형","mis":"M4-2-u2-X10"}],"explanation":["마주 보는 변을 늘여 만나는지 봐요.","평행한 변이 한 쌍 있어요.","그래서 사다리꼴이에요 — 두 쌍이 아니라 평행사변형은 아니에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,45.0],[75.0,15.0],[105.0,60.0],[75.0,75.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 사각형은 위아래(또는 마주 보는) 두 변만 서로 평행해요. 이 사각형의 이름으로 알맞은 것은 어느 것인가요?","options":[{"t":"사다리꼴","correct":true},{"t":"평행사변형","mis":"M4-2-u2-X10"},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"직사각형","mis":"M4-2-u2-X10"}],"explanation":["마주 보는 변을 늘여 만나는지 봐요.","평행한 변이 한 쌍 있어요.","그래서 사다리꼴이에요 — 두 쌍이 아니라 평행사변형은 아니에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[120.0,75.0],[120.0,15.0],[60.0,15.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind