INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L05_basic#4','math',4,2,'u2','L05','g4_2_math_u2_L05_basic','lesson_basic','M4-2-u2-C5',1,'ox','auto','평행한 변이 한 쌍이라도 있는 사각형은 사다리꼴이에요.',ARRAY['M4-2-u2-X09']::text[],true,'{"seq":4,"concept":"M4-2-u2-C5","difficulty":1,"kind":"ox","stem":"평행한 변이 한 쌍이라도 있는 사각형은 사다리꼴이에요.","answer":"O","reason_options":[{"t":"사다리꼴의 뜻이 그래서","correct":true},{"t":"평행한 변이 꼭 한 쌍만 있어야 해서","mis":"M4-2-u2-X09"}],"mis":"M4-2-u2-X09","explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있는 사각형이에요.","변의 길이나 놓인 모양은 상관없어요.","평행한 변이 없으면 사다리꼴이 아니에요."],"variant_rule":{"alt":[{"stem":"평행한 변이 없는 사각형도 사다리꼴이에요.","answer":"X","reason_options":[{"t":"사다리꼴에는 평행한 변이 한 쌍 이상 있어야 해서","correct":true},{"t":"변이 네 개면 모두 사다리꼴이라서","mis":"M4-2-u2-X10"}],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있는 사각형이에요.","변의 길이나 놓인 모양은 상관없어요.","평행한 변이 없으면 사다리꼴이 아니에요."],"asset":null},{"stem":"사다리꼴은 위쪽 변이 아래쪽 변보다 짧아야 해요.","answer":"X","reason_options":[{"t":"평행한 변이 한 쌍이라도 있으면 되어서","correct":true},{"t":"사다리 모양처럼 위가 좁아야 해서","mis":"M4-2-u2-X10"}],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있는 사각형이에요.","변의 길이나 놓인 모양은 상관없어요.","평행한 변이 없으면 사다리꼴이 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
