INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L05_basic#9','math',4,2,'u2','L05','g4_2_math_u2_L05_basic','lesson_basic','M4-2-u2-C5',2,'mc','auto','직사각형 모양의 종이띠를 비스듬한 선을 따라 잘랐어요. 잘라 낸 사각형들이 모두 사다리꼴인 까닭은 무엇인가요?',ARRAY['M4-2-u2-X14','M4-2-u2-X10']::text[],true,'{"seq":9,"concept":"M4-2-u2-C5","difficulty":2,"kind":"mc","stem":"직사각형 모양의 종이띠를 비스듬한 선을 따라 잘랐어요. 잘라 낸 사각형들이 모두 사다리꼴인 까닭은 무엇인가요?","options":[{"t":"잘라 낸 사각형에도 종이띠의 평행한 두 변이 한 쌍은 남아 있어서","correct":true},{"t":"잘라 낸 사각형의 네 변의 길이가 같아서","mis":"M4-2-u2-X14"},{"t":"잘라 낸 사각형의 네 각이 모두 직각이라서","mis":"M4-2-u2-X10"},{"t":"잘라 낸 사각형의 크기가 모두 같아서","mis":"M4-2-u2-X10"}],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있으면 돼요.","평행한 두 변을 가로질러 자르면 두 조각 모두에 평행한 변 한 쌍이 남아요.","그래서 잘라 낸 사각형은 모두 사다리꼴이에요."],"variant_rule":{"alt":[{"stem":"평행한 두 직선 사이에 선분 두 개를 그어 사각형을 만들었어요. 이 사각형이 언제나 사다리꼴인 까닭은 무엇인가요?","options":[{"t":"평행한 두 직선 위의 두 변이 서로 평행해서","correct":true},{"t":"선분 두 개의 길이가 같아서","mis":"M4-2-u2-X14"},{"t":"네 각이 모두 직각이라서","mis":"M4-2-u2-X10"},{"t":"선분 두 개가 서로 평행해서","mis":"M4-2-u2-X09"}],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있으면 돼요.","평행한 두 변을 가로질러 자르면 두 조각 모두에 평행한 변 한 쌍이 남아요.","그래서 잘라 낸 사각형은 모두 사다리꼴이에요."],"asset":null},{"stem":"사다리꼴 모양의 종이를 평행한 두 변을 가로지르는 선으로 잘랐어요. 잘라 낸 두 도형의 이름으로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 사다리꼴","correct":true},{"t":"둘 다 삼각형","mis":"M4-2-u2-X10"},{"t":"하나는 사다리꼴, 하나는 평행사변형","mis":"M4-2-u2-X09"},{"t":"둘 다 사다리꼴이 아님","mis":"M4-2-u2-X10"}],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있으면 돼요.","평행한 두 변을 가로질러 자르면 두 조각 모두에 평행한 변 한 쌍이 남아요.","그래서 잘라 낸 사각형은 모두 사다리꼴이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L05_basic#10','math',4,2,'u2','L05','g4_2_math_u2_L05_basic','lesson_basic','M4-2-u2-C5',3,'sa','auto','평행한 두 선분 사이에 선분을 그었어요. 그림에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u2-C5","difficulty":3,"kind":"sa","stem":"평행한 두 선분 사이에 선분을 그었어요. 그림에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["위아래 두 선분이 평행해서, 사이를 가로지르는 선분 두 개를 고르면 사다리꼴이 하나 생겨요.","작은 것 2개부터 두 칸·세 칸을 합친 큰 사다리꼴까지 차례로 세어요.","모두 3개예요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"seg":[[[30.0,15.0],[105.0,15.0]],[[15.0,75.0],[120.0,75.0]],[[30.0,15.0],[15.0,75.0]],[[60.0,15.0],[75.0,75.0]],[[105.0,15.0],[120.0,75.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 평행한 두 선분 사이에 선분을 그었어요. 그림에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["위아래 두 선분이 평행해서, 사이를 가로지르는 선분 두 개를 고르면 사다리꼴이 하나 생겨요.","작은 것 2개부터 두 칸·세 칸을 합친 큰 사다리꼴까지 차례로 세어요.","모두 3개예요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"seg":[[[45.0,15.0],[105.0,15.0]],[[15.0,75.0],[135.0,75.0]],[[45.0,15.0],[15.0,75.0]],[[75.0,15.0],[75.0,75.0]],[[105.0,15.0],[135.0,75.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 평행한 두 선분 사이에 선분을 그었어요. 그림에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["위아래 두 선분이 평행해서, 사이를 가로지르는 선분 두 개를 고르면 사다리꼴이 하나 생겨요.","작은 것 3개부터 두 칸·세 칸을 합친 큰 사다리꼴까지 차례로 세어요.","모두 6개예요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"seg":[[[30.0,15.0],[120.0,15.0]],[[15.0,75.0],[135.0,75.0]],[[30.0,15.0],[15.0,75.0]],[[45.0,15.0],[60.0,75.0]],[[90.0,15.0],[75.0,75.0]],[[120.0,15.0],[135.0,75.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes