INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L05_challenge#2','math',4,2,'u2','L05','g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',2,'mc','auto','사다리꼴 ㅁㅂㅅㅇ에서 서로 평행한 변은 어느 것인가요?',ARRAY['M4-2-u2-X10','M4-2-u2-X06']::text[],true,'{"seq":2,"concept":"M4-2-u2-C5","difficulty":2,"kind":"mc","stem":"사다리꼴 ㅁㅂㅅㅇ에서 서로 평행한 변은 어느 것인가요?","options":[{"t":"변 ㅁㅂ과 변 ㅅㅇ","correct":true},{"t":"변 ㅂㅅ과 변 ㅇㅁ","mis":"M4-2-u2-X10"},{"t":"변 ㅁㅂ과 변 ㅂㅅ","mis":"M4-2-u2-X06"},{"t":"평행한 변이 없어요","mis":"M4-2-u2-X10"}],"explanation":["마주 보는 두 쌍의 변을 차례로 늘여 봐요.","변 ㅁㅂ과 변 ㅅㅇ은 아무리 늘여도 만나지 않아요.","다른 한 쌍은 늘이면 만나요 — 평행한 변은 한 쌍이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[15.0,75.0],"ㅂ":[120.0,75.0],"ㅅ":[120.0,15.0],"ㅇ":[60.0,15.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 사다리꼴 ㅁㅂㅅㅇ에서 서로 평행한 변은 어느 것인가요?","options":[{"t":"변 ㅁㅂ과 변 ㅅㅇ","correct":true},{"t":"변 ㅂㅅ과 변 ㅇㅁ","mis":"M4-2-u2-X10"},{"t":"변 ㅁㅂ과 변 ㅂㅅ","mis":"M4-2-u2-X06"},{"t":"평행한 변이 없어요","mis":"M4-2-u2-X10"}],"explanation":["마주 보는 두 쌍의 변을 차례로 늘여 봐요.","변 ㅁㅂ과 변 ㅅㅇ은 아무리 늘여도 만나지 않아요.","다른 한 쌍은 늘이면 만나요 — 평행한 변은 한 쌍이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[15.0,45.0],"ㅂ":[75.0,15.0],"ㅅ":[105.0,60.0],"ㅇ":[75.0,75.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]]}],"tag":false}},{"stem":"사다리꼴 ㄱㄴㄷㄹ에서 서로 평행한 변은 어느 것인가요?","options":[{"t":"변 ㄱㄴ과 변 ㄷㄹ","correct":true},{"t":"변 ㄴㄷ과 변 ㄹㄱ","mis":"M4-2-u2-X10"},{"t":"변 ㄱㄴ과 변 ㄴㄷ","mis":"M4-2-u2-X06"},{"t":"평행한 변이 없어요","mis":"M4-2-u2-X10"}],"explanation":["마주 보는 두 쌍의 변을 차례로 늘여 봐요.","변 ㄱㄴ과 변 ㄷㄹ은 아무리 늘여도 만나지 않아요.","다른 한 쌍은 늘이면 만나요 — 평행한 변은 한 쌍이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[120.0,75.0],"ㄷ":[90.0,15.0],"ㄹ":[45.0,15.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode)