INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L05_challenge#3','math',4,2,'u2','L05','g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',3,'sa','auto','평행한 두 선분 사이에 선분을 그었어요. 그림에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u2-C5","difficulty":3,"kind":"sa","stem":"평행한 두 선분 사이에 선분을 그었어요. 그림에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["위아래 두 선분이 평행해서, 사이를 가로지르는 선분 두 개를 고르면 사다리꼴이 하나 생겨요.","작은 것 3개부터 두 칸·세 칸을 합친 큰 사다리꼴까지 차례로 세어요.","모두 6개예요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"seg":[[[30.0,15.0],[120.0,15.0]],[[15.0,75.0],[135.0,75.0]],[[30.0,15.0],[15.0,75.0]],[[45.0,15.0],[60.0,75.0]],[[90.0,15.0],[75.0,75.0]],[[120.0,15.0],[135.0,75.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 평행한 두 선분 사이에 선분을 그었어요. 그림에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["위아래 두 선분이 평행해서, 사이를 가로지르는 선분 두 개를 고르면 사다리꼴이 하나 생겨요.","작은 것 3개부터 두 칸·세 칸을 합친 큰 사다리꼴까지 차례로 세어요.","모두 6개예요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"seg":[[[30.0,15.0],[120.0,15.0]],[[15.0,75.0],[135.0,75.0]],[[30.0,15.0],[15.0,75.0]],[[60.0,15.0],[60.0,75.0]],[[90.0,15.0],[105.0,75.0]],[[120.0,15.0],[135.0,75.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 평행한 두 선분 사이에 선분을 그었어요. 그림에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["위아래 두 선분이 평행해서, 사이를 가로지르는 선분 두 개를 고르면 사다리꼴이 하나 생겨요.","작은 것 2개부터 두 칸·세 칸을 합친 큰 사다리꼴까지 차례로 세어요.","모두 3개예요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"seg":[[[30.0,15.0],[105.0,15.0]],[[15.0,75.0],[120.0,75.0]],[[30.0,15.0],[15.0,75.0]],[[60.0,15.0],[75.0,75.0]],[[105.0,15.0],[120.0,75.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, st