INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L05_challenge#4','math',4,2,'u2','L05','g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',3,'sa','auto','사다리꼴에서 세 각의 크기가 30°, 120°, 60°일 때 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u2-C5","difficulty":3,"kind":"sa","stem":"사다리꼴에서 세 각의 크기가 30°, 120°, 60°일 때 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["150"],"explanation":["사각형의 네 각의 크기의 합은 360°예요.","세 각의 합은 30° + 120° + 60° = 210°예요.","나머지 한 각은 360° − 210° = 150°예요."],"variant_rule":{"alt":[{"stem":"책장 사다리에서 찾은 사다리꼴의 세 각이 110°, 70°, 85°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["사각형의 네 각의 크기의 합은 360°예요.","세 각의 합은 110° + 70° + 85° = 265°예요.","나머지 한 각은 360° − 265° = 95°예요."],"asset":null},{"stem":"사다리꼴에서 세 각의 크기가 90°, 90°, 55°일 때 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["125"],"explanation":["사각형의 네 각의 크기의 합은 360°예요.","세 각의 합은 90° + 90° + 55° = 235°예요.","나머지 한 각은 360° − 235° = 125°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
