INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L05_challenge#6','math',4,2,'u2','L05','g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',3,'error','auto','사다리꼴에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u2-X09','M4-2-u2-X18']::text[],true,'{"seq":6,"concept":"M4-2-u2-C5","difficulty":3,"kind":"error","stem":"사다리꼴에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「평행사변형은 평행한 변이 두 쌍이라서 사다리꼴이 아니야.」","correct":true,"mis_target":"M4-2-u2-X09"},{"t":"지아 — 「사다리꼴에는 평행한 변이 한 쌍 이상 있어.」","mis":"M4-2-u2-X18"},{"t":"준서 — 「평행한 변이 없는 사각형은 사다리꼴이 아니야.」","mis":"M4-2-u2-X18"},{"t":"민서 — 「기울어져 놓여도 평행한 변이 있으면 사다리꼴이야.」","mis":"M4-2-u2-X18"}],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있는 사각형이에요.","평행한 변이 두 쌍인 평행사변형·직사각형도, 위아래 변의 길이가 같아도 사다리꼴이에요.","하랑의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"사다리꼴에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「사다리꼴은 위아래 변의 길이가 달라야 해.」","correct":true,"mis_target":"M4-2-u2-X10"},{"t":"준서 — 「사다리꼴에는 평행한 변이 한 쌍 이상 있어.」","mis":"M4-2-u2-X18"},{"t":"민서 — 「평행한 변이 없는 사각형은 사다리꼴이 아니야.」","mis":"M4-2-u2-X18"},{"t":"도윤 — 「기울어져 놓여도 평행한 변이 있으면 사다리꼴이야.」","mis":"M4-2-u2-X18"}],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있는 사각형이에요.","평행한 변이 두 쌍인 평행사변형·직사각형도, 위아래 변의 길이가 같아도 사다리꼴이에요.","지아의 말이 잘못되었어요."],"asset":null},{"stem":"사다리꼴에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「직사각형은 사다리꼴이라고 부를 수 없어.」","correct":true,"mis_target":"M4-2-u2-X09"},{"t":"민서 — 「사다리꼴에는 평행한 변이 한 쌍 이상 있어.」","mis":"M4-2-u2-X18"},{"t":"도윤 — 「평행한 변이 없는 사각형은 사다리꼴이 아니야.」","mis":"M4-2-u2-X18"},{"t":"서윤 — 「기울어져 놓여도 평행한 변이 있으면 사다리꼴이야.」","mis":"M4-2-u2-X18"}],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있는 사각형이에요.","평행한 변이 두 쌍인 평행사변형·직사각형도, 위아래 변의 길이가 같아도 사다리꼴이에요.","준서의 말이 잘못되었어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L05_challenge#7','math',4,2,'u2','L05','g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',3,'mc','auto','평행한 두 직선 사이에 선분 두 개를 그어 사각형을 만들었어요. 이 사각형이 언제나 사다리꼴인 까닭은 무엇인가요?',ARRAY['M4-2-u2-X14','M4-2-u2-X10','M4-2-u2-X09']::text[],true,'{"seq":7,"concept":"M4-2-u2-C5","difficulty":3,"kind":"mc","stem":"평행한 두 직선 사이에 선분 두 개를 그어 사각형을 만들었어요. 이 사각형이 언제나 사다리꼴인 까닭은 무엇인가요?","options":[{"t":"평행한 두 직선 위의 두 변이 서로 평행해서","correct":true},{"t":"선분 두 개의 길이가 같아서","mis":"M4-2-u2-X14"},{"t":"네 각이 모두 직각이라서","mis":"M4-2-u2-X10"},{"t":"선분 두 개가 서로 평행해서","mis":"M4-2-u2-X09"}],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있으면 돼요.","평행한 두 변을 가로질러 자르면 두 조각 모두에 평행한 변 한 쌍이 남아요.","그래서 잘라 낸 사각형은 모두 사다리꼴이에요."],"variant_rule":{"alt":[{"stem":"사다리꼴 모양의 종이를 평행한 두 변을 가로지르는 선으로 잘랐어요. 잘라 낸 두 도형의 이름으로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 사다리꼴","correct":true},{"t":"둘 다 삼각형","mis":"M4-2-u2-X10"},{"t":"하나는 사다리꼴, 하나는 평행사변형","mis":"M4-2-u2-X09"},{"t":"둘 다 사다리꼴이 아님","mis":"M4-2-u2-X10"}],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있으면 돼요.","평행한 두 변을 가로질러 자르면 두 조각 모두에 평행한 변 한 쌍이 남아요.","그래서 잘라 낸 사각형은 모두 사다리꼴이에요."],"asset":null},{"stem":"직사각형 모양의 종이띠를 비스듬한 선을 따라 잘랐어요. 잘라 낸 사각형들이 모두 사다리꼴인 까닭은 무엇인가요?","options":[{"t":"잘라 낸 사각형에도 종이띠의 평행한 두 변이 한 쌍은 남아 있어서","correct":true},{"t":"잘라 낸 사각형의 네 변의 길이가 같아서","mis":"M4-2-u2-X14"},{"t":"잘라 낸 사각형의 네 각이 모두 직각이라서","mis":"M4-2-u2-X10"},{"t":"잘라 낸 사각형의 크기가 모두 같아서","mis":"M4-2-u2-X10"}],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있으면 돼요.","평행한 두 변을 가로질러 자르면 두 조각 모두에 평행한 변 한 쌍이 남아요.","그래서 잘라 낸 사각형은 모두 사다리꼴이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L05_challenge#8','math',4,2,'u2','L05','g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',4,'sa','auto','삼각형 안에 아래 변과 평행한 선분 2개를 그었어요. 그림에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u2-C5","difficulty":4,"kind":"sa","stem":"삼각형 안에 아래 변과 평행한 선분 2개를 그었어요. 그림에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["맨 위 조각은 삼각형이라 빼요.","아래 변과 평행한 선분 가운데 두 개를 고르면(아래 변 포함) 사다리꼴이 하나 생겨요.","모두 3개예요."],"asset":{"type":"geo","items":[{"w":150,"h":97.5,"seg":[[[75.0,7.5],[7.5,90.0]],[[75.0,7.5],[142.5,90.0]],[[7.5,90.0],[142.5,90.0]],[[52.5,35.0],[97.5,35.0]],[[30.0,62.50000000000001],[120.0,62.50000000000001]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"삼각형 모양 지붕에 아래 변과 평행한 나무 막대 3개를 댔어요. 그림에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["맨 위 조각은 삼각형이라 빼요.","아래 변과 평행한 선분 가운데 두 개를 고르면(아래 변 포함) 사다리꼴이 하나 생겨요.","모두 6개예요."],"asset":{"type":"geo","items":[{"w":150,"h":97.5,"seg":[[[75.0,7.5],[7.5,90.0]],[[75.0,7.5],[142.5,90.0]],[[7.5,90.0],[142.5,90.0]],[[58.125,28.125],[91.875,28.125]],[[41.25,48.75],[108.75,48.75]],[[24.375,69.375],[125.625,69.375]]]}],"tag":false}},{"stem":"삼각형 안에 아래 변과 평행한 선분 3개를 그었어요. 그림에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["맨 위 조각은 삼각형이라 빼요.","아래 변과 평행한 선분 가운데 두 개를 고르면(아래 변 포함) 사다리꼴이 하나 생겨요.","모두 6개예요."],"asset":{"type":"geo","items":[{"w":150,"h":97.5,"seg":[[[75.0,7.5],[7.5,90.0]],[[75.0,7.5],[142.5,90.0]],[[7.5,90.0],[142.5,90.0]],[[58.125,28.125],[91.875,28.125]],[[34.5,57.0],[115.5,57.0]],[[21.0,73.5],[129.0,73.5]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L05_challenge#9','math',4,2,'u2','L05','g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',4,'sa','auto','평행한 두 선분 사이에 선분을 그었어요. 그림에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u2-C5","difficulty":4,"kind":"sa","stem":"평행한 두 선분 사이에 선분을 그었어요. 그림에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["위아래 두 선분이 평행해서, 사이를 가로지르는 선분 두 개를 고르면 사다리꼴이 하나 생겨요.","작은 것 4개부터 두 칸·세 칸을 합친 큰 사다리꼴까지 차례로 세어요.","모두 10개예요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"seg":[[[15.0,15.0],[135.0,15.0]],[[15.0,75.0],[135.0,75.0]],[[15.0,15.0],[15.0,75.0]],[[45.0,15.0],[30.0,75.0]],[[75.0,15.0],[90.0,75.0]],[[105.0,15.0],[120.0,75.0]],[[135.0,15.0],[135.0,75.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 평행한 두 선분 사이에 선분을 그었어요. 그림에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["위아래 두 선분이 평행해서, 사이를 가로지르는 선분 두 개를 고르면 사다리꼴이 하나 생겨요.","작은 것 3개부터 두 칸·세 칸을 합친 큰 사다리꼴까지 차례로 세어요.","모두 6개예요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"seg":[[[30.0,15.0],[120.0,15.0]],[[15.0,75.0],[135.0,75.0]],[[30.0,15.0],[15.0,75.0]],[[60.0,15.0],[60.0,75.0]],[[90.0,15.0],[105.0,75.0]],[[120.0,15.0],[135.0,75.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 평행한 두 선분 사이에 선분을 그었어요. 그림에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["위아래 두 선분이 평행해서, 사이를 가로지르는 선분 두 개를 고르면 사다리꼴이 하나 생겨요.","작은 것 3개부터 두 칸·세 칸을 합친 큰 사다리꼴까지 차례로 세어요.","모두 6개예요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"seg":[[[30.0,15.0],[120.0,15.0]],[[15.0,75.0],[135.0,75.0]],[[30.0,15.0],[15.0,75.0]],[[45.0,15.0],[60.0,75.0]],[[90.0,15.0],[75.0,75.0]],[[120.0,15.0],[135.0,75.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L05_challenge#10','math',4,2,'u2','L05','g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',4,'essay','teacher','평행사변형도 사다리꼴이라고 할 수 있는지 쓰고, 그 까닭을 사다리꼴의 뜻을 써서 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u2-C5","difficulty":4,"kind":"essay","stem":"평행사변형도 사다리꼴이라고 할 수 있는지 쓰고, 그 까닭을 사다리꼴의 뜻을 써서 설명해 보세요.","answer_guide":{"answer":"예: 할 수 있다. 사다리꼴은 평행한 변이 한 쌍이라도 있는 사각형이다. 평행사변형은 마주 보는 두 쌍의 변이 서로 평행하므로 평행한 변이 한 쌍은 분명히 있다. 그래서 평행사변형도 사다리꼴이다.","scoring_points":["할 수 있다고 판단했는가","사다리꼴의 뜻(평행한 변이 한 쌍이라도)을 썼는가","평행사변형에 평행한 변이 있다는 것과 이어 설명했는가"]},"explanation":["사다리꼴: 평행한 변이 한 쌍이라도 있는 사각형.","평행사변형은 평행한 변이 두 쌍 — 한 쌍은 분명히 있어요.","그래서 평행사변형도 사다리꼴이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L06_basic#1','math',4,2,'u2','L06','g4_2_math_u2_L06_basic','lesson_basic','M4-2-u2-C6',1,'mc','auto','평행사변형은 어떤 사각형인가요?',ARRAY['M4-2-u2-X09','M4-2-u2-X14','M4-2-u2-X11']::text[],true,'{"seq":1,"concept":"M4-2-u2-C6","difficulty":1,"kind":"mc","stem":"평행사변형은 어떤 사각형인가요?","options":[{"t":"마주 보는 두 쌍의 변이 서로 평행한 사각형","correct":true},{"t":"평행한 변이 한 쌍만 있는 사각형","mis":"M4-2-u2-X09"},{"t":"네 변의 길이가 모두 같은 사각형","mis":"M4-2-u2-X14"},{"t":"네 각이 모두 직각인 사각형","mis":"M4-2-u2-X11"}],"explanation":["평행한 변이 몇 쌍인지 세어 봐요.","마주 보는 두 쌍의 변이 모두 평행하면 평행사변형이에요.","평행사변형은 평행한 변이 있으니 사다리꼴이기도 해요."],"variant_rule":{"alt":[{"stem":"마주 보는 두 쌍의 변이 서로 평행한 사각형을 무엇이라고 하나요?","options":[{"t":"평행사변형","correct":true},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"직사각형","mis":"M4-2-u2-X11"},{"t":"평행선","mis":"M4-2-u2-X02"}],"explanation":["평행한 변이 몇 쌍인지 세어 봐요.","마주 보는 두 쌍의 변이 모두 평행하면 평행사변형이에요.","평행사변형은 평행한 변이 있으니 사다리꼴이기도 해요."],"asset":null},{"stem":"계단 난간에서 찾은 사각형은 마주 보는 두 쌍의 변이 서로 평행해요. 이 사각형의 이름으로 알맞은 것은 무엇인가요?","options":[{"t":"평행사변형","correct":true},{"t":"정사각형","mis":"M4-2-u2-X10"},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"평행선","mis":"M4-2-u2-X02"}],"explanation":["평행한 변이 몇 쌍인지 세어 봐요.","마주 보는 두 쌍의 변이 모두 평행하면 평행사변형이에요.","평행사변형은 평행한 변이 있으니 사다리꼴이기도 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L06_basic#2','math',4,2,'u2','L06','g4_2_math_u2_L06_basic','lesson_basic','M4-2-u2-C7',1,'sa','auto','평행사변형 ㄱㄴㄷㄹ에서 변 ㄹㄷ의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u2-C7","difficulty":1,"kind":"sa","stem":"평행사변형 ㄱㄴㄷㄹ에서 변 ㄹㄷ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["평행사변형은 마주 보는 두 변의 길이가 같아요.","변 ㄹㄷ과 마주 보는 변은 변 ㄱㄴ이에요.","그래서 9 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[120.0,15.0],"ㄹ":[45.0,15.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[52.5,86.25],"9 cm"],[[121.78230589874906,53.39115294937453],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"평행사변형 ㅁㅂㅅㅇ에서 변 ㅇㅅ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["평행사변형은 마주 보는 두 변의 길이가 같아요.","변 ㅇㅅ과 마주 보는 변은 변 ㅁㅂ이에요.","그래서 12 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[15.0,15.0],"ㅂ":[90.0,15.0],"ㅅ":[120.0,75.0],"ㅇ":[45.0,75.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"lab":[[[52.5,3.75],"12 cm"],[[121.78230589874906,36.60884705062547],"7 cm"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 평행사변형 ㄱㄴㄷㄹ에서 변 ㄹㄷ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["평행사변형은 마주 보는 두 변의 길이가 같아요.","변 ㄹㄷ과 마주 보는 변은 변 ㄱㄴ이에요.","그래서 14 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[120.0,15.0],"ㄹ":[45.0,15.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[52.5,86.25],"14 cm"],[[121.78230589874906,53.39115294937453],"6 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L06_basic#3','math',4,2,'u2','L06','g4_2_math_u2_L06_basic','lesson_basic','M4-2-u2-C7',1,'sa','auto','평행사변형에서 한 각의 크기가 125°일 때, 이 각과 이웃한 각의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u2-C7","difficulty":1,"kind":"sa","stem":"평행사변형에서 한 각의 크기가 125°일 때, 이 각과 이웃한 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","이웃한 각 = 180° − 125°.","55°예요."],"variant_rule":{"alt":[{"stem":"계단 난간에서 찾은 평행사변형의 한 각이 70°예요. 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","이웃한 각 = 180° − 70°.","110°예요."],"asset":null},{"stem":"평행사변형에서 한 각의 크기가 105°일 때, 이 각과 이웃한 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","이웃한 각 = 180° − 105°.","75°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
