INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L06_basic#5','math',4,2,'u2','L06','g4_2_math_u2_L06_basic','lesson_basic','M4-2-u2-C7',2,'mc','auto','모든 평행사변형이 가진 성질이 아닌 것은 어느 것인가요?',ARRAY['M4-2-u2-X18']::text[],true,'{"seq":5,"concept":"M4-2-u2-C7","difficulty":2,"kind":"mc","stem":"모든 평행사변형이 가진 성질이 아닌 것은 어느 것인가요?","options":[{"t":"네 변의 길이가 모두 같다","correct":true},{"t":"마주 보는 두 변의 길이가 같다","mis":"M4-2-u2-X18"},{"t":"마주 보는 두 각의 크기가 같다","mis":"M4-2-u2-X18"},{"t":"이웃한 두 각의 크기의 합이 180°이다","mis":"M4-2-u2-X18"}],"explanation":["평행사변형: 마주 보는 두 쌍의 변이 평행 · 마주 보는 변의 길이가 같음 · 마주 보는 각이 같음 · 이웃한 두 각의 합 180°.","「네 변의 길이가 모두 같다」는 어떤 평행사변형에만 맞는 말이에요.","그래서 모든 평행사변형의 성질은 아니에요."],"variant_rule":{"alt":[{"stem":"모든 평행사변형이 가진 성질이 아닌 것은 어느 것인가요?","options":[{"t":"이웃한 두 각의 크기가 같다","correct":true},{"t":"마주 보는 두 쌍의 변이 서로 평행하다","mis":"M4-2-u2-X18"},{"t":"마주 보는 두 각의 크기가 같다","mis":"M4-2-u2-X18"},{"t":"마주 보는 두 변의 길이가 같다","mis":"M4-2-u2-X18"}],"explanation":["평행사변형: 마주 보는 두 쌍의 변이 평행 · 마주 보는 변의 길이가 같음 · 마주 보는 각이 같음 · 이웃한 두 각의 합 180°.","「이웃한 두 각의 크기가 같다」는 어떤 평행사변형에만 맞는 말이에요.","그래서 모든 평행사변형의 성질은 아니에요."],"asset":null},{"stem":"모든 평행사변형이 가진 성질이 아닌 것은 어느 것인가요?","options":[{"t":"네 각이 모두 직각이다","correct":true},{"t":"이웃한 두 각의 크기의 합이 180°이다","mis":"M4-2-u2-X18"},{"t":"마주 보는 두 변의 길이가 같다","mis":"M4-2-u2-X18"},{"t":"마주 보는 두 쌍의 변이 서로 평행하다","mis":"M4-2-u2-X18"}],"explanation":["평행사변형: 마주 보는 두 쌍의 변이 평행 · 마주 보는 변의 길이가 같음 · 마주 보는 각이 같음 · 이웃한 두 각의 합 180°.","「네 각이 모두 직각이다」는 어떤 평행사변형에만 맞는 말이에요.","그래서 모든 평행사변형의 성질은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
