INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L06_basic#8','math',4,2,'u2','L06','g4_2_math_u2_L06_basic','lesson_basic','M4-2-u2-C7',2,'sa','auto','평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u2-C7","difficulty":2,"kind":"sa","stem":"평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["마주 보는 두 변의 길이가 같아 네 변은 7 cm 둘, 4 cm 둘이에요.","7 + 4 + 7 + 4를 계산해요.","22 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[120.0,15.0],"ㄹ":[45.0,15.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[52.5,86.25],"7 cm"],[[121.78230589874906,53.39115294937453],"4 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"평행사변형 ㅁㅂㅅㅇ의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["마주 보는 두 변의 길이가 같아 네 변은 9 cm 둘, 6 cm 둘이에요.","9 + 6 + 9 + 6을 계산해요.","30 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[15.0,60.0],"ㅂ":[75.0,30.0],"ㅅ":[105.0,60.0],"ㅇ":[45.0,90.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"lab":[[[38.28884705062548,31.577694101250948],"9 cm"],[[102.15495128834866,32.84504871165134],"6 cm"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["34"],"explanation":["마주 보는 두 변의 길이가 같아 네 변은 12 cm 둘, 5 cm 둘이에요.","12 + 5 + 12 + 5를 계산해요.","34 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,15.0],"ㄴ":[90.0,15.0],"ㄷ":[120.0,75.0],"ㄹ":[45.0,75.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[52.5,3.75],"12 cm"],[[121.78230589874906,36.60884705062547],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.