INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L06_basic#9','math',4,2,'u2','L06','g4_2_math_u2_L06_basic','lesson_basic','M4-2-u2-C7',2,'match','auto','평행사변형에서 알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u2-C7","difficulty":2,"kind":"match","stem":"평행사변형에서 알맞은 것끼리 이으세요.","pairs":[{"l":"마주 보는 두 변","r":"길이가 같아요"},{"l":"마주 보는 두 각","r":"크기가 같아요"},{"l":"이웃한 두 각","r":"크기의 합이 180°예요"}],"mis":"M4-2-u2-X12","explanation":["평행사변형은 마주 보는 변과 각이 서로 같아요.","이웃한 두 각의 크기를 더하면 180°예요.","평행한 변이 한 쌍이라도 있으면 사다리꼴, 두 쌍이면 평행사변형이에요."],"variant_rule":{"alt":[{"stem":"사각형의 특징과 이름을 알맞게 이으세요.","pairs":[{"l":"평행한 변이 한 쌍이라도","r":"사다리꼴"},{"l":"마주 보는 두 쌍의 변이 평행","r":"평행사변형"},{"l":"평행한 변이 없음","r":"사다리꼴이 아닌 사각형"}],"explanation":["평행사변형은 마주 보는 변과 각이 서로 같아요.","이웃한 두 각의 크기를 더하면 180°예요.","평행한 변이 한 쌍이라도 있으면 사다리꼴, 두 쌍이면 평행사변형이에요."],"asset":null},{"stem":"평행사변형의 한 각과 그 각에 이웃한 각을 알맞게 이으세요.","pairs":[{"l":"한 각이 70°","r":"이웃한 각은 110°"},{"l":"한 각이 120°","r":"이웃한 각은 60°"},{"l":"한 각이 90°","r":"이웃한 각도 90°"}],"explanation":["평행사변형은 마주 보는 변과 각이 서로 같아요.","이웃한 두 각의 크기를 더하면 180°예요.","평행한 변이 한 쌍이라도 있으면 사다리꼴, 두 쌍이면 평행사변형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L06_basic#10','math',4,2,'u2','L06','g4_2_math_u2_L06_basic','lesson_basic','M4-2-u2-C7',3,'sa','auto','평행사변형의 네 변의 길이의 합이 40 cm이고 한 변이 15 cm일 때, 이 변과 이웃한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u2-C7","difficulty":3,"kind":"sa","stem":"평행사변형의 네 변의 길이의 합이 40 cm이고 한 변이 15 cm일 때, 이 변과 이웃한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["마주 보는 변의 길이가 같아 (한 변 + 이웃한 변) × 2 = 40 cm예요.","한 변 + 이웃한 변 = 40 ÷ 2 = 20 cm.","이웃한 변 = 20 − 15 = 5 cm예요."],"variant_rule":{"alt":[{"stem":"평행사변형 모양 화단의 둘레가 36 m이고 한 변이 11 m예요. 이 변과 이웃한 변은 몇 m인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["마주 보는 변의 길이가 같아 (한 변 + 이웃한 변) × 2 = 36 m예요.","한 변 + 이웃한 변 = 36 ÷ 2 = 18 m.","이웃한 변 = 18 − 11 = 7 m예요."],"asset":null},{"stem":"평행사변형의 네 변의 길이의 합이 50 cm이고 한 변이 16 cm일 때, 이 변과 이웃한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["마주 보는 변의 길이가 같아 (한 변 + 이웃한 변) × 2 = 50 cm예요.","한 변 + 이웃한 변 = 50 ÷ 2 = 25 cm.","이웃한 변 = 25 − 16 = 9 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
