INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L06_challenge#2','math',4,2,'u2','L06','g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C7',2,'sa','auto','계단 난간에서 찾은 평행사변형의 한 각이 40°예요. 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u2-C7","difficulty":2,"kind":"sa","stem":"계단 난간에서 찾은 평행사변형의 한 각이 40°예요. 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["140"],"explanation":["평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","이웃한 각 = 180° − 40°.","140°예요."],"variant_rule":{"alt":[{"stem":"계단 난간에서 찾은 평행사변형의 한 각이 70°예요. 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","이웃한 각 = 180° − 70°.","110°예요."],"asset":null},{"stem":"평행사변형에서 한 각의 크기가 125°일 때, 이 각과 이웃한 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","이웃한 각 = 180° − 125°.","55°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L06_challenge#3','math',4,2,'u2','L06','g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C7',3,'sa','auto','평행사변형 ㄱㄴㄷㄹ에서 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u2-C7","difficulty":3,"kind":"sa","stem":"평행사변형 ㄱㄴㄷㄹ에서 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["㉠은 70°인 각과 이웃한 각이에요.","평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","㉠ = 180° − 70° = 110°예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,60.0],"ㄴ":[75.0,30.0],"ㄷ":[105.0,60.0],"ㄹ":[45.0,90.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[30.699934816962536,62.54774868689275],"70°"],[[72.5972663548955,44.806311864562446],"㉠"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"평행사변형 ㅁㅂㅅㅇ에서 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["㉠은 115°인 각과 이웃한 각이에요.","평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","㉠ = 180° − 115° = 65°예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[15.0,75.0],"ㅂ":[90.0,75.0],"ㅅ":[120.0,15.0],"ㅇ":[45.0,15.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"lab":[[[82.11403331821299,62.24023787471941],"115°"],[[104.95228390462597,24.3],"㉠"]]}],"tag":false}},{"stem":"평행사변형 ㅁㅂㅅㅇ에서 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["135"],"explanation":["㉠은 45°인 각과 이웃한 각이에요.","평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","㉠ = 180° − 45° = 135°예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[15.0,75.0],"ㅂ":[75.0,75.0],"ㅅ":[120.0,30.0],"ㅇ":[60.0,30.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"lab":[[[37.452186130069784,65.7],"45°"],[[69.25974851452365,61.141807012330695],"㉠"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCL