INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L06_challenge#4','math',4,2,'u2','L06','g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C7',3,'error','auto','평행사변형 ㄱㄴㄷㄹ에서 각 ㄴㄱㄹ이 70°예요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u2-X12','M4-2-u2-X18']::text[],true,'{"seq":4,"concept":"M4-2-u2-C7","difficulty":3,"kind":"error","stem":"평행사변형 ㄱㄴㄷㄹ에서 각 ㄴㄱㄹ이 70°예요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「각 ㄱㄴㄷ도 70°야.」","correct":true,"mis_target":"M4-2-u2-X12"},{"t":"준서 — 「각 ㄴㄷㄹ도 70°야.」","mis":"M4-2-u2-X18"},{"t":"민서 — 「각 ㄱㄴㄷ은 110°야.」","mis":"M4-2-u2-X18"},{"t":"도윤 — 「네 각을 모두 더하면 360°야.」","mis":"M4-2-u2-X18"}],"explanation":["각 ㄱㄴㄷ은 각 ㄴㄱㄹ과 이웃한 각이에요.","이웃한 두 각의 합은 180° — 각 ㄱㄴㄷ = 180° − 70° = 110°.","70°가 같은 것은 마주 보는 각 ㄴㄷㄹ이에요."],"variant_rule":{"alt":[{"stem":"평행사변형 ㄱㄴㄷㄹ에서 각 ㄴㄱㄹ이 115°예요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「각 ㄱㄴㄷ도 115°야.」","correct":true,"mis_target":"M4-2-u2-X12"},{"t":"민서 — 「각 ㄴㄷㄹ도 115°야.」","mis":"M4-2-u2-X18"},{"t":"도윤 — 「각 ㄱㄴㄷ은 65°야.」","mis":"M4-2-u2-X18"},{"t":"서윤 — 「네 각을 모두 더하면 360°야.」","mis":"M4-2-u2-X18"}],"explanation":["각 ㄱㄴㄷ은 각 ㄴㄱㄹ과 이웃한 각이에요.","이웃한 두 각의 합은 180° — 각 ㄱㄴㄷ = 180° − 115° = 65°.","115°가 같은 것은 마주 보는 각 ㄴㄷㄹ이에요."],"asset":null},{"stem":"평행사변형 ㄱㄴㄷㄹ에서 각 ㄴㄱㄹ이 55°예요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「각 ㄱㄴㄷ도 55°야.」","correct":true,"mis_target":"M4-2-u2-X12"},{"t":"도윤 — 「각 ㄴㄷㄹ도 55°야.」","mis":"M4-2-u2-X18"},{"t":"서윤 — 「각 ㄱㄴㄷ은 125°야.」","mis":"M4-2-u2-X18"},{"t":"시우 — 「네 각을 모두 더하면 360°야.」","mis":"M4-2-u2-X18"}],"explanation":["각 ㄱㄴㄷ은 각 ㄴㄱㄹ과 이웃한 각이에요.","이웃한 두 각의 합은 180° — 각 ㄱㄴㄷ = 180° − 55° = 125°.","55°가 같은 것은 마주 보는 각 ㄴㄷㄹ이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCL