0],[102.0,75.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L06_challenge#6','math',4,2,'u2','L06','g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C7',3,'sa','auto','평행사변형 모양 화단의 둘레가 36 m이고 한 변이 11 m예요. 이 변과 이웃한 변은 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u2-C7","difficulty":3,"kind":"sa","stem":"평행사변형 모양 화단의 둘레가 36 m이고 한 변이 11 m예요. 이 변과 이웃한 변은 몇 m인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["마주 보는 변의 길이가 같아 (한 변 + 이웃한 변) × 2 = 36 m예요.","한 변 + 이웃한 변 = 36 ÷ 2 = 18 m.","이웃한 변 = 18 − 11 = 7 m예요."],"variant_rule":{"alt":[{"stem":"평행사변형의 네 변의 길이의 합이 50 cm이고 한 변이 16 cm일 때, 이 변과 이웃한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["마주 보는 변의 길이가 같아 (한 변 + 이웃한 변) × 2 = 50 cm예요.","한 변 + 이웃한 변 = 50 ÷ 2 = 25 cm.","이웃한 변 = 25 − 16 = 9 cm예요."],"asset":null},{"stem":"평행사변형의 네 변의 길이의 합이 40 cm이고 한 변이 15 cm일 때, 이 변과 이웃한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["마주 보는 변의 길이가 같아 (한 변 + 이웃한 변) × 2 = 40 cm예요.","한 변 + 이웃한 변 = 40 ÷ 2 = 20 cm.","이웃한 변 = 20 − 15 = 5 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L06_challenge#7','math',4,2,'u2','L06','g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C6',3,'ox','auto','이 정사각형은 평행사변형이라고 할 수 있어요.',ARRAY['M4-2-u2-X11']::text[],true,'{"seq":7,"concept":"M4-2-u2-C6","difficulty":3,"kind":"ox","stem":"이 정사각형은 평행사변형이라고 할 수 있어요.","answer":"O","reason_options":[{"t":"마주 보는 두 쌍의 변이 서로 평행하면 평행사변형이라서","correct":true},{"t":"평행사변형은 기울어져 있어야 해서","mis":"M4-2-u2-X11"}],"mis":"M4-2-u2-X11","explanation":["평행사변형의 뜻에는 「기울어져 있어야 한다」는 말이 없어요.","이 사각형은 마주 보는 두 쌍의 변이 서로 평행해요.","그래서 평행사변형이에요(직사각형·정사각형도 평행사변형)."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[30.0,15.0],[90.0,15.0],[90.0,75.0],[30.0,75.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"평행사변형은 비스듬히 기울어진 모양이어야 해요.","answer":"X","reason_options":[{"t":"마주 보는 두 쌍의 변이 서로 평행하면 평행사변형이라서","correct":true},{"t":"평행사변형은 기울어져 있어야 해서","mis":"M4-2-u2-X11"}],"explanation":["평행사변형의 뜻에는 「기울어져 있어야 한다」는 말이 없어요.","이 사각형은 마주 보는 두 쌍의 변이 서로 평행해요.","그래서 평행사변형이에요(직사각형·정사각형도 평행사변형)."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,45.0],[75.0,15.0],[90.0,45.0],[30.0,75.0]]]}],"tag":false}},{"stem":"기울어지지 않은 이 사각형은 평행사변형이 아니에요.","answer":"X","reason_options":[{"t":"마주 보는 두 쌍의 변이 서로 평행하면 평행사변형이라서","correct":true},{"t":"평행사변형은 기울어져 있어야 해서","mis":"M4-2-u2-X11"}],"explanation":["평행사변형의 뜻에는 「기울어져 있어야 한다」는 말이 없어요.","이 사각형은 마주 보는 두 쌍의 변이 서로 평행해요.","그래서 평행사변형이에요(직사각형·정사각형도 평행사변형)."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,15.0],[120.0,15.0],[120.0,75.0],[15.0,75.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L06_challenge#8','math',4,2,'u2','L06','g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C7',4,'sa','auto','평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 30 cm예요. 변 ㄴㄷ은 변 ㄱㄴ보다 3 cm 더 길어요. 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u2-C7","difficulty":4,"kind":"sa","stem":"평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 30 cm예요. 변 ㄴㄷ은 변 ㄱㄴ보다 3 cm 더 길어요. 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["변 ㄱㄴ + 변 ㄴㄷ = 30 ÷ 2 = 15 cm예요.","두 변의 차가 3 cm이니 긴 변은 (15 + 3) ÷ 2예요.","변 ㄴㄷ = 9 cm(변 ㄱㄴ = 6 cm)예요."],"variant_rule":{"alt":[{"stem":"평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 44 cm예요. 변 ㄴㄷ은 변 ㄱㄴ보다 6 cm 더 길어요. 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["변 ㄱㄴ + 변 ㄴㄷ = 44 ÷ 2 = 22 cm예요.","두 변의 차가 6 cm이니 긴 변은 (22 + 6) ÷ 2예요.","변 ㄴㄷ = 14 cm(변 ㄱㄴ = 8 cm)예요."],"asset":null},{"stem":"평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 26 cm예요. 변 ㄴㄷ은 변 ㄱㄴ보다 5 cm 더 길어요. 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["변 ㄱㄴ + 변 ㄴㄷ = 26 ÷ 2 = 13 cm예요.","두 변의 차가 5 cm이니 긴 변은 (13 + 5) ÷ 2예요.","변 ㄴㄷ = 9 cm(변 ㄱㄴ = 4 cm)예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L06_challenge#9','math',4,2,'u2','L06','g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C7',4,'sa','auto','평행사변형에서 이웃한 두 각 가운데 한 각이 다른 각보다 40° 더 커요. 큰 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u2-C7","difficulty":4,"kind":"sa","stem":"평행사변형에서 이웃한 두 각 가운데 한 각이 다른 각보다 40° 더 커요. 큰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["이웃한 두 각의 합은 180°예요.","큰 각 = 작은 각 + 40° — 두 각을 합하면 작은 각 둘 + 40° = 180°.","작은 각 70°, 큰 각 110°예요."],"variant_rule":{"alt":[{"stem":"평행사변형에서 이웃한 두 각 가운데 한 각이 다른 각보다 20° 더 커요. 큰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["이웃한 두 각의 합은 180°예요.","큰 각 = 작은 각 + 20° — 두 각을 합하면 작은 각 둘 + 20° = 180°.","작은 각 80°, 큰 각 100°예요."],"asset":null},{"stem":"평행사변형에서 이웃한 두 각 가운데 한 각이 다른 각보다 60° 더 커요. 큰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["이웃한 두 각의 합은 180°예요.","큰 각 = 작은 각 + 60° — 두 각을 합하면 작은 각 둘 + 60° = 180°.","작은 각 60°, 큰 각 120°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L06_challenge#10','math',4,2,'u2','L06','g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C7',4,'essay','teacher','평행사변형의 성질을 세 가지 쓰고, 자와 각도기로 어떻게 확인할 수 있는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u2-C7","difficulty":4,"kind":"essay","stem":"평행사변형의 성질을 세 가지 쓰고, 자와 각도기로 어떻게 확인할 수 있는지 써 보세요.","answer_guide":{"answer":"예: ① 마주 보는 두 변의 길이가 같다 — 자로 마주 보는 변을 재어 본다. ② 마주 보는 두 각의 크기가 같다 — 각도기로 마주 보는 각을 재어 본다. ③ 이웃한 두 각의 크기의 합이 180°이다 — 이웃한 두 각을 재어 더해 본다.","scoring_points":["성질 세 가지를 바르게 썼는가","변은 자로, 각은 각도기로 재어 확인한다고 썼는가","「마주 보는」·「이웃한」을 섞지 않고 썼는가"]},"explanation":["마주 보는 변의 길이가 같아요 — 자로 재요.","마주 보는 각의 크기가 같아요 — 각도기로 재요.","이웃한 두 각의 합이 180°예요 — 재어 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_basic#1','math',4,2,'u2','L07','g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',1,'mc','auto','마름모는 어떤 사각형인가요?',ARRAY['M4-2-u2-X14','M4-2-u2-X09','M4-2-u2-X12']::text[],true,'{"seq":1,"concept":"M4-2-u2-C8","difficulty":1,"kind":"mc","stem":"마름모는 어떤 사각형인가요?","options":[{"t":"네 변의 길이가 모두 같은 사각형","correct":true},{"t":"네 각이 모두 직각인 사각형","mis":"M4-2-u2-X14"},{"t":"평행한 변이 한 쌍만 있는 사각형","mis":"M4-2-u2-X09"},{"t":"마주 보는 두 각의 크기가 다른 사각형","mis":"M4-2-u2-X12"}],"explanation":["사각형을 변의 길이로 갈라 봐요.","네 변의 길이가 모두 같으면 마름모예요.","세워 놓였든 눕혀 놓였든, 각이 직각이든 아니든 상관없어요."],"variant_rule":{"alt":[{"stem":"네 변의 길이가 모두 같은 사각형을 무엇이라고 하나요?","options":[{"t":"마름모","correct":true},{"t":"직사각형","mis":"M4-2-u2-X14"},{"t":"사다리꼴만","mis":"M4-2-u2-X09"},{"t":"평행선","mis":"M4-2-u2-X02"}],"explanation":["사각형을 변의 길이로 갈라 봐요.","네 변의 길이가 모두 같으면 마름모예요.","세워 놓였든 눕혀 놓였든, 각이 직각이든 아니든 상관없어요."],"asset":null},{"stem":"학교 정문 안내판에서 네 변의 길이가 모두 같은 사각형을 찾았어요. 이 사각형의 이름으로 알맞은 것은 무엇인가요?","options":[{"t":"마름모","correct":true},{"t":"직사각형","mis":"M4-2-u2-X14"},{"t":"평행선","mis":"M4-2-u2-X02"},{"t":"삼각형","mis":"M4-2-u2-X18"}],"explanation":["사각형을 변의 길이로 갈라 봐요.","네 변의 길이가 모두 같으면 마름모예요.","세워 놓였든 눕혀 놓였든, 각이 직각이든 아니든 상관없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_basic#2','math',4,2,'u2','L07','g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',1,'sa','auto','마름모 ㄱㄴㄷㄹ에서 변 ㄷㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u2-C8","difficulty":1,"kind":"sa","stem":"마름모 ㄱㄴㄷㄹ에서 변 ㄷㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","변 ㄷㄹ도 변 ㄱㄴ과 길이가 같아요.","9 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[60.0,7.5],"ㄴ":[105.0,45.0],"ㄷ":[60.0,82.5],"ㄹ":[15.0,45.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[93.14469744704508,13.476363063545914],"9 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"마름모 ㅁㅂㅅㅇ에서 변 ㅅㅇ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","변 ㅅㅇ도 변 ㅁㅂ과 길이가 같아요.","13 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[15.0,75.0],"ㅂ":[90.0,75.0],"ㅅ":[135.0,15.0],"ㅇ":[60.0,15.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"lab":[[[52.5,86.25],"13 cm"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 마름모 ㄱㄴㄷㄹ에서 변 ㄷㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","변 ㄷㄹ도 변 ㄱㄴ과 길이가 같아요.","7 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,60.0],"ㄴ":[75.0,30.0],"ㄷ":[135.0,60.0],"ㄹ":[75.0,90.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[38.28884705062548,31.577694101250948],"7 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_basic#3','math',4,2,'u2','L07','g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',1,'mc','auto','마름모에서 마주 보는 꼭짓점끼리 이은 두 선분은 어떻게 만나나요?',ARRAY['M4-2-u2-X15','M4-2-u2-X05','M4-2-u2-X02']::text[],true,'{"seq":3,"concept":"M4-2-u2-C8","difficulty":1,"kind":"mc","stem":"마름모에서 마주 보는 꼭짓점끼리 이은 두 선분은 어떻게 만나나요?","options":[{"t":"서로 수직으로 만난다","correct":true},{"t":"비스듬하게 만난다","mis":"M4-2-u2-X15"},{"t":"만나지 않는다","mis":"M4-2-u2-X05"},{"t":"서로 평행하다","mis":"M4-2-u2-X02"}],"explanation":["마름모에서 마주 보는 꼭짓점끼리 선분을 그어 봐요.","두 선분은 서로 수직으로 만나요.","그리고 서로를 똑같이 반으로 나눠요(두 선분의 길이는 다를 수 있어요)."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[60.0,7.5],"ㄴ":[105.0,45.0],"ㄷ":[60.0,82.5],"ㄹ":[15.0,45.0],"ㅇ":[60.0,45.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[60.0,45.0],"ㄴ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"마름모에서 마주 보는 꼭짓점끼리 이은 두 선분이 만나서 이루는 각은 몇 도인가요?","options":[{"t":"90°","correct":true},{"t":"60°","mis":"M4-2-u2-X15"},{"t":"180°","mis":"M4-2-u2-X15"},{"t":"45°","mis":"M4-2-u2-X15"}],"explanation":["마름모에서 마주 보는 꼭짓점끼리 선분을 그어 봐요.","두 선분은 서로 수직으로 만나요.","그리고 서로를 똑같이 반으로 나눠요(두 선분의 길이는 다를 수 있어요)."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[135.0,15.0],"ㄹ":[60.0,15.0],"ㅇ":[75.0,45.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[75.0,45.0],"ㄴ"]]}],"tag":false}},{"stem":"마름모에서 마주 보는 꼭짓점끼리 이은 두 선분에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"서로를 똑같이 반으로 나눈다","correct":true},{"t":"두 선분의 길이가 언제나 같다","mis":"M4-2-u2-X15"},{"t":"한 선분만 다른 선분을 반으로 나눈다","mis":"M4-2-u2-X15"},{"t":"서로 만나지 않는다","mis":"M4-2-u2-X05"}],"explanation":["마름모에서 마주 보는 꼭짓점끼리 선분을 그어 봐요.","두 선분은 서로 수직으로 만나요.","그리고 서로를 똑같이 반으로 나눠요(두 선분의 길이는 다를 수 있어요)."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,60.0],"ㄴ":[75.0,30.0],"ㄷ":[135.0,60.0],"ㄹ":[75.0,90.0],"ㅇ":[75.0,60.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[75.0,60.0],"ㄴ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_basic#4','math',4,2,'u2','L07','g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',1,'sa','auto','마름모에서 한 각의 크기가 110°일 때, 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u2-C8","difficulty":1,"kind":"sa","stem":"마름모에서 한 각의 크기가 110°일 때, 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["마름모도 마주 보는 두 쌍의 변이 평행해요 — 평행사변형이에요.","그래서 이웃한 두 각의 크기의 합이 180°예요.","180° − 110° = 70°예요."],"variant_rule":{"alt":[{"stem":"마름모에서 한 각의 크기가 65°일 때, 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["115"],"explanation":["마름모도 마주 보는 두 쌍의 변이 평행해요 — 평행사변형이에요.","그래서 이웃한 두 각의 크기의 합이 180°예요.","180° − 65° = 115°예요."],"asset":null},{"stem":"마름모에서 한 각의 크기가 130°일 때, 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["마름모도 마주 보는 두 쌍의 변이 평행해요 — 평행사변형이에요.","그래서 이웃한 두 각의 크기의 합이 180°예요.","180° − 130° = 50°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_basic#5','math',4,2,'u2','L07','g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',2,'sa','auto','마름모의 네 변의 길이의 합이 48 cm일 때 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u2-C8","difficulty":2,"kind":"sa","stem":"마름모의 네 변의 길이의 합이 48 cm일 때 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","네 변의 길이의 합을 4로 나눠요.","48 ÷ 4 = 12 cm예요."],"variant_rule":{"alt":[{"stem":"마름모 모양 안내판 테두리의 길이가 36 cm예요. 안내판 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","네 변의 길이의 합을 4로 나눠요.","36 ÷ 4 = 9 cm예요."],"asset":null},{"stem":"네 변의 길이의 합이 60 cm인 마름모가 있어요. 이 마름모의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","네 변의 길이의 합을 4로 나눠요.","60 ÷ 4 = 15 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_basic#6','math',4,2,'u2','L07','g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',2,'sa','auto','마름모 ㄱㄴㄷㄹ에서 선분 ㄱㄷ의 길이는 16 cm예요. 선분 ㄱㅇ의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u2-C8","difficulty":2,"kind":"sa","stem":"마름모 ㄱㄴㄷㄹ에서 선분 ㄱㄷ의 길이는 16 cm예요. 선분 ㄱㅇ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["마름모에서 마주 보는 꼭짓점끼리 이은 두 선분은 서로를 반으로 나눠요.","점 ㅇ은 선분 ㄱㄷ의 가운데예요.","16 ÷ 2 = 8 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[60.0,7.5],"ㄴ":[105.0,45.0],"ㄷ":[60.0,82.5],"ㄹ":[15.0,45.0],"ㅇ":[60.0,45.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[60.0,45.0],"ㄴ"]],"lab":[[[72.75,34.5],"16 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"마름모 ㄱㄴㄷㄹ에서 선분 ㄱㄷ의 길이는 10 cm예요. 선분 ㄱㅇ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["마름모에서 마주 보는 꼭짓점끼리 이은 두 선분은 서로를 반으로 나눠요.","점 ㅇ은 선분 ㄱㄷ의 가운데예요.","10 ÷ 2 = 5 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[135.0,15.0],"ㄹ":[60.0,15.0],"ㅇ":[75.0,45.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[75.0,45.0],"ㄴ"]],"lab":[[[63.901973342624466,64.80394668524892],"10 cm"]]}],"tag":false}},{"stem":"마름모 ㄱㄴㄷㄹ에서 선분 ㄱㄷ의 길이는 22 cm예요. 선분 ㄱㅇ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["마름모에서 마주 보는 꼭짓점끼리 이은 두 선분은 서로를 반으로 나눠요.","점 ㅇ은 선분 ㄱㄷ의 가운데예요.","22 ÷ 2 = 11 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,60.0],"ㄴ":[75.0,30.0],"ㄷ":[135.0,60.0],"ㄹ":[75.0,90.0],"ㅇ":[75.0,60.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[75.0,60.0],"ㄴ"]],"lab":[[[58.199999999999996,47.25],"22 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.conce