INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_basic#7','math',4,2,'u2','L07','g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',2,'mc','auto','모눈 위에 그린 사각형 가운데 마름모를 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X17','M4-2-u2-X14','M4-2-u2-X18']::text[],true,'{"seq":7,"concept":"M4-2-u2-C8","difficulty":2,"kind":"mc","stem":"모눈 위에 그린 사각형 가운데 마름모를 모두 고른 것은 어느 것인가요?","options":[{"t":"㉮, ㉰","correct":true},{"t":"㉮","mis":"M4-2-u2-X17"},{"t":"㉮, ㉰, ㉱","mis":"M4-2-u2-X14"},{"t":"㉯, ㉱","mis":"M4-2-u2-X18"}],"explanation":["모눈 칸을 세어 네 변의 길이가 모두 같은지 봐요(비스듬한 변은 가로·세로 칸 수가 같으면 길이가 같아요).","네 변이 모두 같은 것: ㉮, ㉰.","세워 놓인 모양만 보지 말고, 정사각형도 네 변이 같으니 마름모예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[60.0,7.5],[105.0,45.0],[60.0,82.5],[15.0,45.0]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[90.0,75.0],[120.0,15.0],[45.0,15.0]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[30.0,15.0],[90.0,15.0],[90.0,75.0],[30.0,75.0]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[60.0,7.5],[90.0,37.5],[60.0,90.0],[30.0,37.5]]]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 모눈 위에 그린 사각형 가운데 마름모를 모두 고른 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉯, ㉰","mis":"M4-2-u2-X14"},{"t":"㉮, ㉰, ㉱","mis":"M4-2-u2-X18"},{"t":"㉮, ㉯, ㉰, ㉱","mis":"M4-2-u2-X14"}],"explanation":["모눈 칸을 세어 네 변의 길이가 모두 같은지 봐요(비스듬한 변은 가로·세로 칸 수가 같으면 길이가 같아요).","네 변이 모두 같은 것: ㉯.","세워 놓인 모양만 보지 말고, 정사각형도 네 변이 같으니 마름모예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[120.0,75.0],[90.0,15.0],[45.0,15.0]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[90.0,75.0],[135.0,15.0],[60.0,15.0]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[60.0,7.5],[90.0,37.5],[60.0,90.0],[30.0,37.5]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,15.0],[120.0,15.0],[120.0,75.0],[15.0,75.0]]]}]}},{"stem":"이번에는 다른 그림이에요. 모눈 위에 그린 사각형 가운데 마름모를 모두 고른 것은 어느 것인가요?","options":[{"t":"㉮, ㉰","correct":true},{"t":"㉰","mis":"M4-2-u2-X17"},{"t":"㉮, ㉯, ㉰","mis":"M4-2-u2-X14"},{"t":"㉯, ㉱","mis":"M4-2-u2-X18"}],"explanation":["모눈 칸을 세어 네 변의 길이가 모두 같은지 봐요(비스듬한 변은 가로·세로 칸 수가 같으면 길이가 같아요).","네 변이 모두 같은 것: ㉮, ㉰.","세워 놓인 모양만 보지 말고, 정사각형도 네 변이 같으니 마름모예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[60.0,7.5],[97.5,45.0],[60.0,82.5],[22.5,45.0]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[60.0,7.5],[90.0,37.5],[60.0,90.0],[30.0,37.5]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,60.0],[75.0,30.0],[135.0,60.0],[75.0,90.0]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,60.0],[75.0,30.0],[105.0,60.0],[45.0,90.0]]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_basic#8','math',4,2,'u2','L07','g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',2,'mc','auto','모든 마름모가 가진 성질이 아닌 것은 어느 것인가요?',ARRAY['M4-2-u2-X18']::text[],true,'{"seq":8,"concept":"M4-2-u2-C8","difficulty":2,"kind":"mc","stem":"모든 마름모가 가진 성질이 아닌 것은 어느 것인가요?","options":[{"t":"네 각이 모두 직각이다","correct":true},{"t":"네 변의 길이가 모두 같다","mis":"M4-2-u2-X18"},{"t":"마주 보는 두 각의 크기가 같다","mis":"M4-2-u2-X18"},{"t":"마주 보는 두 쌍의 변이 서로 평행하다","mis":"M4-2-u2-X18"}],"explanation":["마름모: 네 변이 같음 · 마주 보는 두 쌍의 변이 평행 · 마주 보는 각이 같음 · 두 대각선(마주 보는 꼭짓점을 이은 선분)은 수직으로 만나 서로를 반으로.","「네 각이 모두 직각이다」는 마름모에 늘 맞는 말이 아니에요.","정사각형인 마름모에서만 네 각이 직각이고 두 선분의 길이가 같아요."],"variant_rule":{"alt":[{"stem":"모든 마름모가 가진 성질이 아닌 것은 어느 것인가요?","options":[{"t":"마주 보는 꼭짓점끼리 이은 두 선분의 길이가 같다","correct":true},{"t":"마주 보는 꼭짓점끼리 이은 두 선분이 서로 수직이다","mis":"M4-2-u2-X18"},{"t":"네 변의 길이가 모두 같다","mis":"M4-2-u2-X18"},{"t":"이웃한 두 각의 크기의 합이 180°이다","mis":"M4-2-u2-X18"}],"explanation":["마름모: 네 변이 같음 · 마주 보는 두 쌍의 변이 평행 · 마주 보는 각이 같음 · 두 대각선(마주 보는 꼭짓점을 이은 선분)은 수직으로 만나 서로를 반으로.","「마주 보는 꼭짓점끼리 이은 두 선분의 길이가 같다」는 마름모에 늘 맞는 말이 아니에요.","정사각형인 마름모에서만 네 각이 직각이고 두 선분의 길이가 같아요."],"asset":null},{"stem":"모든 마름모가 가진 성질이 아닌 것은 어느 것인가요?","options":[{"t":"평행한 변이 한 쌍만 있다","correct":true},{"t":"마주 보는 두 쌍의 변이 서로 평행하다","mis":"M4-2-u2-X18"},{"t":"마주 보는 두 각의 크기가 같다","mis":"M4-2-u2-X18"},{"t":"마주 보는 꼭짓점끼리 이은 두 선분이 서로를 반으로 나눈다","mis":"M4-2-u2-X18"}],"explanation":["마름모: 네 변이 같음 · 마주 보는 두 쌍의 변이 평행 · 마주 보는 각이 같음 · 두 대각선(마주 보는 꼭짓점을 이은 선분)은 수직으로 만나 서로를 반으로.","「평행한 변이 한 쌍만 있다」는 마름모에 늘 맞는 말이 아니에요.","정사각형인 마름모에서만 네 각이 직각이고 두 선분의 길이가 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_basic#9','math',4,2,'u2','L07','g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',2,'sa','auto','마름모 ㄱㄴㄷㄹ에서 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u2-C8","difficulty":2,"kind":"sa","stem":"마름모 ㄱㄴㄷㄹ에서 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["㉠은 55°인 각과 마주 보는 각이에요.","마름모는 마주 보는 각의 크기가 같고, 이웃한 두 각의 합은 180°예요.","㉠ = 55°예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[135.0,15.0],"ㄹ":[60.0,15.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[33.599999999999994,65.7],"55°"],[[116.39999999999999,24.299999999999997],"㉠"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"마름모 ㅁㅂㅅㅇ에서 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["㉠은 80°인 각과 이웃한 각이에요.","마름모는 마주 보는 각의 크기가 같고, 이웃한 두 각의 합은 180°예요.","㉠ = 180° − 80° = 100°예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[60.0,7.5],"ㅂ":[105.0,45.0],"ㅅ":[60.0,82.5],"ㅇ":[15.0,45.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"lab":[[[90.0,45.0],"80°"],[[60.0,67.5],"㉠"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 마름모 ㄱㄴㄷㄹ에서 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["㉠은 125°인 각과 이웃한 각이에요.","마름모는 마주 보는 각의 크기가 같고, 이웃한 두 각의 합은 180°예요.","㉠ = 180° − 125° = 55°예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,60.0],"ㄴ":[75.0,30.0],"ㄷ":[135.0,60.0],"ㄹ":[75.0,90.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[75.0,45.0],"125°"],[[35.79543219074804,60.0],"㉠"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_basic#10','math',4,2,'u2','L07','g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',3,'ox','auto','정사각형은 마름모라고 할 수 있어요.',ARRAY['M4-2-u2-X17']::text[],true,'{"seq":10,"concept":"M4-2-u2-C8","difficulty":3,"kind":"ox","stem":"정사각형은 마름모라고 할 수 있어요.","answer":"O","reason_options":[{"t":"정사각형도 네 변의 길이가 모두 같아서","correct":true},{"t":"마름모는 비스듬히 세워 놓인 모양이라서","mis":"M4-2-u2-X17"}],"mis":"M4-2-u2-X17","explanation":["마름모는 네 변의 길이가 모두 같은 사각형이에요.","정사각형은 네 변이 같으니 마름모이고, 마름모는 두 쌍의 변이 평행하니 평행사변형이에요.","하지만 마름모가 모두 정사각형인 것은 아니에요(네 각이 직각이어야 정사각형)."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[30.0,15.0],[90.0,15.0],[90.0,75.0],[30.0,75.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"마름모는 모두 정사각형이에요.","answer":"X","reason_options":[{"t":"마름모는 네 각이 직각이 아닐 수도 있어서","correct":true},{"t":"네 변의 길이가 같으면 정사각형이라서","mis":"M4-2-u2-X16"}],"explanation":["마름모는 네 변의 길이가 모두 같은 사각형이에요.","정사각형은 네 변이 같으니 마름모이고, 마름모는 두 쌍의 변이 평행하니 평행사변형이에요.","하지만 마름모가 모두 정사각형인 것은 아니에요(네 각이 직각이어야 정사각형)."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[90.0,75.0],[135.0,15.0],[60.0,15.0]]]}],"tag":false}},{"stem":"마름모는 평행사변형이라고 할 수 있어요.","answer":"O","reason_options":[{"t":"마름모도 마주 보는 두 쌍의 변이 서로 평행해서","correct":true},{"t":"마름모는 기울어진 모양이 달라서","mis":"M4-2-u2-X17"}],"explanation":["마름모는 네 변의 길이가 모두 같은 사각형이에요.","정사각형은 네 변이 같으니 마름모이고, 마름모는 두 쌍의 변이 평행하니 평행사변형이에요.","하지만 마름모가 모두 정사각형인 것은 아니에요(네 각이 직각이어야 정사각형)."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[60.0,7.5],[105.0,45.0],[60.0,82.5],[15.0,45.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_challenge#1','math',4,2,'u2','L07','g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',2,'mc','auto','모눈 위에 그린 사각형 가운데 마름모를 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X17','M4-2-u2-X14','M4-2-u2-X18']::text[],true,'{"seq":1,"concept":"M4-2-u2-C8","difficulty":2,"kind":"mc","stem":"모눈 위에 그린 사각형 가운데 마름모를 모두 고른 것은 어느 것인가요?","options":[{"t":"㉯, ㉱","correct":true},{"t":"㉯","mis":"M4-2-u2-X17"},{"t":"㉮, ㉯, ㉱","mis":"M4-2-u2-X14"},{"t":"㉮, ㉰","mis":"M4-2-u2-X18"}],"explanation":["모눈 칸을 세어 네 변의 길이가 모두 같은지 봐요(비스듬한 변은 가로·세로 칸 수가 같으면 길이가 같아요).","네 변이 모두 같은 것: ㉯, ㉱.","세워 놓인 모양만 보지 말고, 정사각형도 네 변이 같으니 마름모예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[60.0,7.5],[90.0,37.5],[60.0,90.0],[30.0,37.5]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[60.0,7.5],[105.0,45.0],[60.0,82.5],[15.0,45.0]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,45.0],[75.0,15.0],[90.0,45.0],[30.0,75.0]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[45.0,7.5],[90.0,37.5],[60.0,82.5],[15.0,52.5]]]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 모눈 위에 그린 사각형 가운데 마름모를 모두 고른 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉯, ㉰","mis":"M4-2-u2-X14"},{"t":"㉮, ㉰, ㉱","mis":"M4-2-u2-X18"},{"t":"㉮, ㉯, ㉰, ㉱","mis":"M4-2-u2-X14"}],"explanation":["모눈 칸을 세어 네 변의 길이가 모두 같은지 봐요(비스듬한 변은 가로·세로 칸 수가 같으면 길이가 같아요).","네 변이 모두 같은 것: ㉯.","세워 놓인 모양만 보지 말고, 정사각형도 네 변이 같으니 마름모예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[120.0,75.0],[90.0,15.0],[45.0,15.0]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[90.0,75.0],[135.0,15.0],[60.0,15.0]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[60.0,7.5],[90.0,37.5],[60.0,90.0],[30.0,37.5]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,15.0],[120.0,15.0],[120.0,75.0],[15.0,75.0]]]}]}},{"stem":"이번에는 다른 그림이에요. 모눈 위에 그린 사각형 가운데 마름모를 모두 고른 것은 어느 것인가요?","options":[{"t":"㉮, ㉰","correct":true},{"t":"㉮","mis":"M4-2-u2-X17"},{"t":"㉮, ㉰, ㉱","mis":"M4-2-u2-X14"},{"t":"㉯, ㉱","mis":"M4-2-u2-X18"}],"explanation":["모눈 칸을 세어 네 변의 길이가 모두 같은지 봐요(비스듬한 변은 가로·세로 칸 수가 같으면 길이가 같아요).","네 변이 모두 같은 것: ㉮, ㉰.","세워 놓인 모양만 보지 말고, 정사각형도 네 변이 같으니 마름모예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[60.0,7.5],[105.0,45.0],[60.0,82.5],[15.0,45.0]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[90.0,75.0],[120.0,15.0],[45.0,15.0]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[30.0,15.0],[90.0,15.0],[90.0,75.0],[30.0,75.0]]]},{"w":142.5,"h":97.5,"grid":15,"poly":[[[60.0,7.5],[90.0,37.5],[60.0,90.0],[30.0,37.5]]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_challenge#2','math',4,2,'u2','L07','g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',2,'mc','auto','평행사변형과 마름모의 같은 점으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u2-X14','M4-2-u2-X11','M4-2-u2-X09']::text[],true,'{"seq":2,"concept":"M4-2-u2-C8","difficulty":2,"kind":"mc","stem":"평행사변형과 마름모의 같은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"마주 보는 두 쌍의 변이 서로 평행하다","correct":true},{"t":"네 변의 길이가 모두 같다","mis":"M4-2-u2-X14"},{"t":"네 각이 모두 직각이다","mis":"M4-2-u2-X11"},{"t":"평행한 변이 한 쌍만 있다","mis":"M4-2-u2-X09"}],"explanation":["평행사변형: 마주 보는 두 쌍의 변이 평행한 사각형.","마름모도 두 쌍의 변이 평행해요 — 평행사변형이에요.","마름모는 여기에 네 변의 길이까지 모두 같아요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[90.0,75.0],[120.0,15.0],[45.0,15.0]]],"cap":"평행사변형"},{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[90.0,75.0],[135.0,15.0],[60.0,15.0]]],"cap":"마름모"}],"tag":false},"variant_rule":{"alt":[{"stem":"평행사변형과 마름모의 다른 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"마름모는 네 변의 길이가 모두 같지만 평행사변형은 아닐 수도 있다","correct":true},{"t":"평행사변형만 마주 보는 각이 같다","mis":"M4-2-u2-X12"},{"t":"마름모는 평행한 변이 없다","mis":"M4-2-u2-X06"},{"t":"평행사변형은 이웃한 두 각의 합이 180°가 아니다","mis":"M4-2-u2-X12"}],"explanation":["평행사변형: 마주 보는 두 쌍의 변이 평행한 사각형.","마름모도 두 쌍의 변이 평행해요 — 평행사변형이에요.","마름모는 여기에 네 변의 길이까지 모두 같아요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[90.0,75.0],[120.0,15.0],[45.0,15.0]]],"cap":"평행사변형"},{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[90.0,75.0],[135.0,15.0],[60.0,15.0]]],"cap":"마름모"}],"tag":false}},{"stem":"마름모를 평행사변형이라고 할 수 있는 까닭은 무엇인가요?","options":[{"t":"마름모도 마주 보는 두 쌍의 변이 서로 평행해서","correct":true},{"t":"마름모는 네 각이 모두 직각이라서","mis":"M4-2-u2-X14"},{"t":"마름모는 기울어진 모양이라서","mis":"M4-2-u2-X10"},{"t":"마름모는 평행한 변이 한 쌍만 있어서","mis":"M4-2-u2-X09"}],"explanation":["평행사변형: 마주 보는 두 쌍의 변이 평행한 사각형.","마름모도 두 쌍의 변이 평행해요 — 평행사변형이에요.","마름모는 여기에 네 변의 길이까지 모두 같아요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[90.0,75.0],[120.0,15.0],[45.0,15.0]]],"cap":"평행사변형"},{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[90.0,75.0],[135.0,15.0],[60.0,15.0]]],"cap":"마름모"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_challenge#3','math',4,2,'u2','L07','g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',3,'mc','auto','색종이를 반으로 두 번 접은 뒤 비스듬히 한 번 잘라 펼쳤더니 마름모가 되었어요. 늘 마름모가 되는 까닭은 무엇인가요?',ARRAY['M4-2-u2-X14','M4-2-u2-X18']::text[],true,'{"seq":3,"concept":"M4-2-u2-C8","difficulty":3,"kind":"mc","stem":"색종이를 반으로 두 번 접은 뒤 비스듬히 한 번 잘라 펼쳤더니 마름모가 되었어요. 늘 마름모가 되는 까닭은 무엇인가요?","options":[{"t":"접은 자리가 겹쳐 네 변이 모두 같은 자리에서 잘린 변이라서","correct":true},{"t":"색종이가 정사각형이라서","mis":"M4-2-u2-X14"},{"t":"가위가 곧아서","mis":"M4-2-u2-X18"},{"t":"두 번 접어서 네 각이 직각이 되어서","mis":"M4-2-u2-X14"}],"explanation":["반으로 두 번 접으면 네 겹이 한 자리에 겹쳐요.","한 번 자른 자리가 펼치면 네 변이 되니 네 변의 길이가 같아요 — 마름모.","접은 두 선이 마주 보는 꼭짓점을 잇는 선분이 되어 수직으로 만나고 서로를 반으로 나눠요."],"variant_rule":{"alt":[{"stem":"색종이를 반으로 두 번 접고 비스듬히 잘라 펼친 마름모에서, 접었던 두 선은 서로 어떻게 만나나요?","options":[{"t":"서로 수직으로 만난다","correct":true},{"t":"서로 평행하다","mis":"M4-2-u2-X02"},{"t":"비스듬히 만난다","mis":"M4-2-u2-X15"},{"t":"만나지 않는다","mis":"M4-2-u2-X05"}],"explanation":["반으로 두 번 접으면 네 겹이 한 자리에 겹쳐요.","한 번 자른 자리가 펼치면 네 변이 되니 네 변의 길이가 같아요 — 마름모.","접은 두 선이 마주 보는 꼭짓점을 잇는 선분이 되어 수직으로 만나고 서로를 반으로 나눠요."],"asset":null},{"stem":"색종이를 반으로 두 번 접고 비스듬히 잘라 펼친 마름모에서, 접었던 선은 마주 보는 꼭짓점끼리 이은 선분이에요. 이 두 선분에 대해 바른 것은 어느 것인가요?","options":[{"t":"서로를 똑같이 반으로 나눈다","correct":true},{"t":"길이가 언제나 같다","mis":"M4-2-u2-X15"},{"t":"한 선분이 다른 선분보다 언제나 두 배 길다","mis":"M4-2-u2-X15"},{"t":"서로 평행하다","mis":"M4-2-u2-X02"}],"explanation":["반으로 두 번 접으면 네 겹이 한 자리에 겹쳐요.","한 번 자른 자리가 펼치면 네 변이 되니 네 변의 길이가 같아요 — 마름모.","접은 두 선이 마주 보는 꼭짓점을 잇는 선분이 되어 수직으로 만나고 서로를 반으로 나눠요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_challenge#4','math',4,2,'u2','L07','g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',3,'error','auto','마름모에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u2-X15','M4-2-u2-X18']::text[],true,'{"seq":4,"concept":"M4-2-u2-C8","difficulty":3,"kind":"error","stem":"마름모에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「마주 보는 꼭짓점끼리 이은 두 선분은 길이가 같아.」","correct":true,"mis_target":"M4-2-u2-X15"},{"t":"민서 — 「네 변의 길이가 모두 같아.」","mis":"M4-2-u2-X18"},{"t":"도윤 — 「마주 보는 두 쌍의 변이 서로 평행해.」","mis":"M4-2-u2-X18"},{"t":"서윤 — 「마주 보는 꼭짓점끼리 이은 두 선분은 수직으로 만나.」","mis":"M4-2-u2-X18"}],"explanation":["마름모는 네 변이 같고 마주 보는 두 쌍의 변이 평행하며 마주 보는 각이 같아요.","두 대각선은 수직으로 만나 서로를 반으로 나누지만 길이는 다를 수 있어요.","준서의 말이 잘못되었어요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[135.0,15.0],"ㄹ":[60.0,15.0],"ㅇ":[75.0,45.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[75.0,45.0],"ㄴ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 마름모에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「네 각이 모두 직각이어야 마름모야.」","correct":true,"mis_target":"M4-2-u2-X14"},{"t":"도윤 — 「네 변의 길이가 모두 같아.」","mis":"M4-2-u2-X18"},{"t":"서윤 — 「마주 보는 두 쌍의 변이 서로 평행해.」","mis":"M4-2-u2-X18"},{"t":"시우 — 「마주 보는 꼭짓점끼리 이은 두 선분은 수직으로 만나.」","mis":"M4-2-u2-X18"}],"explanation":["마름모는 네 변이 같고 마주 보는 두 쌍의 변이 평행하며 마주 보는 각이 같아요.","두 대각선은 수직으로 만나 서로를 반으로 나누지만 길이는 다를 수 있어요.","민서의 말이 잘못되었어요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[135.0,15.0],"ㄹ":[60.0,15.0],"ㅇ":[75.0,45.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[75.0,45.0],"ㄴ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 마름모에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「마주 보는 두 각은 크기가 달라.」","correct":true,"mis_target":"M4-2-u2-X12"},{"t":"서윤 — 「네 변의 길이가 모두 같아.」","mis":"M4-2-u2-X18"},{"t":"시우 — 「마주 보는 두 쌍의 변이 서로 평행해.」","mis":"M4-2-u2-X18"},{"t":"은우 — 「마주 보는 꼭짓점끼리 이은 두 선분은 수직으로 만나.」","mis":"M4-2-u2-X18"}],"explanation":["마름모는 네 변이 같고 마주 보는 두 쌍의 변이 평행하며 마주 보는 각이 같아요.","두 대각선은 수직으로 만나 서로를 반으로 나누지만 길이는 다를 수 있어요.","도윤의 말이 잘못되었어요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[135.0,15.0],"ㄹ":[60.0,15.0],"ㅇ":[75.0,45.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[75.0,45.0],"ㄴ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_challenge#5','math',4,2,'u2','L07','g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',3,'sa','auto','마름모 ㄱㄴㄷㄹ에서 마주 보는 꼭짓점끼리 이은 두 선분의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u2-C8","difficulty":3,"kind":"sa","stem":"마름모 ㄱㄴㄷㄹ에서 마주 보는 꼭짓점끼리 이은 두 선분의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["두 선분은 점 ㅇ에서 서로를 반으로 나눠요.","선분 ㄱㄷ = 4 × 2 = 8 cm, 선분 ㄴㄹ = 5 × 2 = 10 cm.","8 + 10 = 18 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[60.0,7.5],"ㄴ":[105.0,45.0],"ㄷ":[60.0,82.5],"ㄹ":[15.0,45.0],"ㅇ":[60.0,45.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[60.0,45.0],"ㄴ"]],"lab":[[[70.0,18.25],"4 cm"],[[92.5,37.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 마름모 ㄱㄴㄷㄹ에서 마주 보는 꼭짓점끼리 이은 두 선분의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["두 선분은 점 ㅇ에서 서로를 반으로 나눠요.","선분 ㄱㄷ = 9 × 2 = 18 cm, 선분 ㄴㄹ = 4 × 2 = 8 cm.","18 + 8 = 26 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[135.0,15.0],"ㄹ":[60.0,15.0],"ㅇ":[75.0,45.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[75.0,45.0],"ㄴ"]],"lab":[[[55.0,52.0],"9 cm"],[[92.5,52.0],"4 cm"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 마름모 ㄱㄴㄷㄹ에서 마주 보는 꼭짓점끼리 이은 두 선분의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["두 선분은 점 ㅇ에서 서로를 반으로 나눠요.","선분 ㄱㄷ = 6 × 2 = 12 cm, 선분 ㄴㄹ = 3 × 2 = 6 cm.","12 + 6 = 18 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,60.0],"ㄴ":[75.0,30.0],"ㄷ":[135.0,60.0],"ㄹ":[75.0,90.0],"ㅇ":[75.0,60.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[75.0,60.0],"ㄴ"]],"lab":[[[55.0,52.0],"6 cm"],[[85.0,37.0],"3 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_challenge#6','math',4,2,'u2','L07','g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',3,'ox','auto','마름모는 모두 정사각형이에요.',ARRAY['M4-2-u2-X16']::text[],true,'{"seq":6,"concept":"M4-2-u2-C8","difficulty":3,"kind":"ox","stem":"마름모는 모두 정사각형이에요.","answer":"X","reason_options":[{"t":"마름모는 네 각이 직각이 아닐 수도 있어서","correct":true},{"t":"네 변의 길이가 같으면 정사각형이라서","mis":"M4-2-u2-X16"}],"mis":"M4-2-u2-X16","explanation":["마름모는 네 변의 길이가 모두 같은 사각형이에요.","정사각형은 네 변이 같으니 마름모이고, 마름모는 두 쌍의 변이 평행하니 평행사변형이에요.","하지만 마름모가 모두 정사각형인 것은 아니에요(네 각이 직각이어야 정사각형)."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[90.0,75.0],[135.0,15.0],[60.0,15.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"마름모는 평행사변형이라고 할 수 있어요.","answer":"O","reason_options":[{"t":"마름모도 마주 보는 두 쌍의 변이 서로 평행해서","correct":true},{"t":"마름모는 기울어진 모양이 달라서","mis":"M4-2-u2-X17"}],"explanation":["마름모는 네 변의 길이가 모두 같은 사각형이에요.","정사각형은 네 변이 같으니 마름모이고, 마름모는 두 쌍의 변이 평행하니 평행사변형이에요.","하지만 마름모가 모두 정사각형인 것은 아니에요(네 각이 직각이어야 정사각형)."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[60.0,7.5],[105.0,45.0],[60.0,82.5],[15.0,45.0]]]}],"tag":false}},{"stem":"정사각형은 마름모라고 할 수 있어요.","answer":"O","reason_options":[{"t":"정사각형도 네 변의 길이가 모두 같아서","correct":true},{"t":"마름모는 비스듬히 세워 놓인 모양이라서","mis":"M4-2-u2-X17"}],"explanation":["마름모는 네 변의 길이가 모두 같은 사각형이에요.","정사각형은 네 변이 같으니 마름모이고, 마름모는 두 쌍의 변이 평행하니 평행사변형이에요.","하지만 마름모가 모두 정사각형인 것은 아니에요(네 각이 직각이어야 정사각형)."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[30.0,15.0],[90.0,15.0],[90.0,75.0],[30.0,75.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_challenge#7','math',4,2,'u2','L07','g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',3,'sa','auto','마름모 ㅁㅂㅅㅇ에서 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u2-C8","difficulty":3,"kind":"sa","stem":"마름모 ㅁㅂㅅㅇ에서 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["㉠은 80°인 각과 이웃한 각이에요.","마름모는 마주 보는 각의 크기가 같고, 이웃한 두 각의 합은 180°예요.","㉠ = 180° − 80° = 100°예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[60.0,7.5],"ㅂ":[105.0,45.0],"ㅅ":[60.0,82.5],"ㅇ":[15.0,45.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"lab":[[[90.0,45.0],"80°"],[[60.0,67.5],"㉠"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"마름모 ㄱㄴㄷㄹ에서 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["㉠은 125°인 각과 이웃한 각이에요.","마름모는 마주 보는 각의 크기가 같고, 이웃한 두 각의 합은 180°예요.","㉠ = 180° − 125° = 55°예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,60.0],"ㄴ":[75.0,30.0],"ㄷ":[135.0,60.0],"ㄹ":[75.0,90.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[75.0,45.0],"125°"],[[35.79543219074804,60.0],"㉠"]]}],"tag":false}},{"stem":"마름모 ㄱㄴㄷㄹ에서 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["㉠은 55°인 각과 마주 보는 각이에요.","마름모는 마주 보는 각의 크기가 같고, 이웃한 두 각의 합은 180°예요.","㉠ = 55°예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[135.0,15.0],"ㄹ":[60.0,15.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[33.599999999999994,65.7],"55°"],[[116.39999999999999,24.299999999999997],"㉠"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_challenge#8','math',4,2,'u2','L07','g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',4,'sa','auto','마름모 ㄱㄴㄷㄹ에 마주 보는 꼭짓점끼리 선분을 그었어요. 삼각형 ㄱㅇㄴ에서 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u2-C8","difficulty":4,"kind":"sa","stem":"마름모 ㄱㄴㄷㄹ에 마주 보는 꼭짓점끼리 선분을 그었어요. 삼각형 ㄱㅇㄴ에서 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["두 선분은 점 ㅇ에서 수직으로 만나요 — 각 ㄱㅇㄴ = 90°.","삼각형의 세 각의 합은 180°예요.","㉠ = 180° − 90° − 25° = 65°예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[135.0,15.0],"ㄹ":[60.0,15.0],"ㅇ":[75.0,45.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[75.0,45.0],"ㄴ"]],"lab":[[[44.19746968403191,68.10741238357916],"25°"],[[74.95228390462597,65.7],"㉠"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 마름모 ㄱㄴㄷㄹ에 마주 보는 꼭짓점끼리 선분을 그었어요. 삼각형 ㄱㅇㄴ에서 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["두 선분은 점 ㅇ에서 수직으로 만나요 — 각 ㄱㅇㄴ = 90°.","삼각형의 세 각의 합은 180°예요.","㉠ = 180° − 90° − 50° = 40°예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[60.0,7.5],"ㄴ":[105.0,45.0],"ㄷ":[60.0,82.5],"ㄹ":[15.0,45.0],"ㅇ":[60.0,45.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[60.0,45.0],"ㄴ"]],"lab":[[[69.3,27.355886997655315],"50°"],[[79.31293560281362,35.699999999999996],"㉠"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 마름모 ㄱㄴㄷㄹ에 마주 보는 꼭짓점끼리 선분을 그었어요. 삼각형 ㄱㅇㄴ에서 ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["두 선분은 점 ㅇ에서 수직으로 만나요 — 각 ㄱㅇㄴ = 90°.","삼각형의 세 각의 합은 180°예요.","㉠ = 180° − 90° − 65° = 25°예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,60.0],"ㄴ":[75.0,30.0],"ㄷ":[135.0,60.0],"ㄹ":[75.0,90.0],"ㅇ":[75.0,60.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[75.0,60.0],"ㄴ"]],"lab":[[[65.7,45.04771609537403],"65°"],[[44.19746968403191,53.10741238357917],"㉠"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_challenge#9','math',4,2,'u2','L07','g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',4,'sa','auto','네 변의 길이의 합이 같은 평행사변형과 마름모가 있어요. 평행사변형의 두 변이 7 cm와 5 cm일 때, 마름모의 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u2-C8","difficulty":4,"kind":"sa","stem":"네 변의 길이의 합이 같은 평행사변형과 마름모가 있어요. 평행사변형의 두 변이 7 cm와 5 cm일 때, 마름모의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["평행사변형의 네 변의 길이의 합은 (7 + 5) × 2 = 24 cm예요.","마름모도 네 변의 합이 24 cm이고 네 변이 모두 같아요.","24 ÷ 4 = 6 cm예요."],"variant_rule":{"alt":[{"stem":"네 변의 길이의 합이 같은 평행사변형과 마름모가 있어요. 평행사변형의 두 변이 9 cm와 3 cm일 때, 마름모의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["평행사변형의 네 변의 길이의 합은 (9 + 3) × 2 = 24 cm예요.","마름모도 네 변의 합이 24 cm이고 네 변이 모두 같아요.","24 ÷ 4 = 6 cm예요."],"asset":null},{"stem":"네 변의 길이의 합이 같은 평행사변형과 마름모가 있어요. 평행사변형의 두 변이 8 cm와 6 cm일 때, 마름모의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["평행사변형의 네 변의 길이의 합은 (8 + 6) × 2 = 28 cm예요.","마름모도 네 변의 합이 28 cm이고 네 변이 모두 같아요.","28 ÷ 4 = 7 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L07_challenge#10','math',4,2,'u2','L07','g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',4,'essay','teacher','마름모와 평행사변형의 같은 점과 다른 점을 한 가지씩 쓰고, 마름모를 평행사변형이라고 할 수 있는지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u2-C8","difficulty":4,"kind":"essay","stem":"마름모와 평행사변형의 같은 점과 다른 점을 한 가지씩 쓰고, 마름모를 평행사변형이라고 할 수 있는지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 같은 점 — 마주 보는 두 쌍의 변이 서로 평행하고 마주 보는 각의 크기가 같다. 다른 점 — 마름모는 네 변의 길이가 모두 같지만 평행사변형은 이웃한 두 변의 길이가 다를 수 있다. 마름모도 마주 보는 두 쌍의 변이 평행하므로 평행사변형이라고 할 수 있다.","scoring_points":["같은 점을 바르게 썼는가","다른 점(네 변의 길이)을 바르게 썼는가","두 쌍의 변이 평행하다는 까닭으로 마름모가 평행사변형임을 썼는가"]},"explanation":["같은 점: 두 쌍의 변이 평행, 마주 보는 각이 같음.","다른 점: 마름모는 네 변이 모두 같아요.","마름모도 두 쌍의 변이 평행하니 평행사변형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L08_basic#1','math',4,2,'u2','L08','g4_2_math_u2_L08_basic','lesson_basic','M4-2-u2-C9',1,'sa','auto','직사각형의 한 각의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u2-C9","difficulty":1,"kind":"sa","stem":"직사각형의 한 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["직사각형과 정사각형은 네 각이 모두 직각이에요.","직각은 90°예요.","직사각형은 네 각이 모두 직각 — 90°예요."],"variant_rule":{"alt":[{"stem":"정사각형에서 이웃한 두 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["직사각형과 정사각형은 네 각이 모두 직각이에요.","직각은 90°예요.","정사각형의 네 각은 모두 90° — 90° + 90° = 180°예요."],"asset":null},{"stem":"직사각형의 네 각의 크기를 모두 더하면 몇 도인가요? 숫자로 쓰세요.","answer":["360"],"explanation":["직사각형과 정사각형은 네 각이 모두 직각이에요.","직각은 90°예요.","네 각이 모두 90° — 90° × 4 = 360°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L08_basic#2','math',4,2,'u2','L08','g4_2_math_u2_L08_basic','lesson_basic','M4-2-u2-C9',1,'mc','auto','정사각형의 성질로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u2-X14','M4-2-u2-X06','M4-2-u2-X12']::text[],true,'{"seq":2,"concept":"M4-2-u2-C9","difficulty":1,"kind":"mc","stem":"정사각형의 성질로 알맞은 것은 어느 것인가요?","options":[{"t":"네 각이 모두 직각이고 네 변의 길이가 모두 같다","correct":true},{"t":"네 변의 길이가 모두 다르다","mis":"M4-2-u2-X14"},{"t":"평행한 변이 없다","mis":"M4-2-u2-X06"},{"t":"마주 보는 두 각의 크기가 다르다","mis":"M4-2-u2-X12"}],"explanation":["직사각형: 네 각이 모두 직각, 마주 보는 두 변의 길이가 같아요.","정사각형: 네 각이 모두 직각, 네 변의 길이가 모두 같아요.","마름모는 네 변이 같지만 네 각이 직각이 아닐 수 있어요."],"variant_rule":{"alt":[{"stem":"직사각형의 성질로 알맞은 것은 어느 것인가요?","options":[{"t":"네 각이 모두 직각이고 마주 보는 두 변의 길이가 같다","correct":true},{"t":"네 변의 길이가 언제나 모두 같다","mis":"M4-2-u2-X16"},{"t":"평행한 변이 한 쌍만 있다","mis":"M4-2-u2-X09"},{"t":"이웃한 두 각의 크기의 합이 90°이다","mis":"M4-2-u2-X12"}],"explanation":["직사각형: 네 각이 모두 직각, 마주 보는 두 변의 길이가 같아요.","정사각형: 네 각이 모두 직각, 네 변의 길이가 모두 같아요.","마름모는 네 변이 같지만 네 각이 직각이 아닐 수 있어요."],"asset":null},{"stem":"직사각형과 정사각형의 같은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"네 각이 모두 직각이다","correct":true},{"t":"네 변의 길이가 모두 같다","mis":"M4-2-u2-X16"},{"t":"평행한 변이 없다","mis":"M4-2-u2-X06"},{"t":"평행한 변이 한 쌍만 있다","mis":"M4-2-u2-X09"}],"explanation":["직사각형: 네 각이 모두 직각, 마주 보는 두 변의 길이가 같아요.","정사각형: 네 각이 모두 직각, 네 변의 길이가 모두 같아요.","마름모는 네 변이 같지만 네 각이 직각이 아닐 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L08_basic#3','math',4,2,'u2','L08','g4_2_math_u2_L08_basic','lesson_basic','M4-2-u2-C9',1,'sa','auto','직사각형 ㄱㄴㄷㄹ에서 변 ㄹㄷ의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u2-C9","difficulty":1,"kind":"sa","stem":"직사각형 ㄱㄴㄷㄹ에서 변 ㄹㄷ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","변 ㄹㄷ과 마주 보는 변은 변 ㄱㄴ이에요.","그래서 8 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,15.0],"ㄴ":[120.0,15.0],"ㄷ":[120.0,75.0],"ㄹ":[15.0,75.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"right":[["ㄹ","ㄱ","ㄴ"],["ㄱ","ㄴ","ㄷ"],["ㄴ","ㄷ","ㄹ"],["ㄷ","ㄹ","ㄱ"]],"lab":[[[67.5,3.75],"8 cm"],[[139.65,45.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직사각형 ㅁㅂㅅㅇ에서 변 ㅁㅇ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","변 ㅁㅇ과 마주 보는 변은 변 ㅂㅅ이에요.","그래서 7 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[45.0,7.5],"ㅂ":[90.0,7.5],"ㅅ":[90.0,82.5],"ㅇ":[45.0,82.5]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"right":[["ㅇ","ㅁ","ㅂ"],["ㅁ","ㅂ","ㅅ"],["ㅂ","ㅅ","ㅇ"],["ㅅ","ㅇ","ㅁ"]],"lab":[[[67.5,-3.75],"4 cm"],[[109.65,45.0],"7 cm"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 직사각형 ㄱㄴㄷㄹ에서 변 ㄹㄷ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","변 ㄹㄷ과 마주 보는 변은 변 ㄱㄴ이에요.","그래서 10 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,45.0],"ㄴ":[75.0,15.0],"ㄷ":[90.0,45.0],"ㄹ":[30.0,75.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"right":[["ㄹ","ㄱ","ㄴ"],["ㄱ","ㄴ","ㄷ"],["ㄴ","ㄷ","ㄹ"],["ㄷ","ㄹ","ㄱ"]],"lab":[[[37.868847050625476,15.737694101250948],"10 cm"],[[99.28230589874906,21.60884705062547],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L08_basic#4','math',4,2,'u2','L08','g4_2_math_u2_L08_basic','lesson_basic','M4-2-u2-C9',1,'sa','auto','정사각형의 네 변의 길이의 합이 24 cm일 때 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u2-C9","difficulty":1,"kind":"sa","stem":"정사각형의 네 변의 길이의 합이 24 cm일 때 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["정사각형은 네 변의 길이가 모두 같아요.","네 변의 길이의 합을 4로 나눠요.","24 ÷ 4 = 6 cm예요."],"variant_rule":{"alt":[{"stem":"정사각형 보도블록 한 장의 테두리 길이가 36 cm예요. 보도블록 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["정사각형은 네 변의 길이가 모두 같아요.","네 변의 길이의 합을 4로 나눠요.","36 ÷ 4 = 9 cm예요."],"asset":null},{"stem":"정사각형의 네 변의 길이의 합이 44 cm일 때 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["정사각형은 네 변의 길이가 모두 같아요.","네 변의 길이의 합을 4로 나눠요.","44 ÷ 4 = 11 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
