INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L08_basic#7','math',4,2,'u2','L08','g4_2_math_u2_L08_basic','lesson_basic','M4-2-u2-C9',2,'ox','auto','직사각형은 평행사변형이라고 할 수 있어요.',ARRAY['M4-2-u2-X11']::text[],true,'{"seq":7,"concept":"M4-2-u2-C9","difficulty":2,"kind":"ox","stem":"직사각형은 평행사변형이라고 할 수 있어요.","answer":"O","reason_options":[{"t":"직사각형도 마주 보는 두 쌍의 변이 서로 평행해서","correct":true},{"t":"평행사변형은 기울어져 있어야 해서","mis":"M4-2-u2-X11"}],"mis":"M4-2-u2-X11","explanation":["이름마다 뜻을 떠올려 봐요 — 사다리꼴(평행한 변 한 쌍 이상) · 평행사변형(두 쌍) · 마름모(네 변) · 직사각형(네 각).","한쪽 뜻을 모두 가지면 그 이름으로도 부를 수 있어요.","거꾸로는 늘 맞지는 않아요 — 직사각형이 모두 정사각형인 것은 아니에요."],"variant_rule":{"alt":[{"stem":"직사각형은 모두 정사각형이에요.","answer":"X","reason_options":[{"t":"직사각형은 이웃한 두 변의 길이가 다를 수 있어서","correct":true},{"t":"네 각이 직각이면 모두 정사각형이라서","mis":"M4-2-u2-X16"}],"explanation":["이름마다 뜻을 떠올려 봐요 — 사다리꼴(평행한 변 한 쌍 이상) · 평행사변형(두 쌍) · 마름모(네 변) · 직사각형(네 각).","한쪽 뜻을 모두 가지면 그 이름으로도 부를 수 있어요.","거꾸로는 늘 맞지는 않아요 — 직사각형이 모두 정사각형인 것은 아니에요."],"asset":null},{"stem":"정사각형은 직사각형이라고 할 수 있어요.","answer":"O","reason_options":[{"t":"정사각형도 네 각이 모두 직각이어서","correct":true},{"t":"정사각형에는 이름이 하나뿐이라서","mis":"M4-2-u2-X17"}],"explanation":["이름마다 뜻을 떠올려 봐요 — 사다리꼴(평행한 변 한 쌍 이상) · 평행사변형(두 쌍) · 마름모(네 변) · 직사각형(네 각).","한쪽 뜻을 모두 가지면 그 이름으로도 부를 수 있어요.","거꾸로는 늘 맞지는 않아요 — 직사각형이 모두 정사각형인 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L08_basic#8','math',4,2,'u2','L08','g4_2_math_u2_L08_basic','lesson_basic','M4-2-u2-C9',2,'match','auto','사각형의 특징과 이름을 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u2-C9","difficulty":2,"kind":"match","stem":"사각형의 특징과 이름을 알맞게 이으세요.","pairs":[{"l":"평행한 변이 한 쌍이라도 있어요","r":"사다리꼴"},{"l":"마주 보는 두 쌍의 변이 평행해요","r":"평행사변형"},{"l":"네 각이 모두 직각이에요","r":"직사각형"}],"mis":"M4-2-u2-X10","explanation":["사각형을 가르는 기준은 평행한 변 · 변의 길이 · 각의 크기예요.","기준마다 따로 이름을 붙여요.","그래서 한 사각형이 여러 이름을 가질 수 있어요."],"variant_rule":{"alt":[{"stem":"사각형의 특징과 이름을 알맞게 이으세요.","pairs":[{"l":"네 변의 길이가 모두 같아요","r":"마름모"},{"l":"네 각이 모두 직각이에요","r":"직사각형"},{"l":"네 변이 같고 네 각이 직각이에요","r":"정사각형"}],"explanation":["사각형을 가르는 기준은 평행한 변 · 변의 길이 · 각의 크기예요.","기준마다 따로 이름을 붙여요.","그래서 한 사각형이 여러 이름을 가질 수 있어요."],"asset":null},{"stem":"정사각형을 어떤 기준으로 보면 어떤 이름이 되는지 알맞게 이으세요.","pairs":[{"l":"네 각의 크기를 보면","r":"직사각형"},{"l":"네 변의 길이를 보면","r":"마름모"},{"l":"평행한 변 두 쌍을 보면","r":"평행사변형"}],"explanation":["사각형을 가르는 기준은 평행한 변 · 변의 길이 · 각의 크기예요.","기준마다 따로 이름을 붙여요.","그래서 한 사각형이 여러 이름을 가질 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L08_basic#9','math',4,2,'u2','L08','g4_2_math_u2_L08_basic','lesson_basic','M4-2-u2-C9',2,'sa','auto','직사각형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u2-C9","difficulty":2,"kind":"sa","stem":"직사각형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아 9 cm 둘, 5 cm 둘이에요.","(9 + 5) × 2를 계산해요.","28 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,15.0],"ㄴ":[120.0,15.0],"ㄷ":[120.0,75.0],"ㄹ":[15.0,75.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"right":[["ㄹ","ㄱ","ㄴ"],["ㄱ","ㄴ","ㄷ"],["ㄴ","ㄷ","ㄹ"],["ㄷ","ㄹ","ㄱ"]],"lab":[[[67.5,3.75],"9 cm"],[[139.65,45.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직사각형 ㅁㅂㅅㅇ의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["34"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아 6 cm 둘, 11 cm 둘이에요.","(6 + 11) × 2를 계산해요.","34 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[45.0,7.5],"ㅂ":[90.0,7.5],"ㅅ":[90.0,82.5],"ㅇ":[45.0,82.5]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"right":[["ㅇ","ㅁ","ㅂ"],["ㅁ","ㅂ","ㅅ"],["ㅂ","ㅅ","ㅇ"],["ㅅ","ㅇ","ㅁ"]],"lab":[[[67.5,-3.75],"6 cm"],[[111.75,45.0],"11 cm"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 직사각형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아 12 cm 둘, 6 cm 둘이에요.","(12 + 6) × 2를 계산해요.","36 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,45.0],"ㄴ":[75.0,15.0],"ㄷ":[90.0,45.0],"ㄹ":[30.0,75.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"right":[["ㄹ","ㄱ","ㄴ"],["ㄱ","ㄴ","ㄷ"],["ㄴ","ㄷ","ㄹ"],["ㄷ","ㄹ","ㄱ"]],"lab":[[[37.868847050625476,15.737694101250948],"12 cm"],[[99.28230589874906,21.60884705062547],"6 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
