INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L08_challenge#4','math',4,2,'u2','L08','g4_2_math_u2_L08_challenge','lesson_challenge','M4-2-u2-C9',3,'sa','auto','횡단보도 앞에 똑같은 정사각형 보도블록을 가로 3장, 세로 2장 깔았어요. 그림에서 찾을 수 있는 크고 작은 정사각형은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u2-C9","difficulty":3,"kind":"sa","stem":"횡단보도 앞에 똑같은 정사각형 보도블록을 가로 3장, 세로 2장 깔았어요. 그림에서 찾을 수 있는 크고 작은 정사각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["작은 정사각형부터 크기별로 차례로 세요.","1칸짜리 6개 · 4칸짜리 2개.","모두 8개예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"seg":[[[15.0,15.0],[82.5,15.0]],[[15.0,37.5],[82.5,37.5]],[[15.0,60.0],[82.5,60.0]],[[15.0,15.0],[15.0,60.0]],[[37.5,15.0],[37.5,60.0]],[[60.0,15.0],[60.0,60.0]],[[82.5,15.0],[82.5,60.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"횡단보도 앞에 똑같은 정사각형 보도블록을 가로 4장, 세로 2장 깔았어요. 그림에서 찾을 수 있는 크고 작은 정사각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["작은 정사각형부터 크기별로 차례로 세요.","1칸짜리 8개 · 4칸짜리 3개.","모두 11개예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"seg":[[[15.0,15.0],[105.0,15.0]],[[15.0,37.5],[105.0,37.5]],[[15.0,60.0],[105.0,60.0]],[[15.0,15.0],[15.0,60.0]],[[37.5,15.0],[37.5,60.0]],[[60.0,15.0],[60.0,60.0]],[[82.5,15.0],[82.5,60.0]],[[105.0,15.0],[105.0,60.0]]]}],"tag":false}},{"stem":"횡단보도 앞에 똑같은 정사각형 보도블록을 가로 3장, 세로 3장 깔았어요. 그림에서 찾을 수 있는 크고 작은 정사각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["작은 정사각형부터 크기별로 차례로 세요.","1칸짜리 9개 · 4칸짜리 4개 · 9칸짜리 1개.","모두 14개예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"seg":[[[15.0,15.0],[82.5,15.0]],[[15.0,37.5],[82.5,37.5]],[[15.0,60.0],[82.5,60.0]],[[15.0,82.5],[82.5,82.5]],[[15.0,15.0],[15.0,82.5]],[[37.5,15.0],[37.5,82.5]],[[60.0,15.0],[60.0,82.5]],[[82.5,15.0],[82.5,82.5]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L08_challenge#5','math',4,2,'u2','L08','g4_2_math_u2_L08_challenge','lesson_challenge','M4-2-u2-C9',3,'sa','auto','직사각형의 네 변의 길이의 합이 30 cm이고 가로가 9 cm예요. 세로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u2-C9","difficulty":3,"kind":"sa","stem":"직사각형의 네 변의 길이의 합이 30 cm이고 가로가 9 cm예요. 세로는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["마주 보는 변의 길이가 같아 (가로 + 세로) × 2 = 30 cm예요.","가로 + 세로 = 30 ÷ 2 = 15 cm.","세로 = 15 − 9 = 6 cm예요."],"variant_rule":{"alt":[{"stem":"직사각형 모양 꽃밭의 둘레가 44 m이고 가로가 15 m예요. 세로는 몇 m인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["마주 보는 변의 길이가 같아 (가로 + 세로) × 2 = 44 m예요.","가로 + 세로 = 44 ÷ 2 = 22 m.","세로 = 22 − 15 = 7 m예요."],"asset":null},{"stem":"직사각형의 네 변의 길이의 합이 50 cm이고 가로가 14 cm예요. 세로는 몇 cm인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["마주 보는 변의 길이가 같아 (가로 + 세로) × 2 = 50 cm예요.","가로 + 세로 = 50 ÷ 2 = 25 cm.","세로 = 25 − 14 = 11 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L08_challenge#6','math',4,2,'u2','L08','g4_2_math_u2_L08_challenge','lesson_challenge','M4-2-u2-C9',3,'sa','auto','가로 12 cm, 세로 5 cm인 직사각형 종이에서 점선을 따라 가장 큰 정사각형을 잘라 냈어요. 남은 직사각형의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u2-C9","difficulty":3,"kind":"sa","stem":"가로 12 cm, 세로 5 cm인 직사각형 종이에서 점선을 따라 가장 큰 정사각형을 잘라 냈어요. 남은 직사각형의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["가장 큰 정사각형은 한 변이 5 cm예요(세로와 같게).","남은 직사각형은 가로 12 − 5 = 7 cm, 세로 5 cm예요.","(7 + 5) × 2 = 24 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"poly":[[[15.0,15.0],[112.5,15.0],[112.5,55.62499999999999],[15.0,55.62499999999999]]],"right":[[[15.0,55.62499999999999],[15.0,15.0],[112.5,15.0]],[[15.0,15.0],[112.5,15.0],[112.5,55.62499999999999]],[[112.5,15.0],[112.5,55.62499999999999],[15.0,55.62499999999999]],[[112.5,55.62499999999999],[15.0,55.62499999999999],[15.0,15.0]]],"lab":[[[63.75,3.75],"12 cm"],[[132.15,35.3125],"5 cm"]],"dash":[[[55.62499999999999,15.0],[55.62499999999999,55.62499999999999]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 10 cm, 세로 4 cm인 직사각형 종이에서 점선을 따라 가장 큰 정사각형을 잘라 냈어요. 남은 직사각형의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["가장 큰 정사각형은 한 변이 4 cm예요(세로와 같게).","남은 직사각형은 가로 10 − 4 = 6 cm, 세로 4 cm예요.","(6 + 4) × 2 = 20 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"poly":[[[15.0,15.0],[112.5,15.0],[112.5,54.0],[15.0,54.0]]],"right":[[[15.0,54.0],[15.0,15.0],[112.5,15.0]],[[15.0,15.0],[112.5,15.0],[112.5,54.0]],[[112.5,15.0],[112.5,54.0],[15.0,54.0]],[[112.5,54.0],[15.0,54.0],[15.0,15.0]]],"lab":[[[63.75,3.75],"10 cm"],[[132.15,34.5],"4 cm"]],"dash":[[[54.0,15.0],[54.0,54.0]]]}],"tag":false}},{"stem":"가로 15 cm, 세로 6 cm인 직사각형 종이에서 점선을 따라 가장 큰 정사각형을 잘라 냈어요. 남은 직사각형의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["가장 큰 정사각형은 한 변이 6 cm예요(세로와 같게).","남은 직사각형은 가로 15 − 6 = 9 cm, 세로 6 cm예요.","(9 + 6) × 2 = 30 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"poly":[[[15.0,15.0],[112.5,15.0],[112.5,54.0],[15.0,54.0]]],"right":[[[15.0,54.0],[15.0,15.0],[112.5,15.0]],[[15.0,15.0],[112.5,15.0],[112.5,54.0]],[[112.5,15.0],[112.5,54.0],[15.0,54.0]],[[112.5,54.0],[15.0,54.0],[15.0,15.0]]],"lab":[[[63.75,3.75],"15 cm"],[[132.15,34.5],"6 cm"]],"dash":[[[54.0,15.0],[54.0,54.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L08_challenge#7','math',4,2,'u2','L08','g4_2_math_u2_L08_challenge','lesson_challenge','M4-2-u2-C9',3,'mc','auto','사각형 사이의 관계를 바르게 말한 것은 어느 것인가요?',ARRAY['M4-2-u2-X16','M4-2-u2-X11','M4-2-u2-X09']::text[],true,'{"seq":7,"concept":"M4-2-u2-C9","difficulty":3,"kind":"mc","stem":"사각형 사이의 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"정사각형은 마름모이면서 직사각형이에요","correct":true},{"t":"마름모는 모두 정사각형이에요","mis":"M4-2-u2-X16"},{"t":"직사각형은 평행사변형이 아니에요","mis":"M4-2-u2-X11"},{"t":"정사각형은 사다리꼴이 아니에요","mis":"M4-2-u2-X09"}],"explanation":["한 사각형이 다른 사각형의 뜻을 모두 가지면 그 이름으로도 불러요.","정사각형 → 마름모·직사각형 → 평행사변형 → 사다리꼴 쪽으로는 늘 맞아요.","거꾸로(마름모 → 정사각형 등)는 늘 맞지는 않아요."],"variant_rule":{"alt":[{"stem":"사각형 사이의 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"직사각형은 사다리꼴이라고 할 수 있어요","correct":true},{"t":"직사각형은 모두 정사각형이에요","mis":"M4-2-u2-X16"},{"t":"마름모는 평행사변형이 아니에요","mis":"M4-2-u2-X17"},{"t":"평행사변형은 모두 마름모예요","mis":"M4-2-u2-X16"}],"explanation":["한 사각형이 다른 사각형의 뜻을 모두 가지면 그 이름으로도 불러요.","정사각형 → 마름모·직사각형 → 평행사변형 → 사다리꼴 쪽으로는 늘 맞아요.","거꾸로(마름모 → 정사각형 등)는 늘 맞지는 않아요."],"asset":null},{"stem":"사각형 사이의 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"마름모 가운데 네 각이 모두 직각인 것은 정사각형이에요","correct":true},{"t":"정사각형은 마름모가 아니에요","mis":"M4-2-u2-X17"},{"t":"사다리꼴은 모두 평행사변형이에요","mis":"M4-2-u2-X16"},{"t":"네 변의 길이가 같은 사각형은 모두 정사각형이에요","mis":"M4-2-u2-X16"}],"explanation":["한 사각형이 다른 사각형의 뜻을 모두 가지면 그 이름으로도 불러요.","정사각형 → 마름모·직사각형 → 평행사변형 → 사다리꼴 쪽으로는 늘 맞아요.","거꾸로(마름모 → 정사각형 등)는 늘 맞지는 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L08_challenge#8','math',4,2,'u2','L08','g4_2_math_u2_L08_challenge','lesson_challenge','M4-2-u2-C9',4,'sa','auto','크기가 같은 정사각형 2개를 겹치지 않게 한 줄로 붙여 직사각형을 만들었어요. 만든 직사각형의 네 변의 길이의 합이 36 cm일 때, 정사각형 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u2-C9","difficulty":4,"kind":"sa","stem":"크기가 같은 정사각형 2개를 겹치지 않게 한 줄로 붙여 직사각형을 만들었어요. 만든 직사각형의 네 변의 길이의 합이 36 cm일 때, 정사각형 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["만든 직사각형의 가로는 정사각형 한 변 2개, 세로는 한 변 1개예요.","네 변의 길이의 합 = 정사각형 한 변의 (2 + 1) × 2 = 6배예요.","36 ÷ 6 = 6 cm예요."],"asset":{"type":"geo","items":[{"w":135,"h":75,"seg":[[[15.0,22.5],[60.0,22.5]],[[15.0,45.0],[60.0,45.0]],[[15.0,22.5],[15.0,45.0]],[[37.5,22.5],[37.5,45.0]],[[60.0,22.5],[60.0,45.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"크기가 같은 정사각형 3개를 겹치지 않게 한 줄로 붙여 직사각형을 만들었어요. 만든 직사각형의 네 변의 길이의 합이 40 cm일 때, 정사각형 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["만든 직사각형의 가로는 정사각형 한 변 3개, 세로는 한 변 1개예요.","네 변의 길이의 합 = 정사각형 한 변의 (3 + 1) × 2 = 8배예요.","40 ÷ 8 = 5 cm예요."],"asset":{"type":"geo","items":[{"w":135,"h":75,"seg":[[[15.0,22.5],[82.5,22.5]],[[15.0,45.0],[82.5,45.0]],[[15.0,22.5],[15.0,45.0]],[[37.5,22.5],[37.5,45.0]],[[60.0,22.5],[60.0,45.0]],[[82.5,22.5],[82.5,45.0]]]}],"tag":false}},{"stem":"크기가 같은 정사각형 4개를 겹치지 않게 한 줄로 붙여 직사각형을 만들었어요. 만든 직사각형의 네 변의 길이의 합이 60 cm일 때, 정사각형 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["만든 직사각형의 가로는 정사각형 한 변 4개, 세로는 한 변 1개예요.","네 변의 길이의 합 = 정사각형 한 변의 (4 + 1) × 2 = 10배예요.","60 ÷ 10 = 6 cm예요."],"asset":{"type":"geo","items":[{"w":135,"h":75,"seg":[[[15.0,22.5],[105.0,22.5]],[[15.0,45.0],[105.0,45.0]],[[15.0,22.5],[15.0,45.0]],[[37.5,22.5],[37.5,45.0]],[[60.0,22.5],[60.0,45.0]],[[82.5,22.5],[82.5,45.0]],[[105.0,22.5],[105.0,45.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L08_challenge#9','math',4,2,'u2','L08','g4_2_math_u2_L08_challenge','lesson_challenge','M4-2-u2-C9',4,'sa','auto','똑같은 정사각형 보도블록을 가로 4장, 세로 1장 깔았어요. 그림에서 찾을 수 있는 크고 작은 직사각형은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u2-C9","difficulty":4,"kind":"sa","stem":"똑같은 정사각형 보도블록을 가로 4장, 세로 1장 깔았어요. 그림에서 찾을 수 있는 크고 작은 직사각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["정사각형도 네 각이 모두 직각이라 직사각형이에요 — 정사각형 4개도 함께 세요.","가로로 고르는 방법 10가지 × 세로로 고르는 방법 1가지로 빠짐없이 세어요.","모두 10개예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"seg":[[[15.0,15.0],[105.0,15.0]],[[15.0,37.5],[105.0,37.5]],[[15.0,15.0],[15.0,37.5]],[[37.5,15.0],[37.5,37.5]],[[60.0,15.0],[60.0,37.5]],[[82.5,15.0],[82.5,37.5]],[[105.0,15.0],[105.0,37.5]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"똑같은 정사각형 보도블록을 가로 2장, 세로 2장 깔았어요. 그림에서 찾을 수 있는 크고 작은 직사각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["정사각형도 네 각이 모두 직각이라 직사각형이에요 — 정사각형 5개도 함께 세요.","가로로 고르는 방법 3가지 × 세로로 고르는 방법 3가지로 빠짐없이 세어요.","모두 9개예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"seg":[[[15.0,15.0],[60.0,15.0]],[[15.0,37.5],[60.0,37.5]],[[15.0,60.0],[60.0,60.0]],[[15.0,15.0],[15.0,60.0]],[[37.5,15.0],[37.5,60.0]],[[60.0,15.0],[60.0,60.0]]]}],"tag":false}},{"stem":"똑같은 정사각형 보도블록을 가로 3장, 세로 2장 깔았어요. 그림에서 찾을 수 있는 크고 작은 직사각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["정사각형도 네 각이 모두 직각이라 직사각형이에요 — 정사각형 8개도 함께 세요.","가로로 고르는 방법 6가지 × 세로로 고르는 방법 3가지로 빠짐없이 세어요.","모두 18개예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"seg":[[[15.0,15.0],[82.5,15.0]],[[15.0,37.5],[82.5,37.5]],[[15.0,60.0],[82.5,60.0]],[[15.0,15.0],[15.0,60.0]],[[37.5,15.0],[37.5,60.0]],[[60.0,15.0],[60.0,60.0]],[[82.5,15.0],[82.5,60.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L08_challenge#10','math',4,2,'u2','L08','g4_2_math_u2_L08_challenge','lesson_challenge','M4-2-u2-C9',4,'essay','teacher','정사각형을 직사각형이라고도, 마름모라고도 부를 수 있는 까닭을 사각형을 가르는 기준을 들어 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u2-C9","difficulty":4,"kind":"essay","stem":"정사각형을 직사각형이라고도, 마름모라고도 부를 수 있는 까닭을 사각형을 가르는 기준을 들어 써 보세요.","answer_guide":{"answer":"예: 각의 크기를 기준으로 보면 정사각형은 네 각이 모두 직각이므로 직사각형이다. 변의 길이를 기준으로 보면 정사각형은 네 변의 길이가 모두 같으므로 마름모이다. 기준이 여러 가지라서 한 사각형이 여러 이름으로 불릴 수 있다.","scoring_points":["네 각이 직각이라 직사각형이라고 썼는가","네 변이 같아 마름모라고 썼는가","기준이 여러 가지라 이름이 여럿이라고 썼는가"]},"explanation":["각의 크기 기준 — 네 각이 직각이라 직사각형.","변의 길이 기준 — 네 변이 같아 마름모.","기준마다 이름이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_basic#1','math',4,2,'u2','L09','g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',1,'mc','auto','두 원을 겹쳐 그려 마름모를 만들려면 두 원을 어떻게 그려야 하나요?',ARRAY['M4-2-u2-X19']::text[],true,'{"seq":1,"concept":"M4-2-u2-C10","difficulty":1,"kind":"mc","stem":"두 원을 겹쳐 그려 마름모를 만들려면 두 원을 어떻게 그려야 하나요?","options":[{"t":"크기가 같게","correct":true},{"t":"크기가 다르게","mis":"M4-2-u2-X19"},{"t":"서로 만나지 않게","mis":"M4-2-u2-X19"},{"t":"하나는 아주 크게","mis":"M4-2-u2-X19"}],"explanation":["컴퍼스를 벌린 정도를 바꾸지 않고 크기가 같은 두 원을 겹쳐 그려요.","두 원의 중심과 두 원이 만나는 점, 모두 네 점을 이어요.","네 변이 모두 반지름이라 길이가 같아요 — 마름모."],"variant_rule":{"alt":[{"stem":"컴퍼스로 두 원을 그려 마름모를 만들 때 꼭 지켜야 할 것은 무엇인가요?","options":[{"t":"컴퍼스를 벌린 정도를 바꾸지 않는다","correct":true},{"t":"두 번째 원은 더 크게 벌려 그린다","mis":"M4-2-u2-X19"},{"t":"두 원이 만나지 않게 멀리 그린다","mis":"M4-2-u2-X19"},{"t":"두 원의 중심을 같은 점에 둔다","mis":"M4-2-u2-X19"}],"explanation":["컴퍼스를 벌린 정도를 바꾸지 않고 크기가 같은 두 원을 겹쳐 그려요.","두 원의 중심과 두 원이 만나는 점, 모두 네 점을 이어요.","네 변이 모두 반지름이라 길이가 같아요 — 마름모."],"asset":null},{"stem":"크기가 같은 두 원을 겹쳐 그린 뒤 마름모가 되게 하려면 어떤 네 점을 이어야 하나요?","options":[{"t":"두 원의 중심 두 개와 두 원이 만나는 점 두 개","correct":true},{"t":"한 원의 중심과 원 위의 아무 점 세 개","mis":"M4-2-u2-X19"},{"t":"두 원이 만나는 점 두 개와 한 원의 중심","mis":"M4-2-u2-X19"},{"t":"두 원 위의 아무 점 네 개","mis":"M4-2-u2-X19"}],"explanation":["컴퍼스를 벌린 정도를 바꾸지 않고 크기가 같은 두 원을 겹쳐 그려요.","두 원의 중심과 두 원이 만나는 점, 모두 네 점을 이어요.","네 변이 모두 반지름이라 길이가 같아요 — 마름모."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_basic#2','math',4,2,'u2','L09','g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',1,'sa','auto','크기가 같은 두 원을 그리고, 두 원의 중심 ㄱ, ㄷ과 두 원이 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 원의 반지름이 5 cm일 때 변 ㄴㄷ의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u2-C10","difficulty":1,"kind":"sa","stem":"크기가 같은 두 원을 그리고, 두 원의 중심 ㄱ, ㄷ과 두 원이 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 원의 반지름이 5 cm일 때 변 ㄴㄷ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["변 ㄴㄷ은 한 원의 중심과 원 위의 점을 이은 선분이에요.","그래서 변 ㄴㄷ은 원의 반지름이에요.","5 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[126.75000000000001,68.25,"e"],"ㄹ":[97.5,107.25,"s"]},"circle":[[[68.25,68.25],48.7],[[126.75000000000001,68.25],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[43.875,57.0],"5 cm"]],"seg":[[[68.25,68.25],[19.500000000000004,68.25]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"크기가 같은 두 원을 그리고, 두 원의 중심 ㄱ, ㄷ과 두 원이 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 원의 반지름이 6 cm일 때 변 ㄷㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["변 ㄷㄹ은 한 원의 중심과 원 위의 점을 이은 선분이에요.","그래서 변 ㄷㄹ은 원의 반지름이에요.","6 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[126.75000000000001,68.25,"e"],"ㄹ":[97.5,107.25,"s"]},"circle":[[[68.25,68.25],48.7],[[126.75000000000001,68.25],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[43.875,57.0],"6 cm"]],"seg":[[[68.25,68.25],[19.500000000000004,68.25]]]}],"tag":false}},{"stem":"크기가 같은 두 원을 그리고, 두 원의 중심 ㄱ, ㄷ과 두 원이 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 원의 반지름이 4 cm일 때 변 ㄱㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["변 ㄱㄹ은 한 원의 중심과 원 위의 점을 이은 선분이에요.","그래서 변 ㄱㄹ은 원의 반지름이에요.","4 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[126.75000000000001,68.25,"e"],"ㄹ":[97.5,107.25,"s"]},"circle":[[[68.25,68.25],48.7],[[126.75000000000001,68.25],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[43.875,57.0],"4 cm"]],"seg":[[[68.25,68.25],[19.500000000000004,68.25]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_basic#3','math',4,2,'u2','L09','g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',1,'mc','auto','그린 사각형 ㄱㄴㄷㄹ이 마름모인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u2-X14','M4-2-u2-X19','M4-2-u2-X03']::text[],true,'{"seq":3,"concept":"M4-2-u2-C10","difficulty":1,"kind":"mc","stem":"그린 사각형 ㄱㄴㄷㄹ이 마름모인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"네 변이 모두 원의 반지름이어서 길이가 같기 때문에","correct":true},{"t":"네 각이 모두 직각이기 때문에","mis":"M4-2-u2-X14"},{"t":"두 원이 겹쳤기 때문에","mis":"M4-2-u2-X19"},{"t":"그려 보니 마름모처럼 보이기 때문에","mis":"M4-2-u2-X03"}],"explanation":["ㄴ·ㄹ은 두 원 위에 있는 점이에요.","그래서 ㄱㄴ·ㄱㄹ은 왼쪽 원의 반지름, ㄷㄴ·ㄷㄹ은 오른쪽 원의 반지름이에요.","두 원의 크기가 같으니 네 변이 모두 같아요 — 마름모."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[126.75000000000001,68.25,"e"],"ㄹ":[97.5,107.25,"s"]},"circle":[[[68.25,68.25],48.7],[[126.75000000000001,68.25],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"변 ㄱㄴ과 변 ㄴㄷ의 길이가 같은 까닭은 무엇인가요?","options":[{"t":"두 변이 모두 크기가 같은 원의 반지름이라서","correct":true},{"t":"두 변이 서로 평행해서","mis":"M4-2-u2-X06"},{"t":"두 변이 서로 수직이라서","mis":"M4-2-u2-X01"},{"t":"눈으로 보기에 같아 보여서","mis":"M4-2-u2-X03"}],"explanation":["ㄴ·ㄹ은 두 원 위에 있는 점이에요.","그래서 ㄱㄴ·ㄱㄹ은 왼쪽 원의 반지름, ㄷㄴ·ㄷㄹ은 오른쪽 원의 반지름이에요.","두 원의 크기가 같으니 네 변이 모두 같아요 — 마름모."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[126.75000000000001,68.25,"e"],"ㄹ":[97.5,107.25,"s"]},"circle":[[[68.25,68.25],48.7],[[126.75000000000001,68.25],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}},{"stem":"변 ㄱㄴ과 변 ㄱㄹ의 길이가 같은 까닭은 무엇인가요?","options":[{"t":"두 변이 모두 점 ㄱ을 중심으로 하는 원의 반지름이라서","correct":true},{"t":"두 변이 마주 보는 변이라서","mis":"M4-2-u2-X12"},{"t":"두 변이 서로 평행해서","mis":"M4-2-u2-X06"},{"t":"두 변이 모두 원의 지름이라서","mis":"M4-2-u2-X19"}],"explanation":["ㄴ·ㄹ은 두 원 위에 있는 점이에요.","그래서 ㄱㄴ·ㄱㄹ은 왼쪽 원의 반지름, ㄷㄴ·ㄷㄹ은 오른쪽 원의 반지름이에요.","두 원의 크기가 같으니 네 변이 모두 같아요 — 마름모."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[126.75000000000001,68.25,"e"],"ㄹ":[97.5,107.25,"s"]},"circle":[[[68.25,68.25],48.7],[[126.75000000000001,68.25],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_basic#4','math',4,2,'u2','L09','g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',1,'sa','auto','반지름이 5 cm인 크기가 같은 두 원으로 그린 마름모 ㄱㄴㄷㄹ의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u2-C10","difficulty":1,"kind":"sa","stem":"반지름이 5 cm인 크기가 같은 두 원으로 그린 마름모 ㄱㄴㄷㄹ의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["마름모의 네 변은 모두 원의 반지름이에요.","한 변이 5 cm인 변이 4개예요.","5 × 4 = 20 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[126.75000000000001,68.25,"e"],"ㄹ":[97.5,107.25,"s"]},"circle":[[[68.25,68.25],48.7],[[126.75000000000001,68.25],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[43.875,57.0],"5 cm"]],"seg":[[[68.25,68.25],[19.500000000000004,68.25]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"반지름이 7 cm인 크기가 같은 두 원으로 그린 마름모 ㄱㄴㄷㄹ의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["마름모의 네 변은 모두 원의 반지름이에요.","한 변이 7 cm인 변이 4개예요.","7 × 4 = 28 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[126.75000000000001,68.25,"e"],"ㄹ":[97.5,107.25,"s"]},"circle":[[[68.25,68.25],48.7],[[126.75000000000001,68.25],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[43.875,57.0],"7 cm"]],"seg":[[[68.25,68.25],[19.500000000000004,68.25]]]}],"tag":false}},{"stem":"반지름이 6 cm인 크기가 같은 두 원으로 그린 마름모 ㄱㄴㄷㄹ의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["마름모의 네 변은 모두 원의 반지름이에요.","한 변이 6 cm인 변이 4개예요.","6 × 4 = 24 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[126.75000000000001,68.25,"e"],"ㄹ":[97.5,107.25,"s"]},"circle":[[[68.25,68.25],48.7],[[126.75000000000001,68.25],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[43.875,57.0],"6 cm"]],"seg":[[[68.25,68.25],[19.500000000000004,68.25]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_basic#5','math',4,2,'u2','L09','g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',2,'mc','auto','크기가 다른 두 원으로 그린 사각형 ㄱㄴㄷㄹ이 마름모가 아닌 까닭은 무엇인가요?',ARRAY['M4-2-u2-X18','M4-2-u2-X14','M4-2-u2-X19']::text[],true,'{"seq":5,"concept":"M4-2-u2-C10","difficulty":2,"kind":"mc","stem":"크기가 다른 두 원으로 그린 사각형 ㄱㄴㄷㄹ이 마름모가 아닌 까닭은 무엇인가요?","options":[{"t":"길이가 다른 변이 생겨서","correct":true},{"t":"변이 네 개가 아니어서","mis":"M4-2-u2-X18"},{"t":"네 각이 모두 직각이어서","mis":"M4-2-u2-X14"},{"t":"두 원이 서로 만나서","mis":"M4-2-u2-X19"}],"explanation":["변 ㄱㄴ·ㄱㄹ은 작은 원의 반지름, 변 ㄴㄷ·ㄷㄹ은 큰 원의 반지름이에요.","두 원의 반지름이 다르니 길이가 다른 변이 생겨요.","네 변의 길이가 모두 같지 않아 마름모가 아니에요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[58.50000000000001,68.25,"w"],"ㄴ":[87.75000000000001,29.250000000000004,"n"],"ㄷ":[136.5,68.25,"e"],"ㄹ":[87.75000000000001,107.25,"s"]},"circle":[[[58.50000000000001,68.25],48.7],[[136.5,68.25],62.4]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"크기가 다른 두 원으로 그린 사각형 ㄱㄴㄷㄹ에서 길이가 같은 변끼리 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"변 ㄱㄴ과 변 ㄱㄹ, 변 ㄴㄷ과 변 ㄷㄹ","correct":true},{"t":"변 ㄱㄴ과 변 ㄴㄷ, 변 ㄷㄹ과 변 ㄱㄹ","mis":"M4-2-u2-X19"},{"t":"네 변의 길이가 모두 같다","mis":"M4-2-u2-X19"},{"t":"변 ㄱㄴ과 변 ㄷㄹ, 변 ㄴㄷ과 변 ㄱㄹ","mis":"M4-2-u2-X12"}],"explanation":["변 ㄱㄴ·ㄱㄹ은 작은 원의 반지름, 변 ㄴㄷ·ㄷㄹ은 큰 원의 반지름이에요.","두 원의 반지름이 다르니 길이가 다른 변이 생겨요.","네 변의 길이가 모두 같지 않아 마름모가 아니에요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[58.50000000000001,68.25,"w"],"ㄴ":[87.75000000000001,29.250000000000004,"n"],"ㄷ":[136.5,68.25,"e"],"ㄹ":[87.75000000000001,107.25,"s"]},"circle":[[[58.50000000000001,68.25],48.7],[[136.5,68.25],62.4]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}},{"stem":"반지름이 3 cm인 원과 5 cm인 원을 겹쳐 그려, 두 원의 중심과 만나는 점을 이었어요. 이 사각형은 마름모인가요?","options":[{"t":"아니다 — 3 cm인 변 두 개와 5 cm인 변 두 개가 생긴다","correct":true},{"t":"그렇다 — 두 원을 겹쳐 그렸다","mis":"M4-2-u2-X19"},{"t":"그렇다 — 네 변이 모두 4 cm이다","mis":"M4-2-u2-X13"},{"t":"아니다 — 변이 세 개뿐이다","mis":"M4-2-u2-X18"}],"explanation":["변 ㄱㄴ·ㄱㄹ은 작은 원의 반지름, 변 ㄴㄷ·ㄷㄹ은 큰 원의 반지름이에요.","두 원의 반지름이 다르니 길이가 다른 변이 생겨요.","네 변의 길이가 모두 같지 않아 마름모가 아니에요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[58.50000000000001,68.25,"w"],"ㄴ":[87.75000000000001,29.250000000000004,"n"],"ㄷ":[136.5,68.25,"e"],"ㄹ":[87.75000000000001,107.25,"s"]},"circle":[[[58.50000000000001,68.25],48.7],[[136.5,68.25],62.4]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_basic#6','math',4,2,'u2','L09','g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',2,'sa','auto','크기가 같은 두 원으로 그린 마름모의 네 변의 길이의 합이 36 cm예요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u2-C10","difficulty":2,"kind":"sa","stem":"크기가 같은 두 원으로 그린 마름모의 네 변의 길이의 합이 36 cm예요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["마름모의 네 변은 모두 원의 반지름이에요.","네 변의 길이의 합 = 반지름 × 4.","36 ÷ 4 = 9 cm예요."],"variant_rule":{"alt":[{"stem":"컴퍼스로 크기가 같은 두 원을 그려 만든 마름모의 둘레가 28 cm예요. 컴퍼스를 몇 cm 벌렸을까요? 숫자로 쓰세요.","answer":["7"],"explanation":["마름모의 네 변은 모두 원의 반지름이에요.","네 변의 길이의 합 = 반지름 × 4.","28 ÷ 4 = 7 cm예요."],"asset":null},{"stem":"크기가 같은 두 원으로 그린 마름모의 네 변의 길이의 합이 44 cm예요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["마름모의 네 변은 모두 원의 반지름이에요.","네 변의 길이의 합 = 반지름 × 4.","44 ÷ 4 = 11 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_basic#7','math',4,2,'u2','L09','g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',2,'ox','auto','반지름이 6 cm인 크기가 같은 두 원으로 그린 마름모의 한 변은 12 cm예요.',ARRAY['M4-2-u2-X19']::text[],true,'{"seq":7,"concept":"M4-2-u2-C10","difficulty":2,"kind":"ox","stem":"반지름이 6 cm인 크기가 같은 두 원으로 그린 마름모의 한 변은 12 cm예요.","answer":"X","reason_options":[{"t":"마름모의 변은 지름이 아니라 반지름이라서","correct":true},{"t":"원의 지름이 한 변이 되어서","mis":"M4-2-u2-X19"}],"mis":"M4-2-u2-X19","explanation":["두 원으로 그린 사각형의 네 변은 모두 반지름이에요.","반지름은 지름의 반이에요.","두 원의 크기가 같아야 네 변이 모두 같아져요."],"variant_rule":{"alt":[{"stem":"지름이 10 cm인 크기가 같은 두 원으로 그린 마름모의 한 변은 5 cm예요.","answer":"O","reason_options":[{"t":"변은 반지름이고 반지름은 지름의 반이라서","correct":true},{"t":"변은 지름과 길이가 같아서","mis":"M4-2-u2-X19"}],"explanation":["두 원으로 그린 사각형의 네 변은 모두 반지름이에요.","반지름은 지름의 반이에요.","두 원의 크기가 같아야 네 변이 모두 같아져요."],"asset":null},{"stem":"크기가 다른 두 원으로도 두 중심과 만나는 두 점을 이으면 마름모가 돼요.","answer":"X","reason_options":[{"t":"두 원의 반지름이 달라 길이가 다른 변이 생겨서","correct":true},{"t":"두 원을 겹치기만 하면 마름모가 되어서","mis":"M4-2-u2-X19"}],"explanation":["두 원으로 그린 사각형의 네 변은 모두 반지름이에요.","반지름은 지름의 반이에요.","두 원의 크기가 같아야 네 변이 모두 같아져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_basic#8','math',4,2,'u2','L09','g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',2,'mc','auto','사다리꼴을 그리려면 무엇을 먼저 그어야 하나요?',ARRAY['M4-2-u2-X10','M4-2-u2-X14']::text[],true,'{"seq":8,"concept":"M4-2-u2-C10","difficulty":2,"kind":"mc","stem":"사다리꼴을 그리려면 무엇을 먼저 그어야 하나요?","options":[{"t":"서로 평행한 두 직선","correct":true},{"t":"직각으로 만나는 두 직선","mis":"M4-2-u2-X10"},{"t":"길이가 같은 네 선분","mis":"M4-2-u2-X14"},{"t":"한 점에서 만나는 세 직선","mis":"M4-2-u2-X10"}],"explanation":["그리려는 사각형의 뜻을 먼저 떠올려요.","사다리꼴·평행사변형은 평행선으로, 직사각형은 수선과 평행선으로, 마름모는 크기가 같은 두 원으로 그려요.","뜻에 맞는 조건(평행·수직·같은 길이)이 생기게 그려요."],"variant_rule":{"alt":[{"stem":"평행사변형을 그리는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"평행선을 두 쌍 그어 서로 만나게 한다","correct":true},{"t":"평행선을 한 쌍만 그어 잇는다","mis":"M4-2-u2-X09"},{"t":"수직인 두 직선만 긋는다","mis":"M4-2-u2-X11"},{"t":"길이가 다른 네 선분을 아무렇게나 잇는다","mis":"M4-2-u2-X10"}],"explanation":["그리려는 사각형의 뜻을 먼저 떠올려요.","사다리꼴·평행사변형은 평행선으로, 직사각형은 수선과 평행선으로, 마름모는 크기가 같은 두 원으로 그려요.","뜻에 맞는 조건(평행·수직·같은 길이)이 생기게 그려요."],"asset":null},{"stem":"직사각형을 그리는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 변에 수선을 긋고, 평행선과 수선을 이용해 네 각이 직각이 되게 그린다","correct":true},{"t":"네 변의 길이만 같게 그린다","mis":"M4-2-u2-X14"},{"t":"평행한 변이 한 쌍만 있게 그린다","mis":"M4-2-u2-X09"},{"t":"비스듬히 기울어지게 그린다","mis":"M4-2-u2-X11"}],"explanation":["그리려는 사각형의 뜻을 먼저 떠올려요.","사다리꼴·평행사변형은 평행선으로, 직사각형은 수선과 평행선으로, 마름모는 크기가 같은 두 원으로 그려요.","뜻에 맞는 조건(평행·수직·같은 길이)이 생기게 그려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_basic#9','math',4,2,'u2','L09','g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',2,'mc','auto','모눈 위의 세 점 ㄱ, ㄴ, ㄷ에 한 점을 더 이어 평행사변형을 그리려고 해요. 어느 점을 이어야 하나요?',ARRAY['M4-2-u2-X10']::text[],true,'{"seq":9,"concept":"M4-2-u2-C10","difficulty":2,"kind":"mc","stem":"모눈 위의 세 점 ㄱ, ㄴ, ㄷ에 한 점을 더 이어 평행사변형을 그리려고 해요. 어느 점을 이어야 하나요?","options":[{"t":"점 가","correct":true},{"t":"점 나","mis":"M4-2-u2-X10"},{"t":"점 다","mis":"M4-2-u2-X10"},{"t":"점 라","mis":"M4-2-u2-X10"}],"explanation":["평행사변형의 뜻을 떠올리고, 모눈 칸을 세어 확인해요.","점 가을 이으면 평행사변형의 조건(평행한 변·변의 길이·직각)이 모두 맞아요.","나머지 점은 변이 평행하지 않거나 길이·각이 맞지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[120.0,15.0],"가":[45.0,15.0],"나":[15.0,15.0],"다":[75.0,15.0],"라":[45.0,45.0]},"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"모눈 위의 세 점 ㄱ, ㄴ, ㄷ에 한 점을 더 이어 마름모를 그리려고 해요. 어느 점을 이어야 하나요?","options":[{"t":"점 라","correct":true},{"t":"점 가","mis":"M4-2-u2-X14"},{"t":"점 나","mis":"M4-2-u2-X14"},{"t":"점 다","mis":"M4-2-u2-X14"}],"explanation":["마름모의 뜻을 떠올리고, 모눈 칸을 세어 확인해요.","점 라을 이으면 마름모의 조건(평행한 변·변의 길이·직각)이 모두 맞아요.","나머지 점은 변이 평행하지 않거나 길이·각이 맞지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[135.0,15.0],"가":[30.0,15.0],"나":[90.0,15.0],"다":[60.0,45.0],"라":[60.0,15.0]},"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"]]}],"tag":false}},{"stem":"모눈 위의 세 점 ㄱ, ㄴ, ㄷ에 한 점을 더 이어 직사각형을 그리려고 해요. 어느 점을 이어야 하나요?","options":[{"t":"점 다","correct":true},{"t":"점 가","mis":"M4-2-u2-X10"},{"t":"점 나","mis":"M4-2-u2-X10"},{"t":"점 라","mis":"M4-2-u2-X10"}],"explanation":["직사각형의 뜻을 떠올리고, 모눈 칸을 세어 확인해요.","점 다을 이으면 직사각형의 조건(평행한 변·변의 길이·직각)이 모두 맞아요.","나머지 점은 변이 평행하지 않거나 길이·각이 맞지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":97.5,"grid":15,"pts":{"ㄱ":[30.0,60.0],"ㄴ":[90.0,30.0],"ㄷ":[105.0,60.0],"가":[75.0,90.0],"나":[120.0,90.0],"다":[45.0,90.0],"라":[15.0,90.0]},"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_basic#10','math',4,2,'u2','L09','g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',3,'sa','auto','반지름이 3 cm인 원과 5 cm인 원을 겹쳐 그리고, 두 원의 중심과 두 원이 만나는 점을 이어 사각형 ㄱㄴㄷㄹ을 그렸어요. 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u2-C10","difficulty":3,"kind":"sa","stem":"반지름이 3 cm인 원과 5 cm인 원을 겹쳐 그리고, 두 원의 중심과 두 원이 만나는 점을 이어 사각형 ㄱㄴㄷㄹ을 그렸어요. 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["변 ㄱㄴ·ㄱㄹ은 작은 원의 반지름 3 cm, 변 ㄴㄷ·ㄷㄹ은 큰 원의 반지름 5 cm예요.","3 + 3 + 5 + 5를 계산해요.","16 cm예요(네 변이 같지 않아 마름모는 아니에요)."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[58.50000000000001,68.25,"w"],"ㄴ":[87.75000000000001,29.250000000000004,"n"],"ㄷ":[136.5,68.25,"e"],"ㄹ":[87.75000000000001,107.25,"s"]},"circle":[[[58.50000000000001,68.25],48.7],[[136.5,68.25],62.4]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[61.125,39.75],"3 cm"],[[121.49542571331635,37.036967858354544],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원과 6 cm인 원을 겹쳐 그리고, 두 원의 중심과 두 원이 만나는 점을 이어 사각형 ㄱㄴㄷㄹ을 그렸어요. 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["변 ㄱㄴ·ㄱㄹ은 작은 원의 반지름 4 cm, 변 ㄴㄷ·ㄷㄹ은 큰 원의 반지름 6 cm예요.","4 + 4 + 6 + 6을 계산해요.","20 cm예요(네 변이 같지 않아 마름모는 아니에요)."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[58.50000000000001,68.25,"w"],"ㄴ":[87.75000000000001,29.250000000000004,"n"],"ㄷ":[136.5,68.25,"e"],"ㄹ":[87.75000000000001,107.25,"s"]},"circle":[[[58.50000000000001,68.25],48.7],[[136.5,68.25],62.4]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[61.125,39.75],"4 cm"],[[121.49542571331635,37.036967858354544],"6 cm"]]}],"tag":false}},{"stem":"반지름이 5 cm인 원과 8 cm인 원을 겹쳐 그리고, 두 원의 중심과 두 원이 만나는 점을 이어 사각형 ㄱㄴㄷㄹ을 그렸어요. 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["변 ㄱㄴ·ㄱㄹ은 작은 원의 반지름 5 cm, 변 ㄴㄷ·ㄷㄹ은 큰 원의 반지름 8 cm예요.","5 + 5 + 8 + 8을 계산해요.","26 cm예요(네 변이 같지 않아 마름모는 아니에요)."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[58.50000000000001,68.25,"w"],"ㄴ":[87.75000000000001,29.250000000000004,"n"],"ㄷ":[136.5,68.25,"e"],"ㄹ":[87.75000000000001,107.25,"s"]},"circle":[[[58.50000000000001,68.25],48.7],[[136.5,68.25],62.4]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[61.125,39.75],"5 cm"],[[121.49542571331635,37.036967858354544],"8 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_challenge#1','math',4,2,'u2','L09','g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C10',2,'mc','auto','모눈 위의 세 점 ㄱ, ㄴ, ㄷ에 한 점을 더 이어 정사각형을 그리려고 해요. 어느 점을 이어야 하나요?',ARRAY['M4-2-u2-X16']::text[],true,'{"seq":1,"concept":"M4-2-u2-C10","difficulty":2,"kind":"mc","stem":"모눈 위의 세 점 ㄱ, ㄴ, ㄷ에 한 점을 더 이어 정사각형을 그리려고 해요. 어느 점을 이어야 하나요?","options":[{"t":"점 나","correct":true},{"t":"점 가","mis":"M4-2-u2-X16"},{"t":"점 다","mis":"M4-2-u2-X16"},{"t":"점 라","mis":"M4-2-u2-X16"}],"explanation":["정사각형의 뜻을 떠올리고, 모눈 칸을 세어 확인해요.","점 나을 이으면 정사각형의 조건(평행한 변·변의 길이·직각)이 모두 맞아요.","나머지 점은 변이 평행하지 않거나 길이·각이 맞지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":97.5,"grid":15,"pts":{"ㄱ":[45.0,7.5],"ㄴ":[90.0,37.5],"ㄷ":[60.0,82.5],"가":[45.0,52.5],"나":[15.0,52.5],"다":[15.0,22.5],"라":[15.0,82.5]},"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"모눈 위의 세 점 ㄱ, ㄴ, ㄷ에 한 점을 더 이어 마름모를 그리려고 해요. 어느 점을 이어야 하나요?","options":[{"t":"점 라","correct":true},{"t":"점 가","mis":"M4-2-u2-X14"},{"t":"점 나","mis":"M4-2-u2-X14"},{"t":"점 다","mis":"M4-2-u2-X14"}],"explanation":["마름모의 뜻을 떠올리고, 모눈 칸을 세어 확인해요.","점 라을 이으면 마름모의 조건(평행한 변·변의 길이·직각)이 모두 맞아요.","나머지 점은 변이 평행하지 않거나 길이·각이 맞지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[135.0,15.0],"가":[30.0,15.0],"나":[90.0,15.0],"다":[60.0,45.0],"라":[60.0,15.0]},"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"]]}],"tag":false}},{"stem":"모눈 위의 세 점 ㄱ, ㄴ, ㄷ에 한 점을 더 이어 평행사변형을 그리려고 해요. 어느 점을 이어야 하나요?","options":[{"t":"점 가","correct":true},{"t":"점 나","mis":"M4-2-u2-X10"},{"t":"점 다","mis":"M4-2-u2-X10"},{"t":"점 라","mis":"M4-2-u2-X10"}],"explanation":["평행사변형의 뜻을 떠올리고, 모눈 칸을 세어 확인해요.","점 가을 이으면 평행사변형의 조건(평행한 변·변의 길이·직각)이 모두 맞아요.","나머지 점은 변이 평행하지 않거나 길이·각이 맞지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[120.0,15.0],"가":[45.0,15.0],"나":[15.0,15.0],"다":[75.0,15.0],"라":[45.0,45.0]},"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_challenge#2','math',4,2,'u2','L09','g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C10',2,'sa','auto','컴퍼스로 크기가 같은 두 원을 그려 만든 마름모의 둘레가 52 cm예요. 컴퍼스를 몇 cm 벌렸을까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u2-C10","difficulty":2,"kind":"sa","stem":"컴퍼스로 크기가 같은 두 원을 그려 만든 마름모의 둘레가 52 cm예요. 컴퍼스를 몇 cm 벌렸을까요? 숫자로 쓰세요.","answer":["13"],"explanation":["마름모의 네 변은 모두 원의 반지름이에요.","네 변의 길이의 합 = 반지름 × 4.","52 ÷ 4 = 13 cm예요."],"variant_rule":{"alt":[{"stem":"컴퍼스로 크기가 같은 두 원을 그려 만든 마름모의 둘레가 28 cm예요. 컴퍼스를 몇 cm 벌렸을까요? 숫자로 쓰세요.","answer":["7"],"explanation":["마름모의 네 변은 모두 원의 반지름이에요.","네 변의 길이의 합 = 반지름 × 4.","28 ÷ 4 = 7 cm예요."],"asset":null},{"stem":"크기가 같은 두 원으로 그린 마름모의 네 변의 길이의 합이 36 cm예요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["마름모의 네 변은 모두 원의 반지름이에요.","네 변의 길이의 합 = 반지름 × 4.","36 ÷ 4 = 9 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
