 + 5 + 5를 계산해요.","16 cm예요(네 변이 같지 않아 마름모는 아니에요)."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[58.50000000000001,68.25,"w"],"ㄴ":[87.75000000000001,29.250000000000004,"n"],"ㄷ":[136.5,68.25,"e"],"ㄹ":[87.75000000000001,107.25,"s"]},"circle":[[[58.50000000000001,68.25],48.7],[[136.5,68.25],62.4]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[61.125,39.75],"3 cm"],[[121.49542571331635,37.036967858354544],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_challenge#4','math',4,2,'u2','L09','g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C10',3,'error','auto','컴퍼스로 마름모를 그리는 방법을 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u2-X19','M4-2-u2-X18']::text[],true,'{"seq":4,"concept":"M4-2-u2-C10","difficulty":3,"kind":"error","stem":"컴퍼스로 마름모를 그리는 방법을 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「두 번째 원은 컴퍼스를 더 벌려 그려도 마름모가 돼.」","correct":true,"mis_target":"M4-2-u2-X19"},{"t":"서윤 — 「컴퍼스를 벌린 정도를 그대로 두고 두 원을 그려.」","mis":"M4-2-u2-X18"},{"t":"시우 — 「두 원의 중심과 두 원이 만나는 점을 이어.」","mis":"M4-2-u2-X18"},{"t":"은우 — 「네 변이 모두 반지름이라 길이가 같아.」","mis":"M4-2-u2-X18"}],"explanation":["크기가 같은 두 원을 겹쳐 그리고, 두 중심과 만나는 두 점을 모두 이어요.","네 변은 모두 반지름 — 지름이 아니에요.","도윤의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"컴퍼스로 마름모를 그리는 방법을 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「원의 지름이 마름모의 한 변이 돼.」","correct":true,"mis_target":"M4-2-u2-X19"},{"t":"시우 — 「마름모의 한 변은 원의 반지름이야.」","mis":"M4-2-u2-X18"},{"t":"은우 — 「두 원은 서로 겹치게 그려.」","mis":"M4-2-u2-X18"},{"t":"하랑 — 「반지름이 4 cm면 네 변의 합은 16 cm야.」","mis":"M4-2-u2-X18"}],"explanation":["크기가 같은 두 원을 겹쳐 그리고, 두 중심과 만나는 두 점을 모두 이어요.","네 변은 모두 반지름 — 지름이 아니에요.","서윤의 말이 잘못되었어요."],"asset":null},{"stem":"컴퍼스로 마름모를 그리는 방법을 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「두 원이 만나는 점 두 개만 이으면 마름모가 돼.」","correct":true,"mis_target":"M4-2-u2-X19"},{"t":"은우 — 「두 원의 중심 두 개도 함께 이어야 해.」","mis":"M4-2-u2-X18"},{"t":"하랑 — 「두 원의 크기를 같게 그려.」","mis":"M4-2-u2-X18"},{"t":"지아 — 「그린 사각형은 평행사변형이기도 해.」","mis":"M4-2-u2-X18"}],"explanation":["크기가 같은 두 원을 겹쳐 그리고, 두 중심과 만나는 두 점을 모두 이어요.","네 변은 모두 반지름 — 지름이 아니에요.","시우의 말이 잘못되었어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_challenge#5','math',4,2,'u2','L09','g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C10',3,'mc','auto','컴퍼스로 마름모를 그리는 순서대로 바르게 늘어놓은 것은 어느 것인가요? ㉠ 두 원이 만나는 두 점을 찾는다 ㉡ 컴퍼스를 알맞게 벌려 원 하나를 그린다 ㉢ 두 원의 중심과 만나는 두 점을 차례로 이어 사각형을 그린다 ㉣ 벌린 정도를 그대로 두고 중심을 옮겨 첫 원과 겹치게 원을 하나 더 그린다',ARRAY['M4-2-u2-X19']::text[],true,'{"seq":5,"concept":"M4-2-u2-C10","difficulty":3,"kind":"mc","stem":"컴퍼스로 마름모를 그리는 순서대로 바르게 늘어놓은 것은 어느 것인가요? ㉠ 두 원이 만나는 두 점을 찾는다 ㉡ 컴퍼스를 알맞게 벌려 원 하나를 그린다 ㉢ 두 원의 중심과 만나는 두 점을 차례로 이어 사각형을 그린다 ㉣ 벌린 정도를 그대로 두고 중심을 옮겨 첫 원과 겹치게 원을 하나 더 그린다","options":[{"t":"㉡ → ㉣ → ㉠ → ㉢","correct":true},{"t":"㉣ → ㉡ → ㉠ → ㉢","mis":"M4-2-u2-X19"},{"t":"㉡ → ㉠ → ㉣ → ㉢","mis":"M4-2-u2-X19"},{"t":"㉡ → ㉣ → ㉢ → ㉠","mis":"M4-2-u2-X19"}],"explanation":["먼저 원 하나, 그다음 벌린 정도를 그대로 둔 채 겹치는 원 하나를 그려요.","두 원이 만나는 점을 찾은 뒤 네 점을 이어요.","순서: ㉡ → ㉣ → ㉠ → ㉢."],"variant_rule":{"alt":[{"stem":"컴퍼스로 마름모를 그리는 순서대로 바르게 늘어놓은 것은 어느 것인가요? ㉠ 벌린 정도를 그대로 두고 중심을 옮겨 첫 원과 겹치게 원을 하나 더 그린다 ㉡ 두 원의 중심과 만나는 두 점을 차례로 이어 사각형을 그린다 ㉢ 컴퍼스를 알맞게 벌려 원 하나를 그린다 ㉣ 두 원이 만나는 두 점을 찾는다","options":[{"t":"㉢ → ㉠ → ㉣ → ㉡","correct":true},{"t":"㉠ → ㉢ → ㉣ → ㉡","mis":"M4-2-u2-X19"},{"t":"㉢ → ㉣ → ㉠ → ㉡","mis":"M4-2-u2-X19"},{"t":"㉢ → ㉠ → ㉡ → ㉣","mis":"M4-2-u2-X19"}],"explanation":["먼저 원 하나, 그다음 벌린 정도를 그대로 둔 채 겹치는 원 하나를 그려요.","두 원이 만나는 점을 찾은 뒤 네 점을 이어요.","순서: ㉢ → ㉠ → ㉣ → ㉡."],"asset":null},{"stem":"컴퍼스로 마름모를 그리는 순서대로 바르게 늘어놓은 것은 어느 것인가요? ㉠ 두 원의 중심과 만나는 두 점을 차례로 이어 사각형을 그린다 ㉡ 벌린 정도를 그대로 두고 중심을 옮겨 첫 원과 겹치게 원을 하나 더 그린다 ㉢ 두 원이 만나는 두 점을 찾는다 ㉣ 컴퍼스를 알맞게 벌려 원 하나를 그린다","options":[{"t":"㉣ → ㉡ → ㉢ → ㉠","correct":true},{"t":"㉡ → ㉣ → ㉢ → ㉠","mis":"M4-2-u2-X19"},{"t":"㉣ → ㉢ → ㉡ → ㉠","mis":"M4-2-u2-X19"},{"t":"㉣ → ㉡ → ㉠ → ㉢","mis":"M4-2-u2-X19"}],"explanation":["먼저 원 하나, 그다음 벌린 정도를 그대로 둔 채 겹치는 원 하나를 그려요.","두 원이 만나는 점을 찾은 뒤 네 점을 이어요.","순서: ㉣ → ㉡ → ㉢ → ㉠."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_challenge#6','math',4,2,'u2','L09','g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C9',3,'mc','auto','마주 보는 두 쌍의 변이 서로 평행하고, 네 각이 모두 직각이며, 이웃한 두 변의 길이가 달라요. 이 사각형의 이름이 될 수 없는 것은 어느 것인가요?',ARRAY['M4-2-u2-X17','M4-2-u2-X18']::text[],true,'{"seq":6,"concept":"M4-2-u2-C9","difficulty":3,"kind":"mc","stem":"마주 보는 두 쌍의 변이 서로 평행하고, 네 각이 모두 직각이며, 이웃한 두 변의 길이가 달라요. 이 사각형의 이름이 될 수 없는 것은 어느 것인가요?","options":[{"t":"마름모","correct":true},{"t":"사다리꼴","mis":"M4-2-u2-X17"},{"t":"평행사변형","mis":"M4-2-u2-X17"},{"t":"직사각형","mis":"M4-2-u2-X18"}],"explanation":["조건을 하나씩 사각형의 뜻과 맞춰 봐요.","평행한 변 → 사다리꼴·평행사변형, 네 변이 같음 → 마름모, 네 각이 직각 → 직사각형.","조건에 맞지 않는 뜻이 있으면 그 이름은 될 수 없어요."],"variant_rule":{"alt":[{"stem":"네 변의 길이가 모두 같고, 한 각의 크기가 120°예요. 이 사각형의 이름이 될 수 없는 것은 어느 것인가요?","options":[{"t":"직사각형","correct":true},{"t":"사다리꼴","mis":"M4-2-u2-X17"},{"t":"평행사변형","mis":"M4-2-u2-X17"},{"t":"마름모","mis":"M4-2-u2-X18"}],"explanation":["조건을 하나씩 사각형의 뜻과 맞춰 봐요.","평행한 변 → 사다리꼴·평행사변형, 네 변이 같음 → 마름모, 네 각이 직각 → 직사각형.","조건에 맞지 않는 뜻이 있으면 그 이름은 될 수 없어요."],"asset":null},{"stem":"마주 보는 두 쌍의 변이 서로 평행하고, 이웃한 두 변의 길이가 다르며, 한 각의 크기가 70°예요. 이 사각형의 이름이 될 수 있는 것은 어느 것인가요?","options":[{"t":"평행사변형","correct":true},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"직사각형","mis":"M4-2-u2-X11"},{"t":"정사각형","mis":"M4-2-u2-X16"}],"explanation":["조건을 하나씩 사각형의 뜻과 맞춰 봐요.","평행한 변 → 사다리꼴·평행사변형, 네 변이 같음 → 마름모, 네 각이 직각 → 직사각형.","조건에 맞지 않는 뜻이 있으면 그 이름은 될 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_challenge#7','math',4,2,'u2','L09','g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C10',3,'mc','auto','크기가 다른 두 원으로 그린 사각형 ㄱㄴㄷㄹ에서 길이가 같은 변끼리 바르게 짝 지은 것은 어느 것인가요?',ARRAY['M4-2-u2-X19','M4-2-u2-X12']::text[],true,'{"seq":7,"concept":"M4-2-u2-C10","difficulty":3,"kind":"mc","stem":"크기가 다른 두 원으로 그린 사각형 ㄱㄴㄷㄹ에서 길이가 같은 변끼리 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"변 ㄱㄴ과 변 ㄱㄹ, 변 ㄴㄷ과 변 ㄷㄹ","correct":true},{"t":"변 ㄱㄴ과 변 ㄴㄷ, 변 ㄷㄹ과 변 ㄱㄹ","mis":"M4-2-u2-X19"},{"t":"네 변의 길이가 모두 같다","mis":"M4-2-u2-X19"},{"t":"변 ㄱㄴ과 변 ㄷㄹ, 변 ㄴㄷ과 변 ㄱㄹ","mis":"M4-2-u2-X12"}],"explanation":["변 ㄱㄴ·ㄱㄹ은 작은 원의 반지름, 변 ㄴㄷ·ㄷㄹ은 큰 원의 반지름이에요.","두 원의 반지름이 다르니 길이가 다른 변이 생겨요.","네 변의 길이가 모두 같지 않아 마름모가 아니에요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[58.50000000000001,68.25,"w"],"ㄴ":[87.75000000000001,29.250000000000004,"n"],"ㄷ":[136.5,68.25,"e"],"ㄹ":[87.75000000000001,107.25,"s"]},"circle":[[[58.50000000000001,68.25],48.7],[[136.5,68.25],62.4]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원과 5 cm인 원을 겹쳐 그려, 두 원의 중심과 만나는 점을 이었어요. 이 사각형은 마름모인가요?","options":[{"t":"아니다 — 3 cm인 변 두 개와 5 cm인 변 두 개가 생긴다","correct":true},{"t":"그렇다 — 두 원을 겹쳐 그렸다","mis":"M4-2-u2-X19"},{"t":"그렇다 — 네 변이 모두 4 cm이다","mis":"M4-2-u2-X13"},{"t":"아니다 — 변이 세 개뿐이다","mis":"M4-2-u2-X18"}],"explanation":["변 ㄱㄴ·ㄱㄹ은 작은 원의 반지름, 변 ㄴㄷ·ㄷㄹ은 큰 원의 반지름이에요.","두 원의 반지름이 다르니 길이가 다른 변이 생겨요.","네 변의 길이가 모두 같지 않아 마름모가 아니에요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[58.50000000000001,68.25,"w"],"ㄴ":[87.75000000000001,29.250000000000004,"n"],"ㄷ":[136.5,68.25,"e"],"ㄹ":[87.75000000000001,107.25,"s"]},"circle":[[[58.50000000000001,68.25],48.7],[[136.5,68.25],62.4]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}},{"stem":"크기가 다른 두 원으로 그린 사각형 ㄱㄴㄷㄹ이 마름모가 아닌 까닭은 무엇인가요?","options":[{"t":"길이가 다른 변이 생겨서","correct":true},{"t":"변이 네 개가 아니어서","mis":"M4-2-u2-X18"},{"t":"네 각이 모두 직각이어서","mis":"M4-2-u2-X14"},{"t":"두 원이 서로 만나서","mis":"M4-2-u2-X19"}],"explanation":["변 ㄱㄴ·ㄱㄹ은 작은 원의 반지름, 변 ㄴㄷ·ㄷㄹ은 큰 원의 반지름이에요.","두 원의 반지름이 다르니 길이가 다른 변이 생겨요.","네 변의 길이가 모두 같지 않아 마름모가 아니에요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[58.50000000000001,68.25,"w"],"ㄴ":[87.75000000000001,29.250000000000004,"n"],"ㄷ":[136.5,68.25,"e"],"ㄹ":[87.75000000000001,107.25,"s"]},"circle":[[[58.50000000000001,68.25],48.7],[[136.5,68.25],62.4]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_challenge#8','math',4,2,'u2','L09','g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C10',4,'sa','auto','크기가 같은 두 원을 서로의 중심을 지나도록 그리고, 두 원의 중심 ㄱ, ㄷ과 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 각 ㄱㄴㄷ의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u2-C10","difficulty":4,"kind":"sa","stem":"크기가 같은 두 원을 서로의 중심을 지나도록 그리고, 두 원의 중심 ㄱ, ㄷ과 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 각 ㄱㄴㄷ의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["한 원이 다른 원의 중심을 지나니 선분 ㄱㄷ도 반지름이에요.","삼각형 ㄱㄴㄷ의 세 변 ㄱㄴ·ㄴㄷ·ㄱㄷ은 모두 반지름이라 길이가 같아요 — 정삼각형.","정삼각형의 세 각은 크기가 같아 180° ÷ 3 = 60°예요."],"asset":{"type":"geo","items":[{"w":180,"h":126.0,"pts":{"ㄱ":[63.0,63.0,"w"],"ㄴ":[90.0,16.23462819564032,"n"],"ㄷ":[117.0,63.0,"e"],"ㄹ":[90.0,109.76537180435969,"s"]},"circle":[[[63.0,63.0],54.0],[[117.0,63.0],54.0]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"크기가 같은 두 원을 서로의 중심을 지나도록 그리고, 두 원의 중심 ㄱ, ㄷ과 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 각 ㄴㄱㄹ의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["한 원이 다른 원의 중심을 지나니 선분 ㄱㄷ도 반지름이에요.","삼각형 ㄱㄴㄷ과 삼각형 ㄱㄹㄷ은 세 변이 모두 반지름인 정삼각형이라 한 각이 60°예요.","각 ㄴㄱㄹ = 각 ㄴㄱㄷ + 각 ㄷㄱㄹ = 60° + 60° = 120°예요."],"asset":{"type":"geo","items":[{"w":180,"h":126.0,"pts":{"ㄱ":[63.0,63.0,"w"],"ㄴ":[90.0,16.23462819564032,"n"],"ㄷ":[117.0,63.0,"e"],"ㄹ":[90.0,109.76537180435969,"s"]},"circle":[[[63.0,63.0],54.0],[[117.0,63.0],54.0]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"]]}],"tag":false}},{"stem":"크기가 같은 두 원을 서로의 중심을 지나도록 그리고, 두 원의 중심 ㄱ, ㄷ과 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 각 ㄴㄷㄹ의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["한 원이 다른 원의 중심을 지나니 선분 ㄱㄷ도 반지름이에요.","삼각형 ㄱㄴㄷ과 삼각형 ㄱㄹㄷ은 세 변이 모두 반지름인 정삼각형이라 한 각이 60°예요.","각 ㄴㄷㄹ = 60° + 60° = 120°예요."],"asset":{"type":"geo","items":[{"w":180,"h":126.0,"pts":{"ㄱ":[63.0,63.0,"w"],"ㄴ":[90.0,16.23462819564032,"n"],"ㄷ":[117.0,63.0,"e"],"ㄹ":[90.0,109.76537180435969,"s"]},"circle":[[[63.0,63.0],54.0],[[117.0,63.0],54.0]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_challenge#9','math',4,2,'u2','L09','g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C10',4,'sa','auto','크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합과 원 한 개의 지름을 더하면 30 cm예요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u2-C10","difficulty":4,"kind":"sa","stem":"크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합과 원 한 개의 지름을 더하면 30 cm예요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["마름모의 네 변 = 반지름 4개, 지름 = 반지름 2개예요.","모두 반지름 6개가 30 cm예요.","30 ÷ 6 = 5 cm예요."],"variant_rule":{"alt":[{"stem":"크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합은 원 한 개의 지름보다 14 cm 더 길어요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["마름모의 네 변 = 반지름 4개, 지름 = 반지름 2개예요.","차이는 반지름 2개 = 14 cm예요.","14 ÷ 2 = 7 cm예요."],"asset":null},{"stem":"크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합과 원 한 개의 지름을 더하면 48 cm예요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["마름모의 네 변 = 반지름 4개, 지름 = 반지름 2개예요.","모두 반지름 6개가 48 cm예요.","48 ÷ 6 = 8 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_L09_challenge#10','math',4,2,'u2','L09','g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C10',4,'essay','teacher','크기가 같은 두 원을 겹쳐 그리고 두 원의 중심과 두 원이 만나는 점을 이으면 마름모가 될 수밖에 없는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u2-C10","difficulty":4,"kind":"essay","stem":"크기가 같은 두 원을 겹쳐 그리고 두 원의 중심과 두 원이 만나는 점을 이으면 마름모가 될 수밖에 없는 까닭을 써 보세요.","answer_guide":{"answer":"예: 두 원이 만나는 점은 두 원 위에 모두 있다. 그래서 한 원의 중심에서 만나는 점까지 이은 두 변은 그 원의 반지름이고, 다른 원의 중심에서 이은 두 변도 그 원의 반지름이다. 두 원의 크기가 같아 반지름이 같으므로 네 변의 길이가 모두 같다. 그래서 마름모가 된다.","scoring_points":["네 변이 모두 원의 반지름이라고 썼는가","두 원의 크기가 같아 반지름이 같다고 썼는가","네 변이 같아 마름모라고 결론지었는가"]},"explanation":["만나는 점은 두 원 위에 모두 있어요.","네 변이 모두 반지름이고, 두 원의 반지름이 같아요.","네 변이 같으니 마름모예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_a#1','math',4,2,'u2','','g4_2_math_u2_review_a','unit_review','M4-2-u2-C1',1,'mc','auto','직선 나와 서로 수직인 직선은 어느 것인가요?',ARRAY['M4-2-u2-X03','M4-2-u2-X05','M4-2-u2-X01']::text[],true,'{"seq":1,"concept":"M4-2-u2-C1","difficulty":1,"kind":"mc","stem":"직선 나와 서로 수직인 직선은 어느 것인가요?","options":[{"t":"직선 가","correct":true},{"t":"직선 다","mis":"M4-2-u2-X03"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"수직인 직선이 없어요","mis":"M4-2-u2-X01"}],"explanation":["모눈을 따라 만나서 이루는 각이 직각인지 살펴봐요.","직선 나와 직선 가가 만나서 이루는 각이 직각이에요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,75.0],[150.0,75.0]],[[30.0,0.0],[30.0,105.0]],[[60.0,105.0],[105.0,0.0]],[[120.0,0.0],[120.0,105.0]]],"lab":[[[13.5,86.25],"가"],[[18.75,13.5],"나"],[[75.65829211852191,97.02313420377185],"다"],[[131.25,13.5],"라"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 직선 나와 서로 수직인 직선은 어느 것인가요?","options":[{"t":"직선 가","correct":true},{"t":"직선 다","mis":"M4-2-u2-X03"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"수직인 직선이 없어요","mis":"M4-2-u2-X01"}],"explanation":["모눈을 따라 만나서 이루는 각이 직각인지 살펴봐요.","직선 나와 직선 가가 만나서 이루는 각이 직각이에요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,30.0],[135.0,75.0]],[[30.0,105.0],[60.0,15.0]],[[75.0,105.0],[135.0,15.0]],[[90.0,105.0],[120.0,15.0]]],"lab":[[[9.249662155992509,44.94176194429559],"가"],[[44.94176194429559,95.75033784400749],"나"],[[78.95223889810475,78.79041572835791],"다"],[[110.05823805570442,9.249662155992509],"라"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 직선 나와 서로 수직인 직선은 어느 것인가요?","options":[{"t":"직선 가","correct":true},{"t":"직선 다","mis":"M4-2-u2-X03"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"수직인 직선이 없어요","mis":"M4-2-u2-X01"}],"explanation":["모눈을 따라 만나서 이루는 각이 직각인지 살펴봐요.","직선 나와 직선 가가 만나서 이루는 각이 직각이에요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[45.0,0.0],[45.0,105.0]],[[0.0,30.0],[150.0,30.0]],[[0.0,90.0],[150.0,45.0]],[[0.0,75.0],[150.0,75.0]]],"lab":[[[33.75,13.5],"가"],[[136.5,18.75],"나"],[[16.16331856310693,96.89634925359229],"다"],[[136.5,86.25],"라"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_a#2','math',4,2,'u2','','g4_2_math_u2_review_a','unit_review','M4-2-u2-C2',1,'mc','auto','두 직선이 만나서 이루는 각이 직각일 때, 두 직선은 서로 어떤 관계라고 하나요?',ARRAY['M4-2-u2-X05','M4-2-u2-X02']::text[],true,'{"seq":2,"concept":"M4-2-u2-C2","difficulty":1,"kind":"mc","stem":"두 직선이 만나서 이루는 각이 직각일 때, 두 직선은 서로 어떤 관계라고 하나요?","options":[{"t":"수직","correct":true},{"t":"평행","mis":"M4-2-u2-X05"},{"t":"수선","mis":"M4-2-u2-X02"},{"t":"평행선","mis":"M4-2-u2-X02"}],"explanation":["두 직선이 만나서 이루는 각이 직각이면 두 직선은 서로 수직이에요.","이때 한 직선을 다른 직선에 대한 수선이라고 해요.","수직은 두 직선의 관계, 수선은 한 직선을 가리키는 말이에요."],"variant_rule":{"alt":[{"stem":"두 직선이 서로 수직일 때, 한 직선을 다른 직선에 대한 무엇이라고 하나요?","options":[{"t":"수선","correct":true},{"t":"수직","mis":"M4-2-u2-X02"},{"t":"평행선","mis":"M4-2-u2-X05"},{"t":"반직선","mis":"M4-2-u2-X02"}],"explanation":["두 직선이 만나서 이루는 각이 직각이면 두 직선은 서로 수직이에요.","이때 한 직선을 다른 직선에 대한 수선이라고 해요.","수직은 두 직선의 관계, 수선은 한 직선을 가리키는 말이에요."],"asset":null},{"stem":"주차장의 주차선 가와 주차선 나가 만나서 이루는 각이 직각이에요. 주차선 나는 주차선 가에 대한 무엇인가요?","options":[{"t":"수선","correct":true},{"t":"수직","mis":"M4-2-u2-X02"},{"t":"평행선","mis":"M4-2-u2-X05"},{"t":"직각","mis":"M4-2-u2-X02"}],"explanation":["두 직선이 만나서 이루는 각이 직각이면 두 직선은 서로 수직이에요.","이때 한 직선을 다른 직선에 대한 수선이라고 해요.","수직은 두 직선의 관계, 수선은 한 직선을 가리키는 말이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_a#3','math',4,2,'u2','','g4_2_math_u2_review_a','unit_review','M4-2-u2-C3',1,'mc','auto','직선 가와 서로 평행한 직선은 어느 것인가요?',ARRAY['M4-2-u2-X05','M4-2-u2-X06']::text[],true,'{"seq":3,"concept":"M4-2-u2-C3","difficulty":1,"kind":"mc","stem":"직선 가와 서로 평행한 직선은 어느 것인가요?","options":[{"t":"직선 다","correct":true},{"t":"직선 나","mis":"M4-2-u2-X05"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"평행한 직선이 없어요","mis":"M4-2-u2-X06"}],"explanation":["끝없이 늘여도 직선 가와 만나지 않는 직선을 찾아요.","모눈을 보면 직선 가와 직선 다는 같은 방향으로 뻗어 만나지 않아요.","그래서 두 직선은 서로 평행해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,15.0],[150.0,15.0]],[[30.0,0.0],[75.0,105.0]],[[0.0,60.0],[150.0,60.0]],[[90.0,0.0],[135.0,105.0]]],"lab":[[[13.5,26.25],"가"],[[80.02247105688438,88.15994998574058],"나"],[[13.5,71.25],"다"],[[140.0224710568844,88.15994998574058],"라"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 직선 가와 서로 평행한 직선은 어느 것인가요?","options":[{"t":"직선 나","correct":true},{"t":"직선 다","mis":"M4-2-u2-X05"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"평행한 직선이 없어요","mis":"M4-2-u2-X06"}],"explanation":["끝없이 늘여도 직선 가와 만나지 않는 직선을 찾아요.","모눈을 보면 직선 가와 직선 나는 같은 방향으로 뻗어 만나지 않아요.","그래서 두 직선은 서로 평행해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,90.0],[135.0,0.0]],[[60.0,105.0],[150.0,45.0]],[[0.0,30.0],[150.0,60.0]],[[90.0,0.0],[120.0,105.0]]],"lab":[[[17.473056181094716,91.87211316226015],"가"],[[64.99230176602705,88.15098153965866],"나"],[[11.031532601522853,43.67910042588833],"다"],[[127.10840918434467,88.9288140180034],"라"]]}],"tag":false}},{"stem":"직선 나와 서로 평행한 직선은 어느 것인가요?","options":[{"t":"직선 다","correct":true},{"t":"직선 가","mis":"M4-2-u2-X01"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"평행한 직선이 없어요","mis":"M4-2-u2-X06"}],"explanation":["끝없이 늘여도 직선 나와 만나지 않는 직선을 찾아요.","모눈을 보면 직선 나와 직