INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_a#5','math',4,2,'u2','','g4_2_math_u2_review_a','unit_review','M4-2-u2-C5',1,'mc','auto','이 사각형은 위아래(또는 마주 보는) 두 변만 서로 평행해요. 이 사각형의 이름으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u2-X10','M4-2-u2-X14']::text[],true,'{"seq":5,"concept":"M4-2-u2-C5","difficulty":1,"kind":"mc","stem":"이 사각형은 위아래(또는 마주 보는) 두 변만 서로 평행해요. 이 사각형의 이름으로 알맞은 것은 어느 것인가요?","options":[{"t":"사다리꼴","correct":true},{"t":"평행사변형","mis":"M4-2-u2-X10"},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"직사각형","mis":"M4-2-u2-X10"}],"explanation":["마주 보는 변을 늘여 만나는지 봐요.","평행한 변이 한 쌍 있어요.","그래서 사다리꼴이에요 — 두 쌍이 아니라 평행사변형은 아니에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[120.0,75.0],[90.0,15.0],[45.0,15.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 사각형은 위아래(또는 마주 보는) 두 변만 서로 평행해요. 이 사각형의 이름으로 알맞은 것은 어느 것인가요?","options":[{"t":"사다리꼴","correct":true},{"t":"평행사변형","mis":"M4-2-u2-X10"},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"직사각형","mis":"M4-2-u2-X10"}],"explanation":["마주 보는 변을 늘여 만나는지 봐요.","평행한 변이 한 쌍 있어요.","그래서 사다리꼴이에요 — 두 쌍이 아니라 평행사변형은 아니에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,45.0],[75.0,15.0],[105.0,60.0],[75.0,75.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 사각형은 위아래(또는 마주 보는) 두 변만 서로 평행해요. 이 사각형의 이름으로 알맞은 것은 어느 것인가요?","options":[{"t":"사다리꼴","correct":true},{"t":"평행사변형","mis":"M4-2-u2-X10"},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"직사각형","mis":"M4-2-u2-X10"}],"explanation":["마주 보는 변을 늘여 만나는지 봐요.","평행한 변이 한 쌍 있어요.","그래서 사다리꼴이에요 — 두 쌍이 아니라 평행사변형은 아니에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[120.0,75.0],[120.0,15.0],[60.0,15.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grad