INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_a#6','math',4,2,'u2','','g4_2_math_u2_review_a','unit_review','M4-2-u2-C7',1,'sa','auto','평행사변형에서 한 각의 크기가 125°일 때, 이 각과 이웃한 각의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u2-C7","difficulty":1,"kind":"sa","stem":"평행사변형에서 한 각의 크기가 125°일 때, 이 각과 이웃한 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","이웃한 각 = 180° − 125°.","55°예요."],"variant_rule":{"alt":[{"stem":"계단 난간에서 찾은 평행사변형의 한 각이 70°예요. 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","이웃한 각 = 180° − 70°.","110°예요."],"asset":null},{"stem":"평행사변형에서 한 각의 크기가 105°일 때, 이 각과 이웃한 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","이웃한 각 = 180° − 105°.","75°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_a#7','math',4,2,'u2','','g4_2_math_u2_review_a','unit_review','M4-2-u2-C8',1,'sa','auto','마름모 ㄱㄴㄷㄹ에서 변 ㄷㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u2-C8","difficulty":1,"kind":"sa","stem":"마름모 ㄱㄴㄷㄹ에서 변 ㄷㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","변 ㄷㄹ도 변 ㄱㄴ과 길이가 같아요.","9 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[60.0,7.5],"ㄴ":[105.0,45.0],"ㄷ":[60.0,82.5],"ㄹ":[15.0,45.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[93.14469744704508,13.476363063545914],"9 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"마름모 ㅁㅂㅅㅇ에서 변 ㅅㅇ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","변 ㅅㅇ도 변 ㅁㅂ과 길이가 같아요.","13 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[15.0,75.0],"ㅂ":[90.0,75.0],"ㅅ":[135.0,15.0],"ㅇ":[60.0,15.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"lab":[[[52.5,86.25],"13 cm"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 마름모 ㄱㄴㄷㄹ에서 변 ㄷㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","변 ㄷㄹ도 변 ㄱㄴ과 길이가 같아요.","7 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,60.0],"ㄴ":[75.0,30.0],"ㄷ":[135.0,60.0],"ㄹ":[75.0,90.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[38.28884705062548,31.577694101250948],"7 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_a#8','math',4,2,'u2','','g4_2_math_u2_review_a','unit_review','M4-2-u2-C10',1,'sa','auto','크기가 같은 두 원을 그리고, 두 원의 중심 ㄱ, ㄷ과 두 원이 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 원의 반지름이 5 cm일 때 변 ㄴㄷ의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u2-C10","difficulty":1,"kind":"sa","stem":"크기가 같은 두 원을 그리고, 두 원의 중심 ㄱ, ㄷ과 두 원이 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 원의 반지름이 5 cm일 때 변 ㄴㄷ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["변 ㄴㄷ은 한 원의 중심과 원 위의 점을 이은 선분이에요.","그래서 변 ㄴㄷ은 원의 반지름이에요.","5 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[126.75000000000001,68.25,"e"],"ㄹ":[97.5,107.25,"s"]},"circle":[[[68.25,68.25],48.7],[[126.75000000000001,68.25],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[43.875,57.0],"5 cm"]],"seg":[[[68.25,68.25],[19.500000000000004,68.25]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"크기가 같은 두 원을 그리고, 두 원의 중심 ㄱ, ㄷ과 두 원이 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 원의 반지름이 6 cm일 때 변 ㄷㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["변 ㄷㄹ은 한 원의 중심과 원 위의 점을 이은 선분이에요.","그래서 변 ㄷㄹ은 원의 반지름이에요.","6 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[126.75000000000001,68.25,"e"],"ㄹ":[97.5,107.25,"s"]},"circle":[[[68.25,68.25],48.7],[[126.75000000000001,68.25],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[43.875,57.0],"6 cm"]],"seg":[[[68.25,68.25],[19.500000000000004,68.25]]]}],"tag":false}},{"stem":"크기가 같은 두 원을 그리고, 두 원의 중심 ㄱ, ㄷ과 두 원이 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 원의 반지름이 4 cm일 때 변 ㄱㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["변 ㄱㄹ은 한 원의 중심과 원 위의 점을 이은 선분이에요.","그래서 변 ㄱㄹ은 원의 반지름이에요.","4 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[126.75000000000001,68.25,"e"],"ㄹ":[97.5,107.25,"s"]},"circle":[[[68.25,68.25],48.7],[[126.75000000000001,68.25],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[43.875,57.0],"4 cm"]],"seg":[[[68.25,68.25],[19.500000000000004,68.25]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
