INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_a#23','math',4,2,'u2','','g4_2_math_u2_review_a','unit_review','M4-2-u2-C7',4,'sa','auto','평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 30 cm예요. 변 ㄴㄷ은 변 ㄱㄴ보다 3 cm 더 길어요. 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-2-u2-C7","difficulty":4,"kind":"sa","stem":"평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 30 cm예요. 변 ㄴㄷ은 변 ㄱㄴ보다 3 cm 더 길어요. 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["변 ㄱㄴ + 변 ㄴㄷ = 30 ÷ 2 = 15 cm예요.","두 변의 차가 3 cm이니 긴 변은 (15 + 3) ÷ 2예요.","변 ㄴㄷ = 9 cm(변 ㄱㄴ = 6 cm)예요."],"variant_rule":{"alt":[{"stem":"평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 44 cm예요. 변 ㄴㄷ은 변 ㄱㄴ보다 6 cm 더 길어요. 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["변 ㄱㄴ + 변 ㄴㄷ = 44 ÷ 2 = 22 cm예요.","두 변의 차가 6 cm이니 긴 변은 (22 + 6) ÷ 2예요.","변 ㄴㄷ = 14 cm(변 ㄱㄴ = 8 cm)예요."],"asset":null},{"stem":"평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 26 cm예요. 변 ㄴㄷ은 변 ㄱㄴ보다 5 cm 더 길어요. 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["변 ㄱㄴ + 변 ㄴㄷ = 26 ÷ 2 = 13 cm예요.","두 변의 차가 5 cm이니 긴 변은 (13 + 5) ÷ 2예요.","변 ㄴㄷ = 9 cm(변 ㄱㄴ = 4 cm)예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_a#24','math',4,2,'u2','','g4_2_math_u2_review_a','unit_review','M4-2-u2-C10',4,'sa','auto','크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합과 원 한 개의 지름을 더하면 30 cm예요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-2-u2-C10","difficulty":4,"kind":"sa","stem":"크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합과 원 한 개의 지름을 더하면 30 cm예요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["마름모의 네 변 = 반지름 4개, 지름 = 반지름 2개예요.","모두 반지름 6개가 30 cm예요.","30 ÷ 6 = 5 cm예요."],"variant_rule":{"alt":[{"stem":"크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합은 원 한 개의 지름보다 14 cm 더 길어요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["마름모의 네 변 = 반지름 4개, 지름 = 반지름 2개예요.","차이는 반지름 2개 = 14 cm예요.","14 ÷ 2 = 7 cm예요."],"asset":null},{"stem":"크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합과 원 한 개의 지름을 더하면 48 cm예요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["마름모의 네 변 = 반지름 4개, 지름 = 반지름 2개예요.","모두 반지름 6개가 48 cm예요.","48 ÷ 6 = 8 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_a#25','math',4,2,'u2','','g4_2_math_u2_review_a','unit_review','M4-2-u2-C3',4,'essay','teacher','직선 가와 직선 나가 서로 평행한지 확인하려고 해요. 삼각자를 써서 확인하는 방법을 쓰고, 그렇게 확인할 수 있는 까닭을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u2-C3","difficulty":4,"kind":"essay","stem":"직선 가와 직선 나가 서로 평행한지 확인하려고 해요. 삼각자를 써서 확인하는 방법을 쓰고, 그렇게 확인할 수 있는 까닭을 써 보세요.","answer_guide":{"answer":"예: 삼각자로 직선 가에 수선을 하나 긋고, 그 수선이 직선 나와도 직각으로 만나는지 삼각자의 직각 부분을 대어 본다. 한 직선에 함께 수직인 두 직선은 아무리 늘여도 만나지 않으므로, 공통의 수선이 있으면 두 직선은 평행하다.","scoring_points":["직선 가에 수선을 긋는다고 썼는가","그 수선이 직선 나와도 직각인지 확인한다고 썼는가","공통의 수선이 있으면 만나지 않아 평행하다는 까닭을 썼는가"]},"explanation":["직선 가에 수선을 그어요.","그 수선이 직선 나와도 직각이면 공통의 수선이에요.","한 직선에 수직인 두 직선은 평행해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_b#1','math',4,2,'u2','','g4_2_math_u2_review_b','unit_review','M4-2-u2-C1',1,'mc','auto','직선 나와 서로 수직인 직선은 어느 것인가요?',ARRAY['M4-2-u2-X03','M4-2-u2-X05','M4-2-u2-X01']::text[],true,'{"seq":1,"concept":"M4-2-u2-C1","difficulty":1,"kind":"mc","stem":"직선 나와 서로 수직인 직선은 어느 것인가요?","options":[{"t":"직선 가","correct":true},{"t":"직선 다","mis":"M4-2-u2-X03"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"수직인 직선이 없어요","mis":"M4-2-u2-X01"}],"explanation":["모눈을 따라 만나서 이루는 각이 직각인지 살펴봐요.","직선 나와 직선 가가 만나서 이루는 각이 직각이에요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,30.0],[135.0,75.0]],[[30.0,105.0],[60.0,15.0]],[[75.0,105.0],[135.0,15.0]],[[90.0,105.0],[120.0,15.0]]],"lab":[[[9.249662155992509,44.94176194429559],"가"],[[44.94176194429559,95.75033784400749],"나"],[[78.95223889810475,78.79041572835791],"다"],[[110.05823805570442,9.249662155992509],"라"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 직선 나와 서로 수직인 직선은 어느 것인가요?","options":[{"t":"직선 가","correct":true},{"t":"직선 다","mis":"M4-2-u2-X03"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"수직인 직선이 없어요","mis":"M4-2-u2-X01"}],"explanation":["모눈을 따라 만나서 이루는 각이 직각인지 살펴봐요.","직선 나와 직선 가가 만나서 이루는 각이 직각이에요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[45.0,0.0],[45.0,105.0]],[[0.0,30.0],[150.0,30.0]],[[0.0,90.0],[150.0,45.0]],[[0.0,75.0],[150.0,75.0]]],"lab":[[[33.75,13.5],"가"],[[136.5,18.75],"나"],[[16.16331856310693,96.89634925359229],"다"],[[136.5,86.25],"라"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 직선 나와 서로 수직인 직선은 어느 것인가요?","options":[{"t":"직선 가","correct":true},{"t":"직선 다","mis":"M4-2-u2-X03"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"수직인 직선이 없어요","mis":"M4-2-u2-X01"}],"explanation":["모눈을 따라 만나서 이루는 각이 직각인지 살펴봐요.","직선 나와 직선 가가 만나서 이루는 각이 직각이에요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,15.0],[150.0,90.0]],[[15.0,105.0],[60.0,15.0]],[[90.0,105.0],[120.0,0.0]],[[105.0,105.0],[150.0,15.0]]],"lab":[[[7.043614129124338,31.099689437998485],"가"],[[31.099689437998485,97.95638587087565],"나"],[[82.89159081565535,88.9288140180034],"다"],[[121.09968943799848,97.95638587087565],"라"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_b#2','math',4,2,'u2','','g4_2_math_u2_review_b','unit_review','M4-2-u2-C2',1,'mc','auto','두 직선이 서로 수직일 때, 한 직선을 다른 직선에 대한 무엇이라고 하나요?',ARRAY['M4-2-u2-X02','M4-2-u2-X05']::text[],true,'{"seq":2,"concept":"M4-2-u2-C2","difficulty":1,"kind":"mc","stem":"두 직선이 서로 수직일 때, 한 직선을 다른 직선에 대한 무엇이라고 하나요?","options":[{"t":"수선","correct":true},{"t":"수직","mis":"M4-2-u2-X02"},{"t":"평행선","mis":"M4-2-u2-X05"},{"t":"반직선","mis":"M4-2-u2-X02"}],"explanation":["두 직선이 만나서 이루는 각이 직각이면 두 직선은 서로 수직이에요.","이때 한 직선을 다른 직선에 대한 수선이라고 해요.","수직은 두 직선의 관계, 수선은 한 직선을 가리키는 말이에요."],"variant_rule":{"alt":[{"stem":"주차장의 주차선 가와 주차선 나가 만나서 이루는 각이 직각이에요. 주차선 나는 주차선 가에 대한 무엇인가요?","options":[{"t":"수선","correct":true},{"t":"수직","mis":"M4-2-u2-X02"},{"t":"평행선","mis":"M4-2-u2-X05"},{"t":"직각","mis":"M4-2-u2-X02"}],"explanation":["두 직선이 만나서 이루는 각이 직각이면 두 직선은 서로 수직이에요.","이때 한 직선을 다른 직선에 대한 수선이라고 해요.","수직은 두 직선의 관계, 수선은 한 직선을 가리키는 말이에요."],"asset":null},{"stem":"두 직선이 만나서 이루는 각이 직각일 때, 두 직선은 서로 어떤 관계라고 하나요?","options":[{"t":"수직","correct":true},{"t":"평행","mis":"M4-2-u2-X05"},{"t":"수선","mis":"M4-2-u2-X02"},{"t":"평행선","mis":"M4-2-u2-X02"}],"explanation":["두 직선이 만나서 이루는 각이 직각이면 두 직선은 서로 수직이에요.","이때 한 직선을 다른 직선에 대한 수선이라고 해요.","수직은 두 직선의 관계, 수선은 한 직선을 가리키는 말이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_b#3','math',4,2,'u2','','g4_2_math_u2_review_b','unit_review','M4-2-u2-C3',1,'mc','auto','직선 가와 서로 평행한 직선은 어느 것인가요?',ARRAY['M4-2-u2-X05','M4-2-u2-X06']::text[],true,'{"seq":3,"concept":"M4-2-u2-C3","difficulty":1,"kind":"mc","stem":"직선 가와 서로 평행한 직선은 어느 것인가요?","options":[{"t":"직선 나","correct":true},{"t":"직선 다","mis":"M4-2-u2-X05"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"평행한 직선이 없어요","mis":"M4-2-u2-X06"}],"explanation":["끝없이 늘여도 직선 가와 만나지 않는 직선을 찾아요.","모눈을 보면 직선 가와 직선 나는 같은 방향으로 뻗어 만나지 않아요.","그래서 두 직선은 서로 평행해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,90.0],[135.0,0.0]],[[60.0,105.0],[150.0,45.0]],[[0.0,30.0],[150.0,60.0]],[[90.0,0.0],[120.0,105.0]]],"lab":[[[17.473056181094716,91.87211316226015],"가"],[[64.99230176602705,88.15098153965866],"나"],[[11.031532601522853,43.67910042588833],"다"],[[127.10840918434467,88.9288140180034],"라"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직선 나와 서로 평행한 직선은 어느 것인가요?","options":[{"t":"직선 다","correct":true},{"t":"직선 가","mis":"M4-2-u2-X01"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"평행한 직선이 없어요","mis":"M4-2-u2-X06"}],"explanation":["끝없이 늘여도 직선 나와 만나지 않는 직선을 찾아요.","모눈을 보면 직선 나와 직선 다는 같은 방향으로 뻗어 만나지 않아요.","그래서 두 직선은 서로 평행해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,30.0],[135.0,75.0]],[[30.0,105.0],[60.0,15.0]],[[90.0,105.0],[120.0,15.0]],[[0.0,90.0],[150.0,90.0]]],"lab":[[[9.249662155992509,44.94176194429559],"가"],[[50.05823805570442,9.249662155992509],"나"],[[110.05823805570442,9.249662155992509],"다"],[[13.5,78.75],"라"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 직선 가와 서로 평행한 직선은 어느 것인가요?","options":[{"t":"직선 다","correct":true},{"t":"직선 나","mis":"M4-2-u2-X05"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"평행한 직선이 없어요","mis":"M4-2-u2-X06"}],"explanation":["끝없이 늘여도 직선 가와 만나지 