INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_b#4','math',4,2,'u2','','g4_2_math_u2_review_b','unit_review','M4-2-u2-C4',1,'sa','auto','두 직선은 서로 평행해요. 점 ㅁ에서 아래 직선에 그은 세 선분 가운데 하나는 아래 직선에 수직이에요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u2-C4","difficulty":1,"kind":"sa","stem":"두 직선은 서로 평행해요. 점 ㅁ에서 아래 직선에 그은 세 선분 가운데 하나는 아래 직선에 수직이에요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["수직인 선분이 세 선분 가운데 가장 짧아요.","세 길이 4 cm, 6 cm, 5 cm 가운데 가장 짧은 것은 4 cm예요.","평행선 사이의 거리는 4 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"pts":{"ㅁ":[52.5,22.5],"ㅂ":[52.5,82.5],"ㅅ":[112.5,82.5],"ㅇ":[7.5,82.5]},"seg":[["ㅁ","ㅂ"],["ㅁ","ㅅ"],["ㅁ","ㅇ"]],"lab":[[[71.25,43.5],"4 cm"],[[112.94999999999999,67.5],"6 cm"],[[2.849999999999999,67.5],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"두 직선은 서로 평행해요. 점 ㄱ에서 아래 직선에 그은 세 선분 가운데 하나는 아래 직선에 수직이에요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["수직인 선분이 세 선분 가운데 가장 짧아요.","세 길이 5 cm, 6 cm, 4 cm 가운데 가장 짧은 것은 4 cm예요.","평행선 사이의 거리는 4 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"pts":{"ㄱ":[90.0,22.5],"ㄷ":[135.0,82.5],"ㄹ":[30.0,82.5],"ㅁ":[90.0,82.5]},"seg":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"]],"lab":[[[139.65,67.5],"5 cm"],[[29.550000000000004,67.5],"6 cm"],[[108.75,43.5],"4 cm"]]}],"tag":false}},{"stem":"두 직선은 서로 평행해요. 점 ㄱ에서 아래 직선에 그은 세 선분 가운데 하나는 아래 직선에 수직이에요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["수직인 선분이 세 선분 가운데 가장 짧아요.","세 길이 5 cm, 4 cm, 6 cm 가운데 가장 짧은 것은 4 cm예요.","평행선 사이의 거리는 4 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"pts":{"ㄱ":[67.5,22.5],"ㄴ":[22.5,82.5],"ㄷ":[67.5,82.5],"ㄹ":[135.0,82.5]