INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_b#6','math',4,2,'u2','','g4_2_math_u2_review_b','unit_review','M4-2-u2-C7',1,'sa','auto','계단 난간에서 찾은 평행사변형의 한 각이 70°예요. 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u2-C7","difficulty":1,"kind":"sa","stem":"계단 난간에서 찾은 평행사변형의 한 각이 70°예요. 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","이웃한 각 = 180° − 70°.","110°예요."],"variant_rule":{"alt":[{"stem":"평행사변형에서 한 각의 크기가 105°일 때, 이 각과 이웃한 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","이웃한 각 = 180° − 105°.","75°예요."],"asset":null},{"stem":"계단 난간에서 찾은 평행사변형의 한 각이 40°예요. 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["140"],"explanation":["평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","이웃한 각 = 180° − 40°.","140°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
