INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_b#8','math',4,2,'u2','','g4_2_math_u2_review_b','unit_review','M4-2-u2-C10',1,'sa','auto','크기가 같은 두 원을 그리고, 두 원의 중심 ㄱ, ㄷ과 두 원이 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 원의 반지름이 6 cm일 때 변 ㄷㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u2-C10","difficulty":1,"kind":"sa","stem":"크기가 같은 두 원을 그리고, 두 원의 중심 ㄱ, ㄷ과 두 원이 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 원의 반지름이 6 cm일 때 변 ㄷㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["변 ㄷㄹ은 한 원의 중심과 원 위의 점을 이은 선분이에요.","그래서 변 ㄷㄹ은 원의 반지름이에요.","6 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[126.75000000000001,68.25,"e"],"ㄹ":[97.5,107.25,"s"]},"circle":[[[68.25,68.25],48.7],[[126.75000000000001,68.25],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[43.875,57.0],"6 cm"]],"seg":[[[68.25,68.25],[19.500000000000004,68.25]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"크기가 같은 두 원을 그리고, 두 원의 중심 ㄱ, ㄷ과 두 원이 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 원의 반지름이 4 cm일 때 변 ㄱㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["변 ㄱㄹ은 한 원의 중심과 원 위의 점을 이은 선분이에요.","그래서 변 ㄱㄹ은 원의 반지름이에요.","4 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[126.75000000000001,68.25,"e"],"ㄹ":[97.5,107.25,"s"]},"circle":[[[68.25,68.25],48.7],[[126.75000000000001,68.25],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[43.875,57.0],"4 cm"]],"seg":[[[68.25,68.25],[19.500000000000004,68.25]]]}],"tag":false}},{"stem":"크기가 같은 두 원을 그리고, 두 원의 중심 ㄱ, ㄷ과 두 원이 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 원의 반지름이 8 cm일 때 변 ㄱㄴ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["변 ㄱㄴ은 한 원의 중심과 원 위의 점을 이은 선분이에요.","그래서 변 ㄱㄴ은 원의 반지름이에요.","8 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[1