INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_b#9','math',4,2,'u2','','g4_2_math_u2_review_b','unit_review','M4-2-u2-C1',2,'mc','auto','사각형 ㄱㄴㄷㄹ에서 변 ㄴㄷ과 수직인 변을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X04','M4-2-u2-X06','M4-2-u2-X03']::text[],true,'{"seq":9,"concept":"M4-2-u2-C1","difficulty":2,"kind":"mc","stem":"사각형 ㄱㄴㄷㄹ에서 변 ㄴㄷ과 수직인 변을 모두 고른 것은 어느 것인가요?","options":[{"t":"변 ㄱㄴ, 변 ㄷㄹ","correct":true},{"t":"변 ㄱㄴ","mis":"M4-2-u2-X04"},{"t":"변 ㄹㄱ","mis":"M4-2-u2-X06"},{"t":"변 ㄱㄴ, 변 ㄷㄹ, 변 ㄹㄱ","mis":"M4-2-u2-X03"}],"explanation":["변 ㄴㄷ과 만나서 이루는 각이 직각인 변을 찾아요.","변 ㄱㄴ, 변 ㄷㄹ — 모눈으로 보면 직각으로 만나요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[120.0,75.0],"ㄷ":[120.0,15.0],"ㄹ":[60.0,15.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"사각형 ㅁㅂㅅㅇ에서 변 ㅅㅇ과 수직인 변을 모두 고른 것은 어느 것인가요?","options":[{"t":"변 ㅂㅅ, 변 ㅇㅁ","correct":true},{"t":"변 ㅂㅅ","mis":"M4-2-u2-X04"},{"t":"변 ㅁㅂ","mis":"M4-2-u2-X06"},{"t":"변 ㅁㅂ, 변 ㅂㅅ, 변 ㅇㅁ","mis":"M4-2-u2-X03"}],"explanation":["변 ㅅㅇ과 만나서 이루는 각이 직각인 변을 찾아요.","변 ㅂㅅ, 변 ㅇㅁ — 모눈으로 보면 직각으로 만나요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[45.0,7.5],"ㅂ":[90.0,37.5],"ㅅ":[60.0,82.5],"ㅇ":[15.0,52.5]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]]}],"tag":false}},{"stem":"사각형 ㅁㅂㅅㅇ에서 변 ㅇㅁ과 수직인 변을 모두 고른 것은 어느 것인가요?","options":[{"t":"변 ㅁㅂ, 변 ㅅㅇ","correct":true},{"t":"변 ㅁㅂ","mis":"M4-2-u2-X04"},{"t":"변 ㅂㅅ","mis":"M4-2-u2-X06"},{"t":"변 ㅁㅂ, 변 ㅂㅅ, 변 ㅅㅇ","mis":"M4-2-u2-X03"}],"explanation":["변 ㅇㅁ과 만나서 이루는 각이 직각인 변을 찾아요.","변 ㅁㅂ, 변 ㅅㅇ — 모눈으로 보면 직각으로 만나요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[15.0,45.0],"ㅂ":[75.0,15.0],"ㅅ":[90.0,45.0],"ㅇ":[30.0,75.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) D