INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_b#17','math',4,2,'u2','','g4_2_math_u2_review_b','unit_review','M4-2-u2-C2',3,'sa','auto','주차선 두 줄이 수직으로 만나는 점 ㅇ에서 비스듬한 안내선을 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M4-2-u2-C2","difficulty":3,"kind":"sa","stem":"주차선 두 줄이 수직으로 만나는 점 ㅇ에서 비스듬한 안내선을 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["두 직선이 수직이라 만나서 이루는 각은 90°예요.","90°가 65°와 ㉠으로 나뉘었어요.","㉠ = 90° − 65° = 25°예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"line":[[[30.0,90.0],[120.0,90.0]]],"ray":[[[30.0,90.0],[30.0,7.5]],[[30.0,90.0],[102.0,54.0]]],"right":[[[75.0,90.0],[30.0,90.0],[30.0,45.0]]],"lab":[[[78.17533378216905,78.62514989212599],"㉠"],[[56.02187155703885,47.891661150444655],"65°"]],"pts":{"ㅇ":[30.0,90.0]},"show":["ㅇ"]}],"tag":false},"variant_rule":{"alt":[{"stem":"점 ㅇ에서 수직인 두 직선 사이에 반직선을 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["두 직선이 수직이라 만나서 이루는 각은 90°예요.","90°가 65°와 ㉠으로 나뉘었어요.","㉠ = 90° − 65° = 25°예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"line":[[[30.0,90.0],[120.0,90.0]]],"ray":[[[30.0,90.0],[30.0,7.5]],[[30.0,90.0],[66.0,18.000000000000004]]],"right":[[[75.0,90.0],[30.0,90.0],[30.0,45.0]]],"lab":[[[72.10833884955535,63.97812844296115],"65°"],[[41.37485010787402,41.82466621783095],"㉠"]],"pts":{"ㅇ":[30.0,90.0]},"show":["ㅇ"]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 주차선 두 줄이 수직으로 만나는 점 ㅇ에서 비스듬한 안내선을 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["두 직선이 수직이라 만나서 이루는 각은 90°예요.","90°가 35°와 ㉠으로 나뉘었어요.","㉠ = 90° − 35° = 55°예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"line":[[[30.0,90.0],[120.0,90.0]]],"ray":[[[30.0,90.0],[30.0,7.5]],[[30.0,90.0],[102.0,-17.99999999999999]]],"right":[[[75.0,90.0],[30.0,90.0],[30.0,45.0]]],"lab":[[[73.6428788753208,66.6430069684885],"㉠"],[[44.34428744253374,42.62393623604881],"35°"]],"pts":{"ㅇ":[30.0,90.0]},"show":["ㅇ"]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_b#18','math',4,2,'u2','','g4_2_math_u2_review_b','unit_review','M4-2-u2-C4',3,'sa','auto','평행사변형 ㄱㄴㄷㄹ에서 위아래 두 변은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-2-u2-C4","difficulty":3,"kind":"sa","stem":"평행사변형 ㄱㄴㄷㄹ에서 위아래 두 변은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["평행한 두 변 사이의 거리는 두 변에 수직인 선분의 길이예요.","비스듬한 변(5 cm)이나 평행한 변(6 cm)의 길이가 아니에요.","점선으로 그은 수직인 선분이 4 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[120.0,15.0],"ㄹ":[45.0,15.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[13.217694101250945,36.60884705062547],"5 cm"],[[52.5,86.25],"6 cm"],[[62.25000000000001,45.0],"4 cm"]],"dash":[[[45.0,15.0],[45.0,75.0]]],"right":[[[45.0,15.0],[45.0,75.0],[15.0,75.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"사다리꼴 ㅁㅂㅅㅇ에서 위아래 두 변은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["평행한 두 변 사이의 거리는 두 변에 수직인 선분의 길이예요.","비스듬한 변(6 cm)이나 평행한 변(7 cm)의 길이가 아니에요.","점선으로 그은 수직인 선분이 4 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[30.0,15.0],"ㅂ":[75.0,15.0],"ㅅ":[120.0,75.0],"ㅇ":[15.0,75.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"lab":[[[3.680014520423841,40.29500363010596],"6 cm"],[[67.5,86.25],"7 cm"],[[47.25,45.0],"4 cm"]],"dash":[[[30.0,15.0],[30.0,75.0]]],"right":[[[30.0,15.0],[30.0,75.0],[120.0,75.0]]]}],"tag":false}},{"stem":"사다리꼴 ㅁㅂㅅㅇ에서 위아래 두 변은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["평행한 두 변 사이의 거리는 두 변에 수직인 선분의 길이예요.","비스듬한 변(5 cm)이나 평행한 변(9 cm)의 길이가 아니에요.","점선으로 그은 수직인 선분이 4 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[15.0,75.0],"ㅂ":[120.0,75.0],"ㅅ":[90.0,15.0],"ㅇ":[45.0,15.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"lab":[[[13.217694101250945