INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_b#22','math',4,2,'u2','','g4_2_math_u2_review_b','unit_review','M4-2-u2-C9',3,'sa','auto','횡단보도 앞에 똑같은 정사각형 보도블록을 가로 4장, 세로 2장 깔았어요. 그림에서 찾을 수 있는 크고 작은 정사각형은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M4-2-u2-C9","difficulty":3,"kind":"sa","stem":"횡단보도 앞에 똑같은 정사각형 보도블록을 가로 4장, 세로 2장 깔았어요. 그림에서 찾을 수 있는 크고 작은 정사각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["작은 정사각형부터 크기별로 차례로 세요.","1칸짜리 8개 · 4칸짜리 3개.","모두 11개예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"seg":[[[15.0,15.0],[105.0,15.0]],[[15.0,37.5],[105.0,37.5]],[[15.0,60.0],[105.0,60.0]],[[15.0,15.0],[15.0,60.0]],[[37.5,15.0],[37.5,60.0]],[[60.0,15.0],[60.0,60.0]],[[82.5,15.0],[82.5,60.0]],[[105.0,15.0],[105.0,60.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"횡단보도 앞에 똑같은 정사각형 보도블록을 가로 3장, 세로 3장 깔았어요. 그림에서 찾을 수 있는 크고 작은 정사각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["작은 정사각형부터 크기별로 차례로 세요.","1칸짜리 9개 · 4칸짜리 4개 · 9칸짜리 1개.","모두 14개예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"seg":[[[15.0,15.0],[82.5,15.0]],[[15.0,37.5],[82.5,37.5]],[[15.0,60.0],[82.5,60.0]],[[15.0,82.5],[82.5,82.5]],[[15.0,15.0],[15.0,82.5]],[[37.5,15.0],[37.5,82.5]],[[60.0,15.0],[60.0,82.5]],[[82.5,15.0],[82.5,82.5]]]}],"tag":false}},{"stem":"횡단보도 앞에 똑같은 정사각형 보도블록을 가로 4장, 세로 3장 깔았어요. 그림에서 찾을 수 있는 크고 작은 정사각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["작은 정사각형부터 크기별로 차례로 세요.","1칸짜리 12개 · 4칸짜리 6개 · 9칸짜리 2개.","모두 20개예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"seg":[[[15.0,15.0],[105.0,15.0]],[[15.0,37.5],[105.0,37.5]],[[15.0,60.0],[105.0,60.0]],[[15.0,82.5],[105.0,82.5]],[[15.0,15.0],[15.0,82.5]],[[37.5,15.0],[37.5,82.5]],[[60.0,15.0],[60.0,82.5]],[[82.5,15.0],[82.5,82.5]],[[105.0,15.0],[105.0,82.5]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_b#23','math',4,2,'u2','','g4_2_math_u2_review_b','unit_review','M4-2-u2-C7',4,'sa','auto','평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 44 cm예요. 변 ㄴㄷ은 변 ㄱㄴ보다 6 cm 더 길어요. 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-2-u2-C7","difficulty":4,"kind":"sa","stem":"평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 44 cm예요. 변 ㄴㄷ은 변 ㄱㄴ보다 6 cm 더 길어요. 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["변 ㄱㄴ + 변 ㄴㄷ = 44 ÷ 2 = 22 cm예요.","두 변의 차가 6 cm이니 긴 변은 (22 + 6) ÷ 2예요.","변 ㄴㄷ = 14 cm(변 ㄱㄴ = 8 cm)예요."],"variant_rule":{"alt":[{"stem":"평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 26 cm예요. 변 ㄴㄷ은 변 ㄱㄴ보다 5 cm 더 길어요. 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["변 ㄱㄴ + 변 ㄴㄷ = 26 ÷ 2 = 13 cm예요.","두 변의 차가 5 cm이니 긴 변은 (13 + 5) ÷ 2예요.","변 ㄴㄷ = 9 cm(변 ㄱㄴ = 4 cm)예요."],"asset":null},{"stem":"평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 30 cm예요. 변 ㄴㄷ은 변 ㄱㄴ보다 3 cm 더 길어요. 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["변 ㄱㄴ + 변 ㄴㄷ = 30 ÷ 2 = 15 cm예요.","두 변의 차가 3 cm이니 긴 변은 (15 + 3) ÷ 2예요.","변 ㄴㄷ = 9 cm(변 ㄱㄴ = 6 cm)예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_b#24','math',4,2,'u2','','g4_2_math_u2_review_b','unit_review','M4-2-u2-C10',4,'sa','auto','크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합은 원 한 개의 지름보다 14 cm 더 길어요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-2-u2-C10","difficulty":4,"kind":"sa","stem":"크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합은 원 한 개의 지름보다 14 cm 더 길어요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["마름모의 네 변 = 반지름 4개, 지름 = 반지름 2개예요.","차이는 반지름 2개 = 14 cm예요.","14 ÷ 2 = 7 cm예요."],"variant_rule":{"alt":[{"stem":"크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합과 원 한 개의 지름을 더하면 48 cm예요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["마름모의 네 변 = 반지름 4개, 지름 = 반지름 2개예요.","모두 반지름 6개가 48 cm예요.","48 ÷ 6 = 8 cm예요."],"asset":null},{"stem":"크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합은 원 한 개의 지름보다 12 cm 더 길어요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["마름모의 네 변 = 반지름 4개, 지름 = 반지름 2개예요.","차이는 반지름 2개 = 12 cm예요.","12 ÷ 2 = 6 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_b#25','math',4,2,'u2','','g4_2_math_u2_review_b','unit_review','M4-2-u2-C9',4,'essay','teacher','직사각형은 사다리꼴이라고 할 수 있는지, 평행사변형이라고 할 수 있는지 각각 판단하고 까닭을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u2-C9","difficulty":4,"kind":"essay","stem":"직사각형은 사다리꼴이라고 할 수 있는지, 평행사변형이라고 할 수 있는지 각각 판단하고 까닭을 써 보세요.","answer_guide":{"answer":"예: 둘 다 할 수 있다. 직사각형은 마주 보는 두 쌍의 변이 서로 평행하다. 평행한 변이 한 쌍이라도 있으므로 사다리꼴이고, 마주 보는 두 쌍의 변이 평행하므로 평행사변형이다.","scoring_points":["사다리꼴이라고 판단하고 까닭(평행한 변이 한 쌍이라도)을 썼는가","평행사변형이라고 판단하고 까닭(두 쌍이 평행)을 썼는가","기울어지지 않아도 된다는 생각이 드러났는가"]},"explanation":["직사각형은 마주 보는 두 쌍의 변이 평행해요.","한 쌍이라도 있으니 사다리꼴, 두 쌍이니 평행사변형.","모양이 아니라 뜻으로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_c#1','math',4,2,'u2','','g4_2_math_u2_review_c','unit_review','M4-2-u2-C1',1,'mc','auto','직선 나와 서로 수직인 직선은 어느 것인가요?',ARRAY['M4-2-u2-X03','M4-2-u2-X05','M4-2-u2-X01']::text[],true,'{"seq":1,"concept":"M4-2-u2-C1","difficulty":1,"kind":"mc","stem":"직선 나와 서로 수직인 직선은 어느 것인가요?","options":[{"t":"직선 가","correct":true},{"t":"직선 다","mis":"M4-2-u2-X03"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"수직인 직선이 없어요","mis":"M4-2-u2-X01"}],"explanation":["모눈을 따라 만나서 이루는 각이 직각인지 살펴봐요.","직선 나와 직선 가가 만나서 이루는 각이 직각이에요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[45.0,0.0],[45.0,105.0]],[[0.0,30.0],[150.0,30.0]],[[0.0,90.0],[150.0,45.0]],[[0.0,75.0],[150.0,75.0]]],"lab":[[[33.75,13.5],"가"],[[136.5,18.75],"나"],[[16.16331856310693,96.89634925359229],"다"],[[136.5,86.25],"라"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 직선 나와 서로 수직인 직선은 어느 것인가요?","options":[{"t":"직선 가","correct":true},{"t":"직선 다","mis":"M4-2-u2-X03"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"수직인 직선이 없어요","mis":"M4-2-u2-X01"}],"explanation":["모눈을 따라 만나서 이루는 각이 직각인지 살펴봐요.","직선 나와 직선 가가 만나서 이루는 각이 직각이에요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,15.0],[150.0,90.0]],[[15.0,105.0],[60.0,15.0]],[[90.0,105.0],[120.0,0.0]],[[105.0,105.0],[150.0,15.0]]],"lab":[[[7.043614129124338,31.099689437998485],"가"],[[31.099689437998485,97.95638587087565],"나"],[[82.89159081565535,88.9288140180034],"다"],[[121.09968943799848,97.95638587087565],"라"]]}],"tag":false}},{"stem":"직선 가와 서로 수직인 직선은 어느 것인가요?","options":[{"t":"직선 나","correct":true},{"t":"직선 다","mis":"M4-2-u2-X03"},{"t":"직선 라","mis":"M4-2-u2-X03"},{"t":"수직인 직선이 없어요","mis":"M4-2-u2-X01"}],"explanation":["모눈을 따라 만나서 이루는 각이 직각인지 살펴봐요.","직선 가와 직선 나가 만나서 이루는 각이 직각이에요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,105.0],[105.0,0.0]],[[15.0,0.0],[120.0,105.0]],[[150.0,30.0],[60.0,105.0]],[[0.0,45.0],[150.0,45.0]]],"lab":[[[103.40900974233026,17.500892834367054],"가"],[[16.59099025766973,17.500892834367054],"나"],[[63.16891277833918,87.71502120905905],"다"],[[13.5,56.25],"라"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_c#2','math',4,2,'u2','','g4_2_math_u2_review_c','unit_review','M4-2-u2-C2',1,'mc','auto','주차장의 주차선 가와 주차선 나가 만나서 이루는 각이 직각이에요. 주차선 나는 주차선 가에 대한 무엇인가요?',ARRAY['M4-2-u2-X02','M4-2-u2-X05']::text[],true,'{"seq":2,"concept":"M4-2-u2-C2","difficulty":1,"kind":"mc","stem":"주차장의 주차선 가와 주차선 나가 만나서 이루는 각이 직각이에요. 주차선 나는 주차선 가에 대한 무엇인가요?","options":[{"t":"수선","correct":true},{"t":"수직","mis":"M4-2-u2-X02"},{"t":"평행선","mis":"M4-2-u2-X05"},{"t":"직각","mis":"M4-2-u2-X02"}],"explanation":["두 직선이 만나서 이루는 각이 직각이면 두 직선은 서로 수직이에요.","이때 한 직선을 다른 직선에 대한 수선이라고 해요.","수직은 두 직선의 관계, 수선은 한 직선을 가리키는 말이에요."],"variant_rule":{"alt":[{"stem":"두 직선이 만나서 이루는 각이 직각일 때, 두 직선은 서로 어떤 관계라고 하나요?","options":[{"t":"수직","correct":true},{"t":"평행","mis":"M4-2-u2-X05"},{"t":"수선","mis":"M4-2-u2-X02"},{"t":"평행선","mis":"M4-2-u2-X02"}],"explanation":["두 직선이 만나서 이루는 각이 직각이면 두 직선은 서로 수직이에요.","이때 한 직선을 다른 직선에 대한 수선이라고 해요.","수직은 두 직선의 관계, 수선은 한 직선을 가리키는 말이에요."],"asset":null},{"stem":"두 직선이 서로 수직일 때, 한 직선을 다른 직선에 대한 무엇이라고 하나요?","options":[{"t":"수선","correct":true},{"t":"수직","mis":"M4-2-u2-X02"},{"t":"평행선","mis":"M4-2-u2-X05"},{"t":"반직선","mis":"M4-2-u2-X02"}],"explanation":["두 직선이 만나서 이루는 각이 직각이면 두 직선은 서로 수직이에요.","이때 한 직선을 다른 직선에 대한 수선이라고 해요.","수직은 두 직선의 관계, 수선은 한 직선을 가리키는 말이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_c#3','math',4,2,'u2','','g4_2_math_u2_review_c','unit_review','M4-2-u2-C3',1,'mc','auto','직선 나와 서로 평행한 직선은 어느 것인가요?',ARRAY['M4-2-u2-X01','M4-2-u2-X05','M4-2-u2-X06']::text[],true,'{"seq":3,"concept":"M4-2-u2-C3","difficulty":1,"kind":"mc","stem":"직선 나와 서로 평행한 직선은 어느 것인가요?","options":[{"t":"직선 다","correct":true},{"t":"직선 가","mis":"M4-2-u2-X01"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"평행한 직선이 없어요","mis":"M4-2-u2-X06"}],"explanation":["끝없이 늘여도 직선 나와 만나지 않는 직선을 찾아요.","모눈을 보면 직선 나와 직선 다는 같은 방향으로 뻗어 만나지 않아요.","그래서 두 직선은 서로 평행해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,30.0],[135.0,75.0]],[[30.0,105.0],[60.0,15.0]],[[90.0,105.0],[120.0,15.0]],[[0.0,90.0],[150.0,90.0]]],"lab":[[[9.249662155992509,44.94176194429559],"가"],[[50.05823805570442,9.249662155992509],"나"],[[110.05823805570442,9.249662155992509],"다"],[[13.5,78.75],"라"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직선 가와 서로 평행한 직선은 어느 것인가요?","options":[{"t":"직선 다","correct":true},{"t":"직선 나","mis":"M4-2-u2-X05"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"평행한 직선이 없어요","mis":"M4-2-u2-X06"}],"explanation":["끝없이 늘여도 직선 가와 만나지 않는 직선을 찾아요.","모눈을 보면 직선 가와 직선 다는 같은 방향으로 뻗어 만나지 않아요.","그래서 두 직선은 서로 평행해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,15.0],[150.0,15.0]],[[30.0,0.0],[75.0,105.0]],[[0.0,60.0],[150.0,60.0]],[[90.0,0.0],[135.0,105.0]]],"lab":[[[13.5,26.25],"가"],[[80.02247105688438,88.15994998574058],"나"],[[13.5,71.25],"다"],[[140.0224710568844,88.15994998574058],"라"]]}],"tag":false}},{"stem":"직선 가와 서로 평행한 직선은 어느 것인가요?","options":[{"t":"직선 나","correct":true},{"t":"직선 다","mis":"M4-2-u2-X05"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"평행한 직선이 없어요","mis":"M4-2-u2-X06"}],"explanation":["끝없이 늘여도 직선 가와 만나지 않는 직선을 찾아요.","모눈을 보면 직선 가와 직선 나는 같은 방향으로 뻗어 만나지 않아요.",