INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_c#23','math',4,2,'u2','','g4_2_math_u2_review_c','unit_review','M4-2-u2-C7',4,'sa','auto','평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 26 cm예요. 변 ㄴㄷ은 변 ㄱㄴ보다 5 cm 더 길어요. 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-2-u2-C7","difficulty":4,"kind":"sa","stem":"평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 26 cm예요. 변 ㄴㄷ은 변 ㄱㄴ보다 5 cm 더 길어요. 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["변 ㄱㄴ + 변 ㄴㄷ = 26 ÷ 2 = 13 cm예요.","두 변의 차가 5 cm이니 긴 변은 (13 + 5) ÷ 2예요.","변 ㄴㄷ = 9 cm(변 ㄱㄴ = 4 cm)예요."],"variant_rule":{"alt":[{"stem":"평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 30 cm예요. 변 ㄴㄷ은 변 ㄱㄴ보다 3 cm 더 길어요. 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["변 ㄱㄴ + 변 ㄴㄷ = 30 ÷ 2 = 15 cm예요.","두 변의 차가 3 cm이니 긴 변은 (15 + 3) ÷ 2예요.","변 ㄴㄷ = 9 cm(변 ㄱㄴ = 6 cm)예요."],"asset":null},{"stem":"평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 44 cm예요. 변 ㄴㄷ은 변 ㄱㄴ보다 6 cm 더 길어요. 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["변 ㄱㄴ + 변 ㄴㄷ = 44 ÷ 2 = 22 cm예요.","두 변의 차가 6 cm이니 긴 변은 (22 + 6) ÷ 2예요.","변 ㄴㄷ = 14 cm(변 ㄱㄴ = 8 cm)예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_c#24','math',4,2,'u2','','g4_2_math_u2_review_c','unit_review','M4-2-u2-C10',4,'sa','auto','크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합과 원 한 개의 지름을 더하면 48 cm예요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-2-u2-C10","difficulty":4,"kind":"sa","stem":"크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합과 원 한 개의 지름을 더하면 48 cm예요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["마름모의 네 변 = 반지름 4개, 지름 = 반지름 2개예요.","모두 반지름 6개가 48 cm예요.","48 ÷ 6 = 8 cm예요."],"variant_rule":{"alt":[{"stem":"크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합은 원 한 개의 지름보다 12 cm 더 길어요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["마름모의 네 변 = 반지름 4개, 지름 = 반지름 2개예요.","차이는 반지름 2개 = 12 cm예요.","12 ÷ 2 = 6 cm예요."],"asset":null},{"stem":"크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합과 원 한 개의 지름을 더하면 30 cm예요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["마름모의 네 변 = 반지름 4개, 지름 = 반지름 2개예요.","모두 반지름 6개가 30 cm예요.","30 ÷ 6 = 5 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_c#25','math',4,2,'u2','','g4_2_math_u2_review_c','unit_review','M4-2-u2-C8',4,'essay','teacher','마름모 ㄱㄴㄷㄹ에서 마주 보는 꼭짓점끼리 이은 두 선분 ㄱㄷ과 ㄴㄹ은 어떻게 만나는지 두 가지를 쓰고, 선분 ㄱㄷ이 14 cm일 때 선분 ㄱㅇ(점 ㅇ은 두 선분이 만나는 점)의 길이를 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u2-C8","difficulty":4,"kind":"essay","stem":"마름모 ㄱㄴㄷㄹ에서 마주 보는 꼭짓점끼리 이은 두 선분 ㄱㄷ과 ㄴㄹ은 어떻게 만나는지 두 가지를 쓰고, 선분 ㄱㄷ이 14 cm일 때 선분 ㄱㅇ(점 ㅇ은 두 선분이 만나는 점)의 길이를 구해 보세요.","answer_guide":{"answer":"예: 두 선분은 서로 수직으로 만나고, 서로를 똑같이 반으로 나눈다. 그래서 선분 ㄱㅇ은 선분 ㄱㄷ의 반인 14 ÷ 2 = 7 cm이다.","scoring_points":["서로 수직으로 만난다고 썼는가","서로를 반으로 나눈다고 썼는가","선분 ㄱㅇ = 7 cm를 구했는가"]},"explanation":["두 선분은 수직으로 만나요.","서로를 반으로 나눠요.","14 ÷ 2 = 7 cm."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_d#1','math',4,2,'u2','','g4_2_math_u2_review_d','unit_review','M4-2-u2-C1',1,'mc','auto','직선 나와 서로 수직인 직선은 어느 것인가요?',ARRAY['M4-2-u2-X03','M4-2-u2-X05','M4-2-u2-X01']::text[],true,'{"seq":1,"concept":"M4-2-u2-C1","difficulty":1,"kind":"mc","stem":"직선 나와 서로 수직인 직선은 어느 것인가요?","options":[{"t":"직선 가","correct":true},{"t":"직선 다","mis":"M4-2-u2-X03"},{"t":"직선 라","mis":"M4-2-u2-X05"},{"t":"수직인 직선이 없어요","mis":"M4-2-u2-X01"}],"explanation":["모눈을 따라 만나서 이루는 각이 직각인지 살펴봐요.","직선 나와 직선 가가 만나서 이루는 각이 직각이에요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,15.0],[150.0,90.0]],[[15.0,105.0],[60.0,15.0]],[[90.0,105.0],[120.0,0.0]],[[105.0,105.0],[150.0,15.0]]],"lab":[[[7.043614129124338,31.099689437998485],"가"],[[31.099689437998485,97.95638587087565],"나"],[[82.89159081565535,88.9288140180034],"다"],[[121.09968943799848,97.95638587087565],"라"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직선 가와 서로 수직인 직선은 어느 것인가요?","options":[{"t":"직선 나","correct":true},{"t":"직선 다","mis":"M4-2-u2-X03"},{"t":"직선 라","mis":"M4-2-u2-X03"},{"t":"수직인 직선이 없어요","mis":"M4-2-u2-X01"}],"explanation":["모눈을 따라 만나서 이루는 각이 직각인지 살펴봐요.","직선 가와 직선 나가 만나서 이루는 각이 직각이에요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,105.0],[105.0,0.0]],[[15.0,0.0],[120.0,105.0]],[[150.0,30.0],[60.0,105.0]],[[0.0,45.0],[150.0,45.0]]],"lab":[[[103.40900974233026,17.500892834367054],"가"],[[16.59099025766973,17.500892834367054],"나"],[[63.16891277833918,87.71502120905905],"다"],[[13.5,56.25],"라"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 직선 나와 서로 수직인 직선은 어느 것인가요?","options":[{"t":"직선 가","correct":true},{"t":"직선 다","mis":"M4-2-u2-X05"},{"t":"직선 라","mis":"M4-2-u2-X03"},{"t":"수직인 직선이 없어요","mis":"M4-2-u2-X01"}],"explanation":["모눈을 따라 만나서 이루는 각이 직각인지 살펴봐요.","직선 나와 직선 가가 만나서 이루는 각이 직각이에요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,90.0],[150.0,15.0]],[[30.0,15.0],[67.5,90.0]],[[75.0,0.0],[120.0,90.0]],[[105.0,0.0],[105.0,105.0]]],"lab":[[[17.105920027873392,94.02492235949961],"가"],[[18.47507764050038,17.105920027873392],"나"],[[70.97507764050039,17.105920027873392],"다"],[[93.75,91.5],"라"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_d#2','math',4,2,'u2','','g4_2_math_u2_review_d','unit_review','M4-2-u2-C2',1,'mc','auto','두 직선이 서로 수직인지 알아보려면 삼각자의 어느 부분을 대어 보나요?',ARRAY['M4-2-u2-X03']::text[],true,'{"seq":2,"concept":"M4-2-u2-C2","difficulty":1,"kind":"mc","stem":"두 직선이 서로 수직인지 알아보려면 삼각자의 어느 부분을 대어 보나요?","options":[{"t":"직각 부분","correct":true},{"t":"가장 긴 변","mis":"M4-2-u2-X03"},{"t":"가장 뾰족한 각 부분","mis":"M4-2-u2-X03"},{"t":"대어 보지 않고 눈으로 본다","mis":"M4-2-u2-X03"}],"explanation":["수직은 만나서 이루는 각이 직각인지로 정해요.","삼각자의 직각 부분을 대거나 각도기로 90°인지 재어 확인해요.","눈대중이나 놓인 방향으로는 정할 수 없어요."],"variant_rule":{"alt":[{"stem":"각도기로 두 직선이 서로 수직인지 알아보려면 만나서 이루는 각이 몇 도인지 보면 되나요?","options":[{"t":"90°","correct":true},{"t":"180°","mis":"M4-2-u2-X03"},{"t":"60°","mis":"M4-2-u2-X03"},{"t":"45°","mis":"M4-2-u2-X03"}],"explanation":["수직은 만나서 이루는 각이 직각인지로 정해요.","삼각자의 직각 부분을 대거나 각도기로 90°인지 재어 확인해요.","눈대중이나 놓인 방향으로는 정할 수 없어요."],"asset":null},{"stem":"주차선이 서로 수직인지 가장 바르게 확인하는 방법은 어느 것인가요?","options":[{"t":"만나는 곳에 삼각자의 직각 부분을 대어 본다","correct":true},{"t":"두 선이 반듯해 보이는지 눈으로 본다","mis":"M4-2-u2-X03"},{"t":"두 선의 길이를 자로 잰다","mis":"M4-2-u2-X02"},{"t":"한 선이 가로로 놓였는지 본다","mis":"M4-2-u2-X01"}],"explanation":["수직은 만나서 이루는 각이 직각인지로 정해요.","삼각자의 직각 부분을 대거나 각도기로 90°인지 재어 확인해요.","눈대중이나 놓인 방향으로는 정할 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_d#3','math',4,2,'u2','','g4_2_math_u2_review_d','unit_review','M4-2-u2-C3',1,'mc','auto','한 직선에 수직인 두 직선처럼, 아무리 늘여도 서로 만나지 않는 두 직선의 관계를 무엇이라고 하나요?',ARRAY['M4-2-u2-X05','M4-2-u2-X02']::text[],true,'{"seq":3,"concept":"M4-2-u2-C3","difficulty":1,"kind":"mc","stem":"한 직선에 수직인 두 직선처럼, 아무리 늘여도 서로 만나지 않는 두 직선의 관계를 무엇이라고 하나요?","options":[{"t":"평행","correct":true},{"t":"수직","mis":"M4-2-u2-X05"},{"t":"평행선","mis":"M4-2-u2-X02"},{"t":"수선","mis":"M4-2-u2-X02"}],"explanation":["한 직선에 수직인 두 직선은 아무리 늘여도 만나지 않아요.","이렇게 만나지 않는 두 직선은 서로 평행하다고 해요.","평행은 두 직선의 관계, 평행선은 평행한 두 직선을 가리키는 말이에요."],"variant_rule":{"alt":[{"stem":"서로 평행한 두 직선을 무엇이라고 하나요?","options":[{"t":"평행선","correct":true},{"t":"평행","mis":"M4-2-u2-X02"},{"t":"수선","mis":"M4-2-u2-X02"},{"t":"수직선","mis":"M4-2-u2-X02"}],"explanation":["한 직선에 수직인 두 직선은 아무리 늘여도 만나지 않아요.","이렇게 만나지 않는 두 직선은 서로 평행하다고 해요.","평행은 두 직선의 관계, 평행선은 평행한 두 직선을 가리키는 말이에요."],"asset":null},{"stem":"자전거 도로의 두 경계선은 아무리 늘여도 만나지 않아요. 두 경계선은 서로 어떤 관계인가요?","options":[{"t":"평행","correct":true},{"t":"수직","mis":"M4-2-u2-X05"},{"t":"수선","mis":"M4-2-u2-X02"},{"t":"직각","mis":"M4-2-u2-X02"}],"explanation":["한 직선에 수직인 두 직선은 아무리 늘여도 만나지 않아요.","이렇게 만나지 않는 두 직선은 서로 평행하다고 해요.","평행은 두 직선의 관계, 평행선은 평행한 두 직선을 가리키는 말이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_d#4','math',4,2,'u2','','g4_2_math_u2_review_d','unit_review','M4-2-u2-C4',1,'mc','auto','두 직선은 서로 평행해요. 평행선 사이의 거리를 나타내는 선분은 어느 것인가요?',ARRAY['M4-2-u2-X07','M4-2-u2-X08']::text[],true,'{"seq":4,"concept":"M4-2-u2-C4","difficulty":1,"kind":"mc","stem":"두 직선은 서로 평행해요. 평행선 사이의 거리를 나타내는 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㄷ","correct":true},{"t":"선분 ㄱㄴ","mis":"M4-2-u2-X07"},{"t":"선분 ㄱㄹ","mis":"M4-2-u2-X07"},{"t":"세 선분 모두","mis":"M4-2-u2-X08"}],"explanation":["평행선 사이의 거리는 한 직선에서 다른 직선에 그은 수직인 선분의 길이예요.","선분 ㄱㄷ이 아래 직선과 직각으로 만나요.","비스듬한 선분은 거리를 나타내지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"pts":{"ㄱ":[67.5,22.5],"ㄴ":[22.5,82.5],"ㄷ":[67.5,82.5],"ㄹ":[135.0,82.5]},"seg":[["ㄱ","ㄴ"],["ㄱ","ㄷ"],["ㄱ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 두 직선은 서로 평행해요. 평행선 사이의 거리를 나타내는 선분은 어느 것인가요?","options":[{"t":"선분 ㅁㅂ","correct":true},{"t":"선분 ㅁㅅ","mis":"M4-2-u2-X07"},{"t":"선분 ㅁㅇ","mis":"M4-2-u2-X07"},{"t":"세 선분 모두","mis":"M4-2-u2-X08"}],"explanation":["평행선 사이의 거리는 한 직선에서 다른 직선에 그은 수직인 선분의 길이예요.","선분 ㅁㅂ이 아래 직선과 직각으로 만나요.","비스듬한 선분은 거리를 나타내지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"pts":{"ㅁ":[52.5,22.5],"ㅂ":[52.5,82.5],"ㅅ":[112.5,82.5],"ㅇ":[7.5,82.5]},"seg":[["ㅁ","ㅂ"],["ㅁ","ㅅ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 두 직선은 서로 평행해요. 평행선 사이의 거리를 나타내는 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㅁ","correct":true},{"t":"선분 ㄱㄷ","mis":"M4-2-u2-X07"},{"t":"선분 ㄱㄹ","mis":"M4-2-u2-X07"},{"t":"세 선분 모두","mis":"M4-2-u2-X08"}],"explanation":["평행선 사이의 거리는 한 직선에서 다른 직선에 그은 수직인 선분의 길이예요.","선분 ㄱㅁ이 아래 직선과 직각으로 만나요.","비스듬한 선분은 거리를 나타내지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"pts":{"ㄱ":[90.0,22.5],"ㄷ":[135.0,82.5],"ㄹ":[30.0,82.5],"ㅁ":[90.0,82.5]},"seg":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_d#5','math',4,2,'u2','','g4_2_math_u2_review_d','unit_review','M4-2-u2-C5',1,'mc','auto','사다리꼴은 어떤 사각형인가요?',ARRAY['M4-2-u2-X09','M4-2-u2-X14','M4-2-u2-X18']::text[],true,'{"seq":5,"concept":"M4-2-u2-C5","difficulty":1,"kind":"mc","stem":"사다리꼴은 어떤 사각형인가요?","options":[{"t":"평행한 변이 한 쌍이라도 있는 사각형","correct":true},{"t":"평행한 변이 한 쌍만 있는 사각형","mis":"M4-2-u2-X09"},{"t":"네 변의 길이가 모두 같은 사각형","mis":"M4-2-u2-X14"},{"t":"평행한 변이 없는 사각형","mis":"M4-2-u2-X18"}],"explanation":["사각형을 평행한 변이 있는지로 갈라 봐요.","평행한 변이 한 쌍이라도 있으면 사다리꼴이에요.","「한 쌍만」이 아니라 「한 쌍이라도」예요."],"variant_rule":{"alt":[{"stem":"평행한 변이 한 쌍이라도 있는 사각형을 무엇이라고 하나요?","options":[{"t":"사다리꼴","correct":true},{"t":"평행사변형","mis":"M4-2-u2-X09"},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"직사각형","mis":"M4-2-u2-X10"}],"explanation":["사각형을 평행한 변이 있는지로 갈라 봐요.","평행한 변이 한 쌍이라도 있으면 사다리꼴이에요.","「한 쌍만」이 아니라 「한 쌍이라도」예요."],"asset":null},{"stem":"책장에 기대 놓은 사다리에서 찾은 사각형은 위아래 두 변이 서로 평행해요. 이런 사각형을 무엇이라고 하나요?","options":[{"t":"사다리꼴","correct":true},{"t":"평행사변형","mis":"M4-2-u2-X10"},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"정사각형","mis":"M4-2-u2-X10"}],"explanation":["사각형을 평행한 변이 있는지로 갈라 봐요.","평행한 변이 한 쌍이라도 있으면 사다리꼴이에요.","「한 쌍만」이 아니라 「한 쌍이라도」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_d#6','math',4,2,'u2','','g4_2_math_u2_review_d','unit_review','M4-2-u2-C7',1,'sa','auto','계단 난간에서 찾은 평행사변형의 한 각이 40°예요. 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u2-C7","difficulty":1,"kind":"sa","stem":"계단 난간에서 찾은 평행사변형의 한 각이 40°예요. 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["140"],"explanation":["평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","이웃한 각 = 180° − 40°.","140°예요."],"variant_rule":{"alt":[{"stem":"평행사변형에서 한 각의 크기가 125°일 때, 이 각과 이웃한 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","이웃한 각 = 180° − 125°.","55°예요."],"asset":null},{"stem":"계단 난간에서 찾은 평행사변형의 한 각이 70°예요. 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["평행사변형은 이웃한 두 각의 크기의 합이 180°예요.","이웃한 각 = 180° − 70°.","110°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_d#7','math',4,2,'u2','','g4_2_math_u2_review_d','unit_review','M4-2-u2-C8',1,'sa','auto','마름모에서 한 각의 크기가 110°일 때, 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u2-C8","difficulty":1,"kind":"sa","stem":"마름모에서 한 각의 크기가 110°일 때, 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["마름모도 마주 보는 두 쌍의 변이 평행해요 — 평행사변형이에요.","그래서 이웃한 두 각의 크기의 합이 180°예요.","180° − 110° = 70°예요."],"variant_rule":{"alt":[{"stem":"마름모에서 한 각의 크기가 65°일 때, 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["115"],"explanation":["마름모도 마주 보는 두 쌍의 변이 평행해요 — 평행사변형이에요.","그래서 이웃한 두 각의 크기의 합이 180°예요.","180° − 65° = 115°예요."],"asset":null},{"stem":"마름모에서 한 각의 크기가 130°일 때, 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["마름모도 마주 보는 두 쌍의 변이 평행해요 — 평행사변형이에요.","그래서 이웃한 두 각의 크기의 합이 180°예요.","180° − 130° = 50°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_d#8','math',4,2,'u2','','g4_2_math_u2_review_d','unit_review','M4-2-u2-C10',1,'sa','auto','크기가 같은 두 원을 그리고, 두 원의 중심 ㄱ, ㄷ과 두 원이 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 원의 반지름이 8 cm일 때 변 ㄱㄴ의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u2-C10","difficulty":1,"kind":"sa","stem":"크기가 같은 두 원을 그리고, 두 원의 중심 ㄱ, ㄷ과 두 원이 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 원의 반지름이 8 cm일 때 변 ㄱㄴ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["변 ㄱㄴ은 한 원의 중심과 원 위의 점을 이은 선분이에요.","그래서 변 ㄱㄴ은 원의 반지름이에요.","8 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[126.75000000000001,68.25,"e"],"ㄹ":[97.5,107.25,"s"]},"circle":[[[68.25,68.25],48.7],[[126.75000000000001,68.25],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[43.875,57.0],"8 cm"]],"seg":[[[68.25,68.25],[19.500000000000004,68.25]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"크기가 같은 두 원을 그리고, 두 원의 중심 ㄱ, ㄷ과 두 원이 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 원의 반지름이 5 cm일 때 변 ㄴㄷ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["변 ㄴㄷ은 한 원의 중심과 원 위의 점을 이은 선분이에요.","그래서 변 ㄴㄷ은 원의 반지름이에요.","5 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[126.75000000000001,68.25,"e"],"ㄹ":[97.5,107.25,"s"]},"circle":[[[68.25,68.25],48.7],[[126.75000000000001,68.25],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[43.875,57.0],"5 cm"]],"seg":[[[68.25,68.25],[19.500000000000004,68.25]]]}],"tag":false}},{"stem":"크기가 같은 두 원을 그리고, 두 원의 중심 ㄱ, ㄷ과 두 원이 만나는 점 ㄴ, ㄹ을 이어 마름모를 그렸어요. 원의 반지름이 6 cm일 때 변 ㄷㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["변 ㄷㄹ은 한 원의 중심과 원 위의 점을 이은 선분이에요.","그래서 변 ㄷㄹ은 원의 반지름이에요.","6 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.25,68.25,"w"],"ㄴ":[97.5,29.250000000000004,"n"],"ㄷ":[126.75000000000001,68.25,"e"],"ㄹ":[97.5,107.25,"s"]},"circle":[[[68.25,68.25],48.7],[[126.75000000000001,68.25],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[43.875,57.0],"6 cm"]],"seg":[[[68.25,68.25],[19.500000000000004,68.25]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_d#9','math',4,2,'u2','','g4_2_math_u2_review_d','unit_review','M4-2-u2-C1',2,'mc','auto','사각형 ㅁㅂㅅㅇ에서 변 ㅇㅁ과 수직인 변을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X04','M4-2-u2-X06','M4-2-u2-X03']::text[],true,'{"seq":9,"concept":"M4-2-u2-C1","difficulty":2,"kind":"mc","stem":"사각형 ㅁㅂㅅㅇ에서 변 ㅇㅁ과 수직인 변을 모두 고른 것은 어느 것인가요?","options":[{"t":"변 ㅁㅂ, 변 ㅅㅇ","correct":true},{"t":"변 ㅁㅂ","mis":"M4-2-u2-X04"},{"t":"변 ㅂㅅ","mis":"M4-2-u2-X06"},{"t":"변 ㅁㅂ, 변 ㅂㅅ, 변 ㅅㅇ","mis":"M4-2-u2-X03"}],"explanation":["변 ㅇㅁ과 만나서 이루는 각이 직각인 변을 찾아요.","변 ㅁㅂ, 변 ㅅㅇ — 모눈으로 보면 직각으로 만나요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[15.0,45.0],"ㅂ":[75.0,15.0],"ㅅ":[90.0,45.0],"ㅇ":[30.0,75.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"사각형 ㅁㅂㅅㅇ에서 변 ㅂㅅ과 수직인 변을 모두 고른 것은 어느 것인가요?","options":[{"t":"변 ㅁㅂ, 변 ㅅㅇ","correct":true},{"t":"변 ㅁㅂ","mis":"M4-2-u2-X04"},{"t":"변 ㅇㅁ","mis":"M4-2-u2-X06"},{"t":"변 ㅁㅂ, 변 ㅅㅇ, 변 ㅇㅁ","mis":"M4-2-u2-X03"}],"explanation":["변 ㅂㅅ과 만나서 이루는 각이 직각인 변을 찾아요.","변 ㅁㅂ, 변 ㅅㅇ — 모눈으로 보면 직각으로 만나요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[15.0,75.0],"ㅂ":[120.0,75.0],"ㅅ":[120.0,15.0],"ㅇ":[60.0,15.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]]}],"tag":false}},{"stem":"사각형 ㄱㄴㄷㄹ에서 변 ㄴㄷ과 수직인 변을 모두 고른 것은 어느 것인가요?","options":[{"t":"변 ㄱㄴ, 변 ㄷㄹ","correct":true},{"t":"변 ㄱㄴ","mis":"M4-2-u2-X04"},{"t":"변 ㄹㄱ","mis":"M4-2-u2-X06"},{"t":"변 ㄱㄴ, 변 ㄷㄹ, 변 ㄹㄱ","mis":"M4-2-u2-X03"}],"explanation":["변 ㄴㄷ과 만나서 이루는 각이 직각인 변을 찾아요.","변 ㄱㄴ, 변 ㄷㄹ — 모눈으로 보면 직각으로 만나요.","기울어져 있어도 직각으로 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,15.0],"ㄴ":[120.0,15.0],"ㄷ":[120.0,75.0],"ㄹ":[15.0,75.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode