 것인가요?","options":[{"t":"사다리꼴","correct":true},{"t":"사다리꼴, 평행사변형","mis":"M4-2-u2-X16"},{"t":"평행사변형, 마름모, 직사각형, 정사각형","mis":"M4-2-u2-X18"},{"t":"사다리꼴, 평행사변형, 마름모, 직사각형, 정사각형","mis":"M4-2-u2-X16"}],"explanation":["평행한 변(몇 쌍) · 변의 길이(네 변이 같은지) · 각(네 각이 직각인지)을 기준마다 따로 봐요.","이 사각형에 맞는 이름: 사다리꼴.","평행한 변이 한 쌍뿐이라 사다리꼴만 돼요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"poly":[[[15.0,75.0],[120.0,75.0],[90.0,15.0],[45.0,15.0]]],"right":[],"tick":[[[15.0,75.0],[120.0,75.0],3],[[120.0,75.0],[90.0,15.0],2],[[90.0,15.0],[45.0,15.0],1],[[45.0,15.0],[15.0,75.0],2]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_d#16','math',4,2,'u2','','g4_2_math_u2_review_d','unit_review','M4-2-u2-C10',2,'mc','auto','모눈 위의 세 점 ㄱ, ㄴ, ㄷ에 한 점을 더 이어 정사각형을 그리려고 해요. 어느 점을 이어야 하나요?',ARRAY['M4-2-u2-X16']::text[],true,'{"seq":16,"concept":"M4-2-u2-C10","difficulty":2,"kind":"mc","stem":"모눈 위의 세 점 ㄱ, ㄴ, ㄷ에 한 점을 더 이어 정사각형을 그리려고 해요. 어느 점을 이어야 하나요?","options":[{"t":"점 나","correct":true},{"t":"점 가","mis":"M4-2-u2-X16"},{"t":"점 다","mis":"M4-2-u2-X16"},{"t":"점 라","mis":"M4-2-u2-X16"}],"explanation":["정사각형의 뜻을 떠올리고, 모눈 칸을 세어 확인해요.","점 나을 이으면 정사각형의 조건(평행한 변·변의 길이·직각)이 모두 맞아요.","나머지 점은 변이 평행하지 않거나 길이·각이 맞지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":97.5,"grid":15,"pts":{"ㄱ":[45.0,7.5],"ㄴ":[90.0,37.5],"ㄷ":[60.0,82.5],"가":[45.0,52.5],"나":[15.0,52.5],"다":[15.0,22.5],"라":[15.0,82.5]},"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"모눈 위의 세 점 ㄱ, ㄴ, ㄷ에 한 점을 더 이어 평행사변형을 그리려고 해요. 어느 점을 이어야 하나요?","options":[{"t":"점 가","correct":true},{"t":"점 나","mis":"M4-2-u2-X10"},{"t":"점 다","mis":"M4-2-u2-X10"},{"t":"점 라","mis":"M4-2-u2-X10"}],"explanation":["평행사변형의 뜻을 떠올리고, 모눈 칸을 세어 확인해요.","점 가을 이으면 평행사변형의 조건(평행한 변·변의 길이·직각)이 모두 맞아요.","나머지 점은 변이 평행하지 않거나 길이·각이 맞지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[120.0,15.0],"가":[45.0,15.0],"나":[15.0,15.0],"다":[75.0,15.0],"라":[45.0,45.0]},"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"]]}],"tag":false}},{"stem":"모눈 위의 세 점 ㄱ, ㄴ, ㄷ에 한 점을 더 이어 마름모를 그리려고 해요. 어느 점을 이어야 하나요?","options":[{"t":"점 라","correct":true},{"t":"점 가","mis":"M4-2-u2-X14"},{"t":"점 나","mis":"M4-2-u2-X14"},{"t":"점 다","mis":"M4-2-u2-X14"}],"explanation":["마름모의 뜻을 떠올리고, 모눈 칸을 세어 확인해요.","점 라을 이으면 마름모의 조건(평행한 변·변의 길이·직각)이 모두 맞아요.","나머지 점은 변이 평행하지 않거나 길이·각이 맞지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[135.0,15.0],"가":[30.0,15.0],"나":[90.0,15.0],"다":[60.0,45.0],"라":[60.0,15.0]},"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_d#17','math',4,2,'u2','','g4_2_math_u2_review_d','unit_review','M4-2-u2-C2',3,'sa','auto','주차선 두 줄이 수직으로 만나는 점 ㅇ에서 비스듬한 안내선을 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M4-2-u2-C2","difficulty":3,"kind":"sa","stem":"주차선 두 줄이 수직으로 만나는 점 ㅇ에서 비스듬한 안내선을 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["두 직선이 수직이라 만나서 이루는 각은 90°예요.","90°가 35°와 ㉠으로 나뉘었어요.","㉠ = 90° − 35° = 55°예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"line":[[[30.0,90.0],[120.0,90.0]]],"ray":[[[30.0,90.0],[30.0,7.5]],[[30.0,90.0],[102.0,-17.99999999999999]]],"right":[[[75.0,90.0],[30.0,90.0],[30.0,45.0]]],"lab":[[[73.6428788753208,66.6430069684885],"㉠"],[[44.34428744253374,42.62393623604881],"35°"]],"pts":{"ㅇ":[30.0,90.0]},"show":["ㅇ"]}],"tag":false},"variant_rule":{"alt":[{"stem":"점 ㅇ에서 수직인 두 직선 사이에 반직선을 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["두 직선이 수직이라 만나서 이루는 각은 90°예요.","90°가 70°와 ㉠으로 나뉘었어요.","㉠ = 90° − 70° = 20°예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"line":[[[30.0,90.0],[120.0,90.0]]],"ray":[[[30.0,90.0],[30.0,7.5]],[[30.0,90.0],[138.0,54.0]]],"right":[[[75.0,90.0],[30.0,90.0],[30.0,45.0]]],"lab":[[[78.86117153516517,82.07308911295429],"㉠"],[[58.94489328714291,49.844761828674095],"70°"]],"pts":{"ㅇ":[30.0,90.0]},"show":["ㅇ"]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 주차선 두 줄이 수직으로 만나는 점 ㅇ에서 비스듬한 안내선을 그었어요. ㉠의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["두 직선이 수직이라 만나서 이루는 각은 90°예요.","90°가 70°와 ㉠으로 나뉘었어요.","㉠ = 90° − 70° = 20°예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"line":[[[30.0,90.0],[120.0,90.0]]],"ray":[[[30.0,90.0],[30.0,7.5]],[[30.0,90.0],[66.0,-17.99999999999999]]],"right":[[[75.0,90.0],[30.0,90.0],[30.0,45.0]]],"lab":[[[70.1552381713259,61.055106712857096],"70°"],[[37.92691088