INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_d#18','math',4,2,'u2','','g4_2_math_u2_review_d','unit_review','M4-2-u2-C4',3,'sa','auto','사다리꼴 ㅁㅂㅅㅇ에서 위아래 두 변은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-2-u2-C4","difficulty":3,"kind":"sa","stem":"사다리꼴 ㅁㅂㅅㅇ에서 위아래 두 변은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["평행한 두 변 사이의 거리는 두 변에 수직인 선분의 길이예요.","비스듬한 변(5 cm)이나 평행한 변(9 cm)의 길이가 아니에요.","점선으로 그은 수직인 선분이 4 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㅁ":[15.0,75.0],"ㅂ":[120.0,75.0],"ㅅ":[90.0,15.0],"ㅇ":[45.0,15.0]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"lab":[[[13.217694101250945,36.60884705062547],"5 cm"],[[67.5,86.25],"9 cm"],[[62.25000000000001,45.0],"4 cm"]],"dash":[[[45.0,15.0],[45.0,75.0]]],"right":[[[45.0,15.0],[45.0,75.0],[15.0,75.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"사다리꼴 ㄱㄴㄷㄹ에서 위아래 두 변은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["평행한 두 변 사이의 거리는 두 변에 수직인 선분의 길이예요.","비스듬한 변(5 cm)이나 평행한 변(7 cm)의 길이가 아니에요.","점선으로 그은 수직인 선분이 4 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[120.0,75.0],"ㄷ":[90.0,15.0],"ㄹ":[45.0,15.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[13.217694101250945,36.60884705062547],"5 cm"],[[67.5,86.25],"7 cm"],[[62.25000000000001,45.0],"4 cm"]],"dash":[[[45.0,15.0],[45.0,75.0]]],"right":[[[45.0,15.0],[45.0,75.0],[15.0,75.0]]]}],"tag":false}},{"stem":"평행사변형 ㄱㄴㄷㄹ에서 위아래 두 변은 서로 평행해요. 두 변 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["평행한 두 변 사이의 거리는 두 변에 수직인 선분의 길이예요.","비스듬한 변(5 cm)이나 평행한 변(6 cm)의 길이가 아니에요.","점선으로 그은 수직인 선분이 4 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[120.0,15.0],"ㄹ":[45.0,15.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[13.2176