INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_d#21','math',4,2,'u2','','g4_2_math_u2_review_d','unit_review','M4-2-u2-C8',3,'sa','auto','마름모 ㄱㄴㄷㄹ에서 마주 보는 꼭짓점끼리 이은 두 선분의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M4-2-u2-C8","difficulty":3,"kind":"sa","stem":"마름모 ㄱㄴㄷㄹ에서 마주 보는 꼭짓점끼리 이은 두 선분의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["두 선분은 점 ㅇ에서 서로를 반으로 나눠요.","선분 ㄱㄷ = 4 × 2 = 8 cm, 선분 ㄴㄹ = 5 × 2 = 10 cm.","8 + 10 = 18 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[60.0,7.5],"ㄴ":[105.0,45.0],"ㄷ":[60.0,82.5],"ㄹ":[15.0,45.0],"ㅇ":[60.0,45.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[60.0,45.0],"ㄴ"]],"lab":[[[70.0,18.25],"4 cm"],[[92.5,37.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 마름모 ㄱㄴㄷㄹ에서 마주 보는 꼭짓점끼리 이은 두 선분의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["두 선분은 점 ㅇ에서 서로를 반으로 나눠요.","선분 ㄱㄷ = 9 × 2 = 18 cm, 선분 ㄴㄹ = 4 × 2 = 8 cm.","18 + 8 = 26 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0],"ㄴ":[90.0,75.0],"ㄷ":[135.0,15.0],"ㄹ":[60.0,15.0],"ㅇ":[75.0,45.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[75.0,45.0],"ㄴ"]],"lab":[[[55.0,52.0],"9 cm"],[[92.5,52.0],"4 cm"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 마름모 ㄱㄴㄷㄹ에서 마주 보는 꼭짓점끼리 이은 두 선분의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["두 선분은 점 ㅇ에서 서로를 반으로 나눠요.","선분 ㄱㄷ = 6 × 2 = 12 cm, 선분 ㄴㄹ = 3 × 2 = 6 cm.","12 + 6 = 18 cm예요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,60.0],"ㄴ":[75.0,30.0],"ㄷ":[135.0,60.0],"ㄹ":[75.0,90.0],"ㅇ":[75.0,60.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ",[75.0,60.0],"ㄴ"]],"lab":[[[55.0,52.0],"6 cm"],[[85.0,37.0],"3 cm"]]}],"tag":false}}]}}':