INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_d#22','math',4,2,'u2','','g4_2_math_u2_review_d','unit_review','M4-2-u2-C9',3,'sa','auto','횡단보도 앞에 똑같은 정사각형 보도블록을 가로 4장, 세로 3장 깔았어요. 그림에서 찾을 수 있는 크고 작은 정사각형은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M4-2-u2-C9","difficulty":3,"kind":"sa","stem":"횡단보도 앞에 똑같은 정사각형 보도블록을 가로 4장, 세로 3장 깔았어요. 그림에서 찾을 수 있는 크고 작은 정사각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["작은 정사각형부터 크기별로 차례로 세요.","1칸짜리 12개 · 4칸짜리 6개 · 9칸짜리 2개.","모두 20개예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"seg":[[[15.0,15.0],[105.0,15.0]],[[15.0,37.5],[105.0,37.5]],[[15.0,60.0],[105.0,60.0]],[[15.0,82.5],[105.0,82.5]],[[15.0,15.0],[15.0,82.5]],[[37.5,15.0],[37.5,82.5]],[[60.0,15.0],[60.0,82.5]],[[82.5,15.0],[82.5,82.5]],[[105.0,15.0],[105.0,82.5]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"횡단보도 앞에 똑같은 정사각형 보도블록을 가로 3장, 세로 2장 깔았어요. 그림에서 찾을 수 있는 크고 작은 정사각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["작은 정사각형부터 크기별로 차례로 세요.","1칸짜리 6개 · 4칸짜리 2개.","모두 8개예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"seg":[[[15.0,15.0],[82.5,15.0]],[[15.0,37.5],[82.5,37.5]],[[15.0,60.0],[82.5,60.0]],[[15.0,15.0],[15.0,60.0]],[[37.5,15.0],[37.5,60.0]],[[60.0,15.0],[60.0,60.0]],[[82.5,15.0],[82.5,60.0]]]}],"tag":false}},{"stem":"횡단보도 앞에 똑같은 정사각형 보도블록을 가로 4장, 세로 2장 깔았어요. 그림에서 찾을 수 있는 크고 작은 정사각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["작은 정사각형부터 크기별로 차례로 세요.","1칸짜리 8개 · 4칸짜리 3개.","모두 11개예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"seg":[[[15.0,15.0],[105.0,15.0]],[[15.0,37.5],[105.0,37.5]],[[15.0,60.0],[105.0,60.0]],[[15.0,15.0],[15.0,60.0]],[[37.5,15.0],[37.5,60.0]],[[60.0,15.0],[60.0,60.0]],[[82.5,15.0],[82.5,60.0]],[[105.0,15.0],[105.0,60.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_d#23','math',4,2,'u2','','g4_2_math_u2_review_d','unit_review','M4-2-u2-C7',4,'sa','auto','평행사변형에서 이웃한 두 각 가운데 한 각이 다른 각보다 40° 더 커요. 큰 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-2-u2-C7","difficulty":4,"kind":"sa","stem":"평행사변형에서 이웃한 두 각 가운데 한 각이 다른 각보다 40° 더 커요. 큰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["이웃한 두 각의 합은 180°예요.","큰 각 = 작은 각 + 40° — 두 각을 합하면 작은 각 둘 + 40° = 180°.","작은 각 70°, 큰 각 110°예요."],"variant_rule":{"alt":[{"stem":"평행사변형에서 이웃한 두 각 가운데 한 각이 다른 각보다 20° 더 커요. 큰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["이웃한 두 각의 합은 180°예요.","큰 각 = 작은 각 + 20° — 두 각을 합하면 작은 각 둘 + 20° = 180°.","작은 각 80°, 큰 각 100°예요."],"asset":null},{"stem":"평행사변형에서 이웃한 두 각 가운데 한 각이 다른 각보다 60° 더 커요. 큰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["이웃한 두 각의 합은 180°예요.","큰 각 = 작은 각 + 60° — 두 각을 합하면 작은 각 둘 + 60° = 180°.","작은 각 60°, 큰 각 120°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_d#24','math',4,2,'u2','','g4_2_math_u2_review_d','unit_review','M4-2-u2-C10',4,'sa','auto','크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합은 원 한 개의 지름보다 12 cm 더 길어요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-2-u2-C10","difficulty":4,"kind":"sa","stem":"크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합은 원 한 개의 지름보다 12 cm 더 길어요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["마름모의 네 변 = 반지름 4개, 지름 = 반지름 2개예요.","차이는 반지름 2개 = 12 cm예요.","12 ÷ 2 = 6 cm예요."],"variant_rule":{"alt":[{"stem":"크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합과 원 한 개의 지름을 더하면 30 cm예요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["마름모의 네 변 = 반지름 4개, 지름 = 반지름 2개예요.","모두 반지름 6개가 30 cm예요.","30 ÷ 6 = 5 cm예요."],"asset":null},{"stem":"크기가 같은 두 원으로 마름모를 그렸어요. 마름모의 네 변의 길이의 합은 원 한 개의 지름보다 14 cm 더 길어요. 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["마름모의 네 변 = 반지름 4개, 지름 = 반지름 2개예요.","차이는 반지름 2개 = 14 cm예요.","14 ÷ 2 = 7 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u2_review_d#25','math',4,2,'u2','','g4_2_math_u2_review_d','unit_review','M4-2-u2-C10',4,'essay','teacher','반지름이 6 cm인 원과 반지름이 6 cm인 원을 겹쳐 그려 마름모를 만들었어요. 이 마름모의 네 변의 길이의 합을 구하고, 반지름이 6 cm와 4 cm인 두 원으로 그리면 왜 마름모가 되지 않는지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u2-C10","difficulty":4,"kind":"essay","stem":"반지름이 6 cm인 원과 반지름이 6 cm인 원을 겹쳐 그려 마름모를 만들었어요. 이 마름모의 네 변의 길이의 합을 구하고, 반지름이 6 cm와 4 cm인 두 원으로 그리면 왜 마름모가 되지 않는지 써 보세요.","answer_guide":{"answer":"예: 네 변이 모두 반지름 6 cm이므로 6 × 4 = 24 cm이다. 반지름이 다른 두 원으로 그리면 6 cm인 변 두 개와 4 cm인 변 두 개가 생겨 네 변의 길이가 모두 같지 않으므로 마름모가 아니다.","scoring_points":["네 변의 길이의 합 24 cm를 구했는가","반지름이 다르면 길이가 다른 변이 생긴다고 썼는가","네 변이 같지 않아 마름모가 아니라고 썼는가"]},"explanation":["네 변 = 반지름 6 cm × 4 = 24 cm.","반지름이 다르면 6 cm 두 변, 4 cm 두 변.","네 변이 같지 않아 마름모가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
